{
  "name": "GoldenDex",
  "description": "A professional localized perpetual contract exchange for gold trading on Arbitrum."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export type Language = 'en' | 'zh-CN' | 'zh-TW';

export type Theme = 'light' | 'dark';

export enum OrderSide {
  BUY = 'BUY',
  SELL = 'SELL',
}

export enum OrderType {
  MARKET = 'MARKET',
  LIMIT = 'LIMIT',
}

export enum MarginMode {
  CROSS = 'CROSS',
  ISOLATED = 'ISOLATED',
}

export interface Position {
  id: string;
  symbol: string;
  side: OrderSide;
  size: number;
  entryPrice: number;
  markPrice: number;
  leverage: number;
  margin: number;
  marginMode: MarginMode;
  pnl: number;
  pnlPercent: number;
  liquidationPrice: number;
}

export interface Order {
  id: string;
  symbol: string;
  side: OrderSide;
  type: OrderType;
  price: number;
  amount: number;
  filled: number;
  status: 'OPEN' | 'FILLED' | 'CANCELED';
  time: string;
}

export interface MarketData {
  symbol: string;
  lastPrice: number;
  markPrice: number;
  indexPrice: number;
  change24h: number;
  change24hPercent: number;
  high24h: number;
  low24h: number;
  volume24h: number; // In XAU
  turnover24h: number; // In USDC
  openInterest: number; // In USDC
  fundingRate: number;
  nextFundingTime: number; // timestamp
}

export interface Notification {
  id: string;
  type: 'success' | 'error' | 'info';
  message: string;
}

import React, { useEffect, useState } from 'react';
import { MarketData, Language } from '../types';
import { TRANSLATIONS } from '../constants';
import { TrendingUp, TrendingDown } from 'lucide-react';

interface MarketStatsProps {
  data: MarketData;
  lang: Language;
}

const StatBox: React.FC<{ label: string; value: React.ReactNode; color?: string }> = ({ label, value, color }) => (
  <div className="flex flex-col px-4 border-r border-gray-200 dark:border-dark-border last:border-0">
    <span className="text-xs text-gray-500 dark:text-gray-400 mb-1 whitespace-nowrap">{label}</span>
    <span className={`text-sm font-semibold whitespace-nowrap ${color || 'text-slate-900 dark:text-slate-100'}`}>{value}</span>
  </div>
);

export const MarketStats: React.FC<MarketStatsProps> = ({ data, lang }) => {
  const t = TRANSLATIONS[lang];
  const [timeLeft, setTimeLeft] = useState('');

  useEffect(() => {
    const timer = setInterval(() => {
      const diff = data.nextFundingTime - Date.now();
      if (diff > 0) {
        const h = Math.floor(diff / (1000 * 60 * 60));
        const m = Math.floor((diff % (1000 * 60 * 60)) / (1000 * 60));
        const s = Math.floor((diff % (1000 * 60)) / 1000);
        setTimeLeft(`${h.toString().padStart(2, '0')}:${m.toString().padStart(2, '0')}:${s.toString().padStart(2, '0')}`);
      }
    }, 1000);
    return () => clearInterval(timer);
  }, [data.nextFundingTime]);

  const isUp = data.change24h >= 0;
  const colorClass = isUp ? 'text-trade-up' : 'text-trade-down';

  return (
    <div className="flex items-center w-full overflow-x-auto py-2 bg-white dark:bg-dark-card border-b border-gray-200 dark:border-dark-border hide-scrollbar">
       {/* Ticker Logo Area */}
      <div className="flex items-center px-4 min-w-fit">
        <div className="w-8 h-8 rounded-full bg-brand-500 flex items-center justify-center mr-3 text-white font-bold text-xs">
          GOLD
        </div>
        <div>
          <h2 className="text-lg font-bold text-slate-900 dark:text-white leading-tight">{data.symbol}</h2>
          <span className="text-xs text-brand-500 font-semibold bg-brand-500/10 px-1 rounded">Perp</span>
        </div>
      </div>

      <StatBox
        label={t.lastPrice}
        value={data.lastPrice.toFixed(2)}
        color={colorClass}
      />

      <StatBox
        label={t.markPrice}
        value={data.markPrice.toFixed(2)}
      />

      <StatBox
        label={t.indexPrice}
        value={data.indexPrice.toFixed(2)}
      />

      <StatBox
        label={t.fundingRate}
        value={
          <div className="flex space-x-2">
            <span className="text-brand-500">{data.fundingRate.toFixed(4)}%</span>
            <span className="text-gray-400">/ {timeLeft}</span>
          </div>
        }
      />

      <StatBox
        label={t.change24h}
        value={
          <div className={`flex items-center space-x-1 ${colorClass}`}>
            <span>{data.change24h.toFixed(2)}</span>
            <span>/ {isUp ? '+' : ''}{data.change24hPercent.toFixed(2)}%</span>
          </div>
        }
      />

      <StatBox
        label={t.highLow24h}
        value={
          <div className="flex space-x-1">
            <span className="text-trade-up">{data.high24h.toFixed(2)}</span>
            <span className="text-gray-400">/</span>
            <span className="text-trade-down">{data.low24h.toFixed(2)}</span>
          </div>
        }
      />

      <StatBox
        label={t.volume24h}
        value={`${data.volume24h.toFixed(2)} / ${parseInt(data.turnover24h.toString()).toLocaleString()}`}
      />

      <StatBox
        label={t.openInterest}
        value={parseInt(data.openInterest.toString()).toLocaleString()}
      />
    </div>
  );
};

import React from 'react';
import { AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from 'recharts';
import { CHART_DATA } from '../constants';
import { Language } from '../types';

// NOTE: A full professional candlestick chart usually requires TradingView's Lightweight Charts library.
// For this React demo using standard libraries, we represent the price action with a sophisticated AreaChart.
// This fulfills the "K-Line" requirement visually within the constraints.

export const CandleChart: React.FC<{ lang: Language }> = ({ lang }) => {
  return (
    <div className="w-full h-full flex flex-col bg-white dark:bg-dark-bg relative">
      <div className="absolute top-4 left-4 z-10 flex space-x-4">
        <div className="flex space-x-2 bg-gray-100 dark:bg-slate-800 rounded p-1">
          {['1m', '5m', '1H', '1D'].map((tf) => (
             <button key={tf} className="px-2 py-1 text-xs font-medium text-gray-500 hover:text-brand-500 dark:hover:text-brand-500 dark:text-gray-400 hover:bg-gray-200 dark:hover:bg-slate-700 rounded transition">
               {tf}
             </button>
          ))}
        </div>
        <div className="flex items-center space-x-2 text-xs text-gray-500 dark:text-gray-400">
           <span className="cursor-pointer hover:text-brand-500">Last Price</span>
           <span className="cursor-pointer hover:text-brand-500">Mark Price</span>
        </div>
      </div>

      <div className="flex-1 w-full mt-12">
        <ResponsiveContainer width="100%" height="100%">
          <AreaChart data={CHART_DATA}>
            <defs>
              <linearGradient id="colorClose" x1="0" y1="0" x2="0" y2="1">
                <stop offset="5%" stopColor="#EAB308" stopOpacity={0.3}/>
                <stop offset="95%" stopColor="#EAB308" stopOpacity={0}/>
              </linearGradient>
            </defs>
            <CartesianGrid strokeDasharray="3 3" stroke="#334155" opacity={0.3} vertical={false} />
            <XAxis dataKey="time" hide />
            <YAxis 
              orientation="right" 
              domain={['auto', 'auto']} 
              tick={{fill: '#94a3b8', fontSize: 12}} 
              axisLine={false}
              tickLine={false}
              tickCount={6}
            />
            <Tooltip 
              contentStyle={{ backgroundColor: '#1E293B', borderColor: '#334155', color: '#f1f5f9' }}
              itemStyle={{ color: '#EAB308' }}
              formatter={(value: number) => [value.toFixed(2), 'Price']}
              labelFormatter={() => ''}
            />
            <Area 
              type="monotone" 
              dataKey="close" 
              stroke="#EAB308" 
              strokeWidth={2}
              fillOpacity={1} 
              fill="url(#colorClose)" 
            />
          </AreaChart>
        </ResponsiveContainer>
      </div>
      <div className="absolute bottom-1/2 left-1/2 transform -translate-x-1/2 -translate-y-1/2 pointer-events-none opacity-20">
         <h1 className="text-4xl font-bold text-brand-500">GoldenDex</h1>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { MOCK_ASKS, MOCK_BIDS, TRANSLATIONS } from '../constants';
import { Language } from '../types';
import { ArrowUp, ArrowDown } from 'lucide-react';

interface OrderBookProps {
  lang: Language;
  lastPrice: number;
}

const Row = ({ price, amount, total, type }: { price: number, amount: string, total: string, type: 'ask' | 'bid' }) => {
  const bgClass = type === 'ask' ? 'bg-trade-down' : 'bg-trade-up';
  const textClass = type === 'ask' ? 'text-trade-down' : 'text-trade-up';
  // Mock depth visualization
  const width = Math.min(parseInt(total) * 2, 100); 

  return (
    <div className="grid grid-cols-3 text-xs py-0.5 hover:bg-slate-100 dark:hover:bg-slate-700 cursor-pointer transition-colors relative group">
      <div 
        className={`absolute top-0 right-0 h-full opacity-10 ${bgClass}`} 
        style={{ width: `${width}%` }} 
      />
      <div className={`text-left pl-2 ${textClass} z-10 font-mono`}>{price.toFixed(2)}</div>
      <div className="text-right text-slate-700 dark:text-slate-300 z-10 font-mono">{amount}</div>
      <div className="text-right pr-2 text-slate-500 dark:text-slate-400 z-10 font-mono">{total}</div>
    </div>
  );
};

export const OrderBook: React.FC<OrderBookProps> = ({ lang, lastPrice }) => {
  const t = TRANSLATIONS[lang];
  const [tab, setTab] = useState<'book' | 'trades'>('book');

  return (
    <div className="flex flex-col h-full bg-white dark:bg-dark-card border-l border-gray-200 dark:border-dark-border">
      {/* Tabs */}
      <div className="flex border-b border-gray-200 dark:border-dark-border">
        <button 
          onClick={() => setTab('book')}
          className={`flex-1 py-2 text-sm font-medium ${tab === 'book' ? 'text-brand-500 border-b-2 border-brand-500' : 'text-gray-500 dark:text-gray-400'}`}
        >
          {t.orderBook}
        </button>
        <button 
          onClick={() => setTab('trades')}
          className={`flex-1 py-2 text-sm font-medium ${tab === 'trades' ? 'text-brand-500 border-b-2 border-brand-500' : 'text-gray-500 dark:text-gray-400'}`}
        >
          {t.recentTrades}
        </button>
      </div>

      {/* Header */}
      <div className="grid grid-cols-3 text-xs text-gray-500 dark:text-gray-400 px-2 py-2 font-semibold">
        <div className="text-left">{t.price}</div>
        <div className="text-right">{t.amount}</div>
        <div className="text-right">{t.total}</div>
      </div>

      <div className="flex-1 overflow-y-auto overflow-x-hidden relative">
        {tab === 'book' ? (
          <>
            {/* Asks */}
            <div className="flex flex-col-reverse">
              {MOCK_ASKS.map((ask, i) => (
                <Row key={`ask-${i}`} {...ask} type="ask" />
              ))}
            </div>

            {/* Current Price */}
            <div className="py-2 my-1 border-y border-gray-100 dark:border-slate-700 flex items-center justify-center space-x-2 bg-gray-50 dark:bg-slate-800/50 sticky top-0 bottom-0 z-20">
               <span className="text-lg font-bold text-trade-up dark:text-white">{lastPrice.toFixed(2)}</span>
               <ArrowUp size={16} className="text-trade-up" />
            </div>

            {/* Bids */}
            <div className="flex flex-col">
               {MOCK_BIDS.map((bid, i) => (
                <Row key={`bid-${i}`} {...bid} type="bid" />
              ))}
            </div>
          </>
        ) : (
          /* Recent Trades Mock */
          <div className="flex flex-col">
            {Array.from({length: 20}).map((_, i) => {
               const isBuy = Math.random() > 0.5;
               const price = (lastPrice + (Math.random() * 5 - 2.5)).toFixed(2);
               const amount = (Math.random() * 5).toFixed(3);
               const time = new Date().toLocaleTimeString();

               return (
                 <div key={i} className="grid grid-cols-3 text-xs py-1 hover:bg-slate-100 dark:hover:bg-slate-700">
                    <div className={`text-left pl-2 font-mono ${isBuy ? 'text-trade-up' : 'text-trade-down'}`}>
                      {price}
                    </div>
                    <div className="text-right font-mono text-slate-300">{amount}</div>
                    <div className="text-right pr-2 text-slate-500">{time}</div>
                 </div>
               )
            })}
          </div>
        )}
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { Language, MarginMode, OrderType, OrderSide } from '../types';
import { TRANSLATIONS } from '../constants';
import { Wallet, Info } from 'lucide-react';

interface TradeFormProps {
  lang: Language;
  isConnected: boolean;
  onConnect: () => void;
  onOrder: (side: OrderSide, type: OrderType, size: number, price: number, leverage: number, marginMode: MarginMode) => void;
  lastPrice: number;
}

export const TradeForm: React.FC<TradeFormProps> = ({ lang, isConnected, onConnect, onOrder, lastPrice }) => {
  const t = TRANSLATIONS[lang];
  const [side, setSide] = useState<OrderSide>(OrderSide.BUY);
  const [type, setType] = useState<OrderType>(OrderType.MARKET);
  const [marginMode, setMarginMode] = useState<MarginMode>(MarginMode.CROSS);
  const [leverage, setLeverage] = useState<number>(5);
  const [amount, setAmount] = useState<string>('');
  const [price, setPrice] = useState<string>('');

  const handleOrder = () => {
    if (!amount) return;
    onOrder(
      side,
      type,
      parseFloat(amount),
      type === OrderType.LIMIT ? parseFloat(price) : lastPrice,
      leverage,
      marginMode
    );
    setAmount('');
  };

  const calculatedPrice = type === OrderType.LIMIT && price ? parseFloat(price) : lastPrice;
  const cost = amount && calculatedPrice ? (parseFloat(amount) * calculatedPrice) / leverage : 0;

  return (
    <div className="flex flex-col h-full bg-white dark:bg-dark-card border-l border-gray-200 dark:border-dark-border p-4 overflow-y-auto">
      {/* Buy/Sell Tabs */}
      <div className="flex bg-gray-100 dark:bg-slate-800 rounded-lg p-1 mb-4">
        <button
          onClick={() => setSide(OrderSide.BUY)}
          className={`flex-1 py-2 text-sm font-bold rounded-md transition-all ${
            side === OrderSide.BUY 
              ? 'bg-trade-up text-white shadow' 
              : 'text-gray-500 dark:text-gray-400 hover:text-trade-up'
          }`}
        >
          {t.buyLong}
        </button>
        <button
          onClick={() => setSide(OrderSide.SELL)}
          className={`flex-1 py-2 text-sm font-bold rounded-md transition-all ${
            side === OrderSide.SELL 
              ? 'bg-trade-down text-white shadow' 
              : 'text-gray-500 dark:text-gray-400 hover:text-trade-down'
          }`}
        >
          {t.sellShort}
        </button>
      </div>

      {/* Margin Mode & Leverage Display */}
      <div className="flex items-center justify-between mb-4">
        <select 
          value={marginMode}
          onChange={(e) => setMarginMode(e.target.value as MarginMode)}
          className="bg-gray-50 dark:bg-slate-800 border-none rounded text-xs font-medium px-2 py-1 text-slate-700 dark:text-slate-300 focus:ring-1 focus:ring-brand-500 outline-none"
        >
          <option value={MarginMode.CROSS}>{t.cross}</option>
          <option value={MarginMode.ISOLATED}>{t.isolated}</option>
        </select>
        <div className="text-xs font-bold text-slate-700 dark:text-slate-300 bg-gray-100 dark:bg-slate-700 px-2 py-1 rounded">
          {leverage}x
        </div>
      </div>

      {/* Order Type */}
      <div className="flex space-x-4 mb-4 text-sm font-medium border-b border-gray-200 dark:border-dark-border pb-2">
        <button 
          onClick={() => setType(OrderType.MARKET)}
          className={`${type === OrderType.MARKET ? 'text-brand-500' : 'text-gray-500 dark:text-gray-400'}`}
        >
          {t.market}
        </button>
        <button 
          onClick={() => setType(OrderType.LIMIT)}
          className={`${type === OrderType.LIMIT ? 'text-brand-500' : 'text-gray-500 dark:text-gray-400'}`}
        >
          {t.limit}
        </button>
      </div>

      {/* Price Input (Limit) */}
      {type === OrderType.LIMIT && (
        <div className="mb-3">
          <label className="text-xs text-gray-500 dark:text-gray-400 mb-1 block">{t.price} (USDC)</label>
          <div className="relative">
            <input
              type="number"
              value={price}
              onChange={(e) => setPrice(e.target.value)}
              placeholder={lastPrice.toFixed(2)}
              className="w-full bg-gray-50 dark:bg-slate-800 border border-gray-200 dark:border-slate-700 rounded p-2 text-sm text-slate-900 dark:text-slate-200 focus:border-brand-500 outline-none transition"
            />
          </div>
        </div>
      )}

      {/* Amount Input */}
      <div className="mb-4">
        <label className="text-xs text-gray-500 dark:text-gray-400 mb-1 block">{t.amount} (XAU)</label>
        <div className="relative">
          <input
            type="number"
            value={amount}
            onChange={(e) => setAmount(e.target.value)}
            placeholder="0.00"
            className="w-full bg-gray-50 dark:bg-slate-800 border border-gray-200 dark:border-slate-700 rounded p-2 text-sm text-slate-900 dark:text-slate-200 focus:border-brand-500 outline-none transition"
          />
          <span className="absolute right-3 top-2 text-xs text-gray-400">XAU</span>
        </div>
      </div>

      {/* Leverage Slider */}
      <div className="mb-6">
        <div className="flex justify-between text-xs text-gray-500 dark:text-gray-400 mb-2">
          <span>{t.leverage}</span>
          <span>{leverage}x</span>
        </div>
        <input
          type="range"
          min="1"
          max="20"
          step="1"
          value={leverage}
          onChange={(e) => setLeverage(parseInt(e.target.value))}
          className="w-full h-1.5 bg-gray-200 dark:bg-slate-700 rounded-lg appearance-none cursor-pointer accent-brand-500"
        />
        <div className="flex justify-between mt-1 text-[10px] text-gray-400">
          <span>1x</span>
          <span>5x</span>
          <span>10x</span>
          <span>15x</span>
          <span>20x</span>
        </div>
      </div>

      {/* Info Rows */}
      <div className="space-y-2 mb-6 text-xs">
        <div className="flex justify-between">
           <span className="text-gray-500 dark:text-gray-400">{t.avail}</span>
           <span className="text-slate-900 dark:text-slate-200">10,000.00 USDC</span>
        </div>
        <div className="flex justify-between">
           <span className="text-gray-500 dark:text-gray-400">{t.cost}</span>
           <span className="text-slate-900 dark:text-slate-200">{cost.toFixed(2)} USDC</span>
        </div>
         <div className="flex justify-between">
           <span className="text-gray-500 dark:text-gray-400 flex items-center">{t.liqPrice} <Info size={10} className="ml-1"/></span>
           <span className="text-brand-500">--</span>
        </div>
      </div>

      {/* Action Button */}
      {!isConnected ? (
        <button 
          onClick={onConnect}
          className="w-full py-3 bg-brand-500 hover:bg-brand-600 text-white font-bold rounded-lg transition-colors flex items-center justify-center space-x-2"
        >
          <Wallet size={18} />
          <span>{t.connectWallet}</span>
        </button>
      ) : (
        <button
          onClick={handleOrder}
          disabled={!amount}
          className={`w-full py-3 font-bold rounded-lg transition-colors text-white ${
            !amount 
             ? 'bg-gray-300 dark:bg-slate-700 cursor-not-allowed text-gray-500' 
             : side === OrderSide.BUY 
                ? 'bg-trade-up hover:bg-green-600' 
                : 'bg-trade-down hover:bg-red-600'
          }`}
        >
          {side === OrderSide.BUY ? t.buyLong : t.sellShort}
        </button>
      )}
    </div>
  );
};

import React, { useState } from 'react';
import { Position, Order, Language, MarginMode } from '../types';
import { TRANSLATIONS } from '../constants';
import { XCircle, Edit3, Trash2 } from 'lucide-react';

interface PositionTableProps {
  positions: Position[];
  orders: Order[];
  lang: Language;
  onClosePosition: (id: string) => void;
  onCancelOrder: (id: string) => void;
  onEditMargin: (position: Position) => void;
  onCloseAll: () => void;
  onCancelAll: () => void;
}

export const PositionTable: React.FC<PositionTableProps> = ({ 
  positions, 
  orders, 
  lang, 
  onClosePosition, 
  onCancelOrder,
  onEditMargin,
  onCloseAll,
  onCancelAll
}) => {
  const t = TRANSLATIONS[lang];
  const [activeTab, setActiveTab] = useState<'positions' | 'orders' | 'history' | 'trades' | 'assets'>('positions');

  return (
    <div className="flex flex-col h-full bg-white dark:bg-dark-card border-t border-gray-200 dark:border-dark-border">
      {/* Tabs Row */}
      <div className="flex items-center justify-between px-4 border-b border-gray-200 dark:border-dark-border">
        <div className="flex space-x-6">
          {[
            { id: 'positions', label: t.positions },
            { id: 'orders', label: t.openOrders },
            { id: 'history', label: t.history },
            { id: 'trades', label: t.tradeHistory },
            { id: 'assets', label: t.assetsHistory },
          ].map(tab => (
            <button
              key={tab.id}
              onClick={() => setActiveTab(tab.id as any)}
              className={`py-3 text-sm font-medium border-b-2 transition-colors ${
                activeTab === tab.id 
                  ? 'border-brand-500 text-brand-500' 
                  : 'border-transparent text-gray-500 dark:text-gray-400 hover:text-slate-900 dark:hover:text-slate-200'
              }`}
            >
              {tab.label}
              {(tab.id === 'positions' && positions.length > 0) && ` (${positions.length})`}
              {(tab.id === 'orders' && orders.length > 0) && ` (${orders.length})`}
            </button>
          ))}
        </div>

        {/* Bulk Actions */}
        <div className="flex space-x-3">
          {activeTab === 'positions' && positions.length > 0 && (
            <button 
              onClick={onCloseAll}
              className="text-xs text-trade-down hover:bg-trade-down/10 px-2 py-1 rounded transition-colors"
            >
              {t.closeAll}
            </button>
          )}
          {activeTab === 'orders' && orders.length > 0 && (
             <button 
              onClick={onCancelAll}
              className="text-xs text-trade-down hover:bg-trade-down/10 px-2 py-1 rounded transition-colors"
             >
              {t.cancelAll}
            </button>
          )}
        </div>
      </div>

      {/* Content Area */}
      <div className="flex-1 overflow-auto p-4 min-h-[200px]">
        {activeTab === 'positions' && (
          <table className="w-full text-left text-sm">
            <thead>
              <tr className="text-gray-500 dark:text-gray-400 border-b border-gray-200 dark:border-slate-700">
                <th className="pb-2 font-medium pl-2">{t.symbol}</th>
                <th className="pb-2 font-medium">{t.leverage}</th>
