                    <div className="text-xs">{pos.pnlPercent >= 0 ? '+' : ''}{pos.pnlPercent.toFixed(2)}%</div>
                  </td>
                  <td className="py-3 text-right pr-2">
                    <button 
                      onClick={() => onClosePosition(pos.id)}
