                    >
                      {t.market}
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        )}

        {activeTab === 'orders' && (
           <table className="w-full text-left text-sm">
            <thead>
              <tr className="text-gray-500 dark:text-gray-400 border-b border-gray-200 dark:border-slate-700">
                <th className="pb-2 font-medium pl-2">{t.symbol}</th>
                <th className="pb-2 font-medium">{t.limit} / {t.market}</th>
                <th className="pb-2 font-medium">{t.price}</th>
                <th className="pb-2 font-medium">{t.amount}</th>
                <th className="pb-2 font-medium">{t.total}</th>
                <th className="pb-2 font-medium text-right pr-2">{t.action}</th>
              </tr>
            </thead>
            <tbody className="text-slate-700 dark:text-slate-300">
               {orders.length === 0 ? (
                <tr><td colSpan={6} className="text-center py-8 text-gray-500">No Open Orders</td></tr>
              ) : orders.map((order) => (
                <tr key={order.id} className="border-b border-gray-100 dark:border-slate-800">
                  <td className="py-3 pl-2">
                     <span className={order.side === 'BUY' ? 'text-trade-up' : 'text-trade-down'}>{order.side}</span> {order.symbol}
                  </td>
                  <td className="py-3">{order.type}</td>
                  <td className="py-3">{order.price.toFixed(2)}</td>
                  <td className="py-3">{order.amount}</td>
                  <td className="py-3">{(order.price * order.amount).toFixed(2)}</td>
                  <td className="py-3 text-right pr-2">
                    <button onClick={() => onCancelOrder(order.id)} className="text-trade-down hover:text-red-400">
                      <Trash2 size={16} />
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        )}

        {(activeTab === 'history' || activeTab === 'trades' || activeTab === 'assets') && (
          <div className="flex items-center justify-center h-32 text-gray-500">
            No Records
          </div>
        )}
      </div>
    </div>
  );
};

