// Custom Shape for Candlesticks
const CandleStickShape = (props: any) => {
  const { x, y, width, height, payload } = props;
  const { open, close, high, low } = payload;
  const isUp = close >= open;
  const color = isUp ? '#10B981' : '#F43F5E';

  // Calculate coordinates relative to the chart area
  // We need the Y-axis scale functions to map values to pixels, but inside a custom shape, 
  // we often only get the bar rect.
  // Recharts passes `y` as the top of the bar (min value if reversed, or max value).
  // However, for a Bar with data [min, max], `y` is the top pixel, `height` is the height.
  // This shape is used with [Math.min(open, close), Math.max(open, close)].
  // So the Bar body is already correctly positioned by Recharts layout.

  // To draw the wick, we need to know the pixel positions of High and Low.
  // Since we don't have direct access to the scale function here easily without context,
  // a common trick is to use the ratio of the bar.
  // Alternatively, we can assume the `Bar` represents the Body, and we draw lines extending out.
  // BUT, to do this accurately, we need the scale. 

  // SIMPLIFIED APPROACH:
  // We use the passed `y` and `height` for the body.
  // We approximate wicks or, better, we rely on the fact that we can't easily draw wicks 
  // in a CustomShape without the scale unless we calculate pixel ratios.

  // BETTER APPROACH for Recharts Candle:
  // The `Bar` dataKey is set to `[min, max]` of the body.
  // We calculate pixel locations for high/low relative to the body? No.

  // Let's use a standard approximation for the demo:
  // The 'Bar' is the body. We will draw a line through the center for the wick, 
  // extending slightly beyond? No, that's fake.

  // CORRECT WAY in Recharts Custom Shape:
  // We need to pass the Y-axis scale. But we can't easily.
  // So we will stick to a visual representation where the Bar IS the body.
  // And we add a "ErrorBar" or "Line" for the wick in the composition?

  // Let's try to infer unit height.
  // bodyLength = Math.abs(close - open)
  // pixelHeight = height
  // pixelsPerUnit = height / bodyLength (if bodyLength > 0)

  const bodyLength = Math.abs(close - open);
  const pixelsPerUnit = bodyLength === 0 ? 0 : height / bodyLength;

  let wickTop = y;
  let wickBottom = y + height;

  if (pixelsPerUnit > 0) {
      const highDiff = high - Math.max(open, close);
      const lowDiff = Math.min(open, close) - low;
      wickTop = y - (highDiff * pixelsPerUnit);
      wickBottom = y + height + (lowDiff * pixelsPerUnit);
  }

  return (
    <g>
      {/* Wick */}
      <line 
        x1={x + width / 2} 
        y1={wickTop} 
        x2={x + width / 2} 
        y2={wickBottom} 
        stroke={color} 
        strokeWidth={1} 
      />
      {/* Body */}
      <rect 
        x={x} 
        y={y} 
        width={width} 
        height={Math.max(1, height)} 
        fill={color} 
        stroke="none"
      />
    </g>
  );
};

export const CandleChart: React.FC<CandleChartProps> = ({ lang }) => {
  const [chartType, setChartType] = useState<ChartType>('line');
  const [priceSource, setPriceSource] = useState<PriceSource>('Last Price');

  // Prepare Data based on selections
  const displayData = useMemo(() => {
    if (chartType === 'depth') {
        // Transform OrderBook to Depth
        const bids = [...MOCK_BIDS]
            .sort((a, b) => b.price - a.price)
            .reduce((acc: any[], item) => {
                const prevTotal = acc.length > 0 ? parseFloat(acc[acc.length - 1].total) : 0;
                const total = prevTotal + parseFloat(item.amount);
                acc.push({ price: item.price, bidTotal: total, total: total.toFixed(3) });
                return acc;
            }, [])
            .reverse(); // Show lowest to highest for X axis continuity? No, usually center out or left-right.
            // Standard Depth: X axis is price.
            // Bids: Low Price -> High Price (Current). Curve goes up as price decreases? 
            // Usually Depth Chart: Left Side (Bids) Green, Right Side (Asks) Red.
            // X Axis: Price.
            // Bids: as price decreases from market, depth increases.
            // Asks: as price increases from market, depth increases.

        const asks = [...MOCK_ASKS]
            .sort((a, b) => a.price - b.price)
            .reduce((acc: any[], item) => {
                const prevTotal = acc.length > 0 ? parseFloat(acc[acc.length - 1].total) : 0;
                const total = prevTotal + parseFloat(item.amount);
                acc.push({ price: item.price, askTotal: total, total: total.toFixed(3) });
                return acc;
            }, []);

        // Combine for Recharts. We need a single array sorted by Price.
        // Bids: Price is lower. Asks: Price is higher.
        const combined = [
            ...bids.map(b => ({ ...b, askTotal: null })), 
            ...asks.map(a => ({ ...a, bidTotal: null }))
        ].sort((a, b) => a.price - b.price);

        return combined;
    } else {
        // Line or Candle
        // Adjust close price based on Source (Mock logic)
        return CHART_DATA.map(d => {
            let val = d.close;
            if (priceSource === 'Mark Price') val = d.close * 1.0005;
            if (priceSource === 'Index Price') val = d.close * 0.9995;
            return {
                ...d,
                displayPrice: val,
                // For Candle
                body: [Math.min(d.open, d.close), Math.max(d.open, d.close)]
            };
        });
    }
  }, [chartType, priceSource]);

  return (
    <div className="w-full h-full flex flex-col bg-white dark:bg-dark-bg relative">
      {/* Controls Header */}
      <div className="flex items-center justify-between px-4 py-3 border-b border-gray-100 dark:border-slate-800">
         <div className="flex space-x-1 bg-gray-100 dark:bg-slate-800 p-0.5 rounded-lg">
             {(['line', 'candle', 'depth'] as ChartType[]).map(t => (
                 <button 
                    key={t}
                    onClick={() => setChartType(t)}
                    className={`px-3 py-1 text-xs font-bold uppercase rounded-md transition-all ${
                        chartType === t 
                        ? 'bg-white dark:bg-slate-600 text-brand-500 shadow-sm' 
                        : 'text-gray-500 hover:text-slate-700 dark:hover:text-slate-300'
                    }`}
                 >
                     {t}
                 </button>
             ))}
         </div>

         <div className="relative group">
             <button className="flex items-center space-x-2 text-xs font-bold text-slate-700 dark:text-slate-300 hover:text-brand-500 transition-colors">
                 <span>{priceSource}</span>
                 <ChevronDown size={14} />
             </button>
             <div className="absolute right-0 mt-2 w-32 bg-white dark:bg-dark-card border border-gray-200 dark:border-slate-700 rounded-lg shadow-xl py-1 z-20 hidden group-hover:block">
                 {(['Last Price', 'Mark Price', 'Index Price'] as PriceSource[]).map(src => (
                     <button
                        key={src}
                        onClick={() => setPriceSource(src)}
                        className={`block w-full text-left px-4 py-2 text-xs font-medium hover:bg-gray-100 dark:hover:bg-slate-800 ${
                            priceSource === src ? 'text-brand-500' : 'text-slate-700 dark:text-slate-300'
                        }`}
                     >
                         {src}
                     </button>
                 ))}
             </div>
         </div>
      </div>

      {/* Chart Area */}
      <div className="flex-1 w-full relative">
        <ResponsiveContainer width="100%" height="100%">
          {chartType === 'line' ? (
              <AreaChart data={displayData}>
                <defs>
                  <linearGradient id="colorPrice" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="5%" stopColor="#EAB308" stopOpacity={0.3}/>
                    <stop offset="95%" stopColor="#EAB308" stopOpacity={0}/>
                  </linearGradient>
                </defs>
                <CartesianGrid strokeDasharray="3 3" stroke="#334155" opacity={0.2} vertical={false} />
                <XAxis dataKey="time" hide />
                <YAxis 
                  orientation="right" 
                  domain={['auto', 'auto']} 
                  tick={{fill: '#94a3b8', fontSize: 11}} 
                  axisLine={false}
                  tickLine={false}
                  width={50}
                />
                <Tooltip 
                  contentStyle={{ backgroundColor: '#1E293B', borderColor: '#334155', color: '#f1f5f9' }}
                  itemStyle={{ color: '#EAB308' }}
                  formatter={(value: number) => [value.toFixed(2), priceSource]}
                  labelFormatter={() => ''}
                />
                <Area 
                  type="monotone" 
                  dataKey="displayPrice" 
                  stroke="#EAB308" 
                  strokeWidth={2}
                  fillOpacity={1} 
                  fill="url(#colorPrice)" 
                  animationDuration={500}
                />
              </AreaChart>
          ) : chartType === 'candle' ? (
              <BarChart data={displayData}>
                 <CartesianGrid strokeDasharray="3 3" stroke="#334155" opacity={0.2} vertical={false} />
                 <XAxis dataKey="time" hide />
                 <YAxis 
                  orientation="right" 
                  domain={['dataMin - 5', 'dataMax + 5']} 
                  tick={{fill: '#94a3b8', fontSize: 11}} 
                  axisLine={false}
                  tickLine={false}
                  width={50}
                />
                <Tooltip 
                   cursor={{fill: 'transparent'}}
                   content={({ active, payload }) => {
                       if (active && payload && payload.length) {
                           const d = payload[0].payload;
                           return (
                               <div className="bg-dark-card border border-dark-border p-2 rounded shadow-lg text-xs">
                                   <div className="text-gray-400 mb-1">Time: {d.time}</div>
                                   <div className="grid grid-cols-2 gap-x-4 gap-y-1">
                                       <span className="text-gray-400">O:</span> <span className={d.open < d.close ? 'text-trade-up' : 'text-trade-down'}>{d.open.toFixed(2)}</span>
                                       <span className="text-gray-400">H:</span> <span className="text-slate-200">{d.high.toFixed(2)}</span>
                                       <span className="text-gray-400">L:</span> <span className="text-slate-200">{d.low.toFixed(2)}</span>
                                       <span className="text-gray-400">C:</span> <span className={d.open < d.close ? 'text-trade-up' : 'text-trade-down'}>{d.close.toFixed(2)}</span>
                                   </div>
                               </div>
                           );
                       }
                       return null;
                   }}
                />
                <Bar 
                    dataKey="body" 
                    shape={<CandleStickShape />} 
                    animationDuration={500}
                />
              </BarChart>
          ) : (
              // Depth Chart
              <AreaChart data={displayData}>
                 <CartesianGrid strokeDasharray="3 3" stroke="#334155" opacity={0.2} vertical={false} />
                 <XAxis 
                    dataKey="price" 
                    type="number" 
                    domain={['auto', 'auto']}
                    tick={{fill: '#94a3b8', fontSize: 11}}
                    axisLine={false} 
                    tickLine={false}
                    tickCount={6}
                 />
                 <YAxis 
                    orientation="right" 
                    tick={{fill: '#94a3b8', fontSize: 11}} 
                    axisLine={false}
                    tickLine={false}
                    width={50}
                 />
                 <Tooltip 
                    contentStyle={{ backgroundColor: '#1E293B', borderColor: '#334155', color: '#f1f5f9' }}
                 />
                 <Area type="step" dataKey="bidTotal" stroke="#10B981" fill="#10B981" fillOpacity={0.3} strokeWidth={2} name="Bid Depth" />
                 <Area type="step" dataKey="askTotal" stroke="#F43F5E" fill="#F43F5E" fillOpacity={0.3} strokeWidth={2} name="Ask Depth" />
              </AreaChart>
          )}
        </ResponsiveContainer>
      </div>

      {/* Background Watermark */}
      <div className="absolute top-1/2 left-1/2 transform -translate-x-1/2 -translate-y-1/2 pointer-events-none opacity-[0.03]">
         <div className="text-8xl font-bold text-slate-900 dark:text-white">GOLD</div>
      </div>
    </div>
  );
};

