import React, { useState, useMemo } from 'react';
import { AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, BarChart, Bar } from 'recharts';
import { CHART_DATA, MOCK_ASKS, MOCK_BIDS, TRANSLATIONS, TIMEFRAMES } from '../constants';
import { Language } from '../types';
import { ChevronDown, LineChart as LineIcon, BarChart2, Layers } from 'lucide-react';

type ChartType = 'line' | 'candle' | 'depth';
type PriceSourceKey = 'lastPrice' | 'markPrice' | 'indexPrice';

interface CandleChartProps {
  lang: Language;
}

const CandleStickShape = (props: any) => {
  const { x, y, width, height, payload } = props;
  const { open, close, high, low } = payload;
  const isUp = close >= open;
  const color = isUp ? '#10B981' : '#F43F5E';

  const bodyLength = Math.abs(close - open);
  const pixelsPerUnit = bodyLength === 0 ? 0 : height / bodyLength;

  let wickTop = y;
  let wickBottom = y + height;

  if (pixelsPerUnit > 0) {
      const highDiff = high - Math.max(open, close);
      const lowDiff = Math.min(open, close) - low;
      wickTop = y - (highDiff * pixelsPerUnit);
      wickBottom = y + height + (lowDiff * pixelsPerUnit);
  }

  return (
    <g>
      <line x1={x + width / 2} y1={wickTop} x2={x + width / 2} y2={wickBottom} stroke={color} strokeWidth={1} />
      <rect x={x} y={y} width={width} height={Math.max(1, height)} fill={color} stroke="none"/>
    </g>
  );
};

export const CandleChart: React.FC<CandleChartProps> = ({ lang }) => {
  const t = TRANSLATIONS[lang];
  const [chartType, setChartType] = useState<ChartType>('candle');
  const [timeframe, setTimeframe] = useState('15m');
  const [priceSourceKey, setPriceSourceKey] = useState<PriceSourceKey>('lastPrice');

  const displayData = useMemo(() => {
    if (chartType === 'depth') {
        const bids = [...MOCK_BIDS]
            .sort((a, b) => b.price - a.price)
            .reduce((acc: any[], item) => {
                const prevTotal = acc.length > 0 ? parseFloat(acc[acc.length - 1].total) : 0;
                const total = prevTotal + parseFloat(item.amount);
                acc.push({ price: item.price, bidTotal: total, total: total.toFixed(3) });
                return acc;
            }, [])
            .reverse();

        const asks = [...MOCK_ASKS]
            .sort((a, b) => a.price - b.price)
            .reduce((acc: any[], item) => {
                const prevTotal = acc.length > 0 ? parseFloat(acc[acc.length - 1].total) : 0;
                const total = prevTotal + parseFloat(item.amount);
                acc.push({ price: item.price, askTotal: total, total: total.toFixed(3) });
                return acc;
            }, []);

        const combined = [
            ...bids.map(b => ({ ...b, askTotal: null })), 
            ...asks.map(a => ({ ...a, bidTotal: null }))
        ].sort((a, b) => a.price - b.price);

        return combined;
    } else {
        return CHART_DATA.map(d => {
            let val = d.close;
            if (priceSourceKey === 'markPrice') val = d.close * 1.0005;
            if (priceSourceKey === 'indexPrice') val = d.close * 0.9995;
            return {
                ...d,
                displayPrice: val,
                body: [Math.min(d.open, d.close), Math.max(d.open, d.close)]
            };
        });
    }
  }, [chartType, priceSourceKey]);

  return (
    <div className="w-full h-full flex flex-col bg-white dark:bg-dark-bg relative">
      {/* Controls Header */}
      <div className="flex items-center justify-between px-4 py-2 border-b border-gray-100 dark:border-slate-800">
         {/* Timeframes */}
         <div className="flex space-x-1 overflow-x-auto hide-scrollbar mr-2">
           {TIMEFRAMES.map(tf => (
             <button
               key={tf}
               onClick={() => setTimeframe(tf)}
               className={`px-2 py-1 text-xs font-medium rounded transition-colors whitespace-nowrap ${
                 timeframe === tf 
                   ? 'text-brand-500 bg-brand-500/10' 
                   : 'text-gray-500 hover:text-slate-900 dark:text-gray-400 dark:hover:text-slate-200'
               }`}
             >
               {tf}
             </button>
           ))}
         </div>

         <div className="flex items-center space-x-3 shrink-0">
             {/* Chart Type Icons */}
             <div className="flex bg-gray-100 dark:bg-slate-800 rounded p-0.5">
               <button onClick={() => setChartType('line')} className={`p-1.5 rounded ${chartType === 'line' ? 'bg-white dark:bg-slate-600 text-brand-500 shadow' : 'text-gray-400'}`}>
                 <LineIcon size={14} />
               </button>
               <button onClick={() => setChartType('candle')} className={`p-1.5 rounded ${chartType === 'candle' ? 'bg-white dark:bg-slate-600 text-brand-500 shadow' : 'text-gray-400'}`}>
                 <BarChart2 size={14} />
               </button>
               <button onClick={() => setChartType('depth')} className={`p-1.5 rounded ${chartType === 'depth' ? 'bg-white dark:bg-slate-600 text-brand-500 shadow' : 'text-gray-400'}`}>
                 <Layers size={14} />
               </button>
             </div>

             {/* Price Source Dropdown */}
             <div className="relative group">
                 <button className="flex items-center space-x-1 text-xs font-bold text-slate-700 dark:text-slate-300 hover:text-brand-500 transition-colors">
                     <span>{t[priceSourceKey]}</span>
                     <ChevronDown size={14} />
                 </button>
                 <div className="absolute right-0 mt-2 w-32 bg-white dark:bg-dark-card border border-gray-200 dark:border-slate-700 rounded-lg shadow-xl py-1 z-20 hidden group-hover:block">
                     {(['lastPrice', 'markPrice', 'indexPrice'] as PriceSourceKey[]).map(key => (
                         <button
                            key={key}
                            onClick={() => setPriceSourceKey(key)}
                            className={`block w-full text-left px-4 py-2 text-xs font-medium hover:bg-gray-100 dark:hover:bg-slate-800 ${
                                priceSourceKey === key ? 'text-brand-500' : 'text-slate-700 dark:text-slate-300'
                            }`}
                         >
                             {t[key]}
                         </button>
                     ))}
                 </div>
             </div>
         </div>
      </div>

      {/* Chart Area */}
      <div className="flex-1 w-full relative">
        <ResponsiveContainer width="100%" height="100%">
          {chartType === 'line' ? (
              <AreaChart data={displayData}>
                <defs>
                  <linearGradient id="colorPrice" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="5%" stopColor="#EAB308" stopOpacity={0.3}/>
                    <stop offset="95%" stopColor="#EAB308" stopOpacity={0}/>
                  </linearGradient>
                </defs>
                <CartesianGrid strokeDasharray="3 3" stroke="#334155" opacity={0.2} vertical={false} />
                <XAxis dataKey="time" hide />
                <YAxis orientation="right" domain={['auto', 'auto']} tick={{fill: '#94a3b8', fontSize: 11}} axisLine={false} tickLine={false} width={50} />
                <Tooltip 
                  contentStyle={{ backgroundColor: '#1E293B', borderColor: '#334155', color: '#f1f5f9' }}
                  itemStyle={{ color: '#EAB308' }}
                  formatter={(value: number) => [value.toFixed(2), t[priceSourceKey]]}
                  labelFormatter={() => ''}
                />
                <Area type="monotone" dataKey="displayPrice" stroke="#EAB308" strokeWidth={2} fillOpacity={1} fill="url(#colorPrice)" animationDuration={0} isAnimationActive={false} />
              </AreaChart>
          ) : chartType === 'candle' ? (
              <BarChart data={displayData}>
                 <CartesianGrid strokeDasharray="3 3" stroke="#334155" opacity={0.2} vertical={false} />
                 <XAxis dataKey="time" hide />
                 <YAxis orientation="right" domain={['dataMin - 5', 'dataMax + 5']} tick={{fill: '#94a3b8', fontSize: 11}} axisLine={false} tickLine={false} width={50} />
                 <Tooltip cursor={{fill: 'transparent'}} content={<CustomTooltip />} />
                 <Bar dataKey="body" shape={<CandleStickShape />} animationDuration={0} isAnimationActive={false} />
              </BarChart>
          ) : (
              <AreaChart data={displayData}>
                 <CartesianGrid strokeDasharray="3 3" stroke="#334155" opacity={0.2} vertical={false} />
                 <XAxis dataKey="price" type="number" domain={['auto', 'auto']} tick={{fill: '#94a3b8', fontSize: 11}} axisLine={false} tickLine={false} tickCount={6} />
                 <YAxis orientation="right" tick={{fill: '#94a3b8', fontSize: 11}} axisLine={false} tickLine={false} width={50} />
                 <Tooltip contentStyle={{ backgroundColor: '#1E293B', borderColor: '#334155', color: '#f1f5f9' }} />
                 <Area type="step" dataKey="bidTotal" stroke="#10B981" fill="#10B981" fillOpacity={0.3} strokeWidth={2} name="Bid Depth" animationDuration={0} isAnimationActive={false} />
                 <Area type="step" dataKey="askTotal" stroke="#F43F5E" fill="#F43F5E" fillOpacity={0.3} strokeWidth={2} name="Ask Depth" animationDuration={0} isAnimationActive={false} />
              </AreaChart>
          )}
        </ResponsiveContainer>
      </div>

      {/* Background Watermark */}
      <div className="absolute top-1/2 left-1/2 transform -translate-x-1/2 -translate-y-1/2 pointer-events-none opacity-[0.03]">
         <div className="text-8xl font-bold text-slate-900 dark:text-white">GOLD</div>
      </div>
    </div>
  );
};

const CustomTooltip = ({ active, payload }: any) => {
   if (active && payload && payload.length) {
       const d = payload[0].payload;
       return (
           <div className="bg-dark-card border border-dark-border p-2 rounded shadow-lg text-xs">
               <div className="text-gray-400 mb-1">Time: {d.time}</div>
               <div className="grid grid-cols-2 gap-x-4 gap-y-1">
                   <span className="text-gray-400">O:</span> <span className={d.open < d.close ? 'text-trade-up' : 'text-trade-down'}>{d.open.toFixed(2)}</span>
                   <span className="text-gray-400">H:</span> <span className="text-slate-200">{d.high.toFixed(2)}</span>
                   <span className="text-gray-400">L:</span> <span className="text-slate-200">{d.low.toFixed(2)}</span>
                   <span className="text-gray-400">C:</span> <span className={d.open < d.close ? 'text-trade-up' : 'text-trade-down'}>{d.close.toFixed(2)}</span>
               </div>
           </div>
       );
   }
   return null;
};

import React, { useState, useEffect } from 'react';
import { MOCK_ASKS, MOCK_BIDS, TRANSLATIONS } from '../constants';
import { Language } from '../types';
import { ArrowUp, ArrowDown } from 'lucide-react';

interface OrderBookProps {
  lang: Language;
  lastPrice: number;
}

const Row = ({ price, amount, total, type }: { price: number, amount: string, total: string, type: 'ask' | 'bid' }) => {
  const bgClass = type === 'ask' ? 'bg-trade-down' : 'bg-trade-up';
  const textClass = type === 'ask' ? 'text-trade-down' : 'text-trade-up';
  const width = Math.min(parseFloat(total) * 1, 100); 

  return (
    <div className="grid grid-cols-3 text-xs py-0.5 hover:bg-slate-100 dark:hover:bg-slate-700 cursor-pointer transition-colors relative group">
      <div 
        className={`absolute top-0 right-0 h-full opacity-10 transition-all duration-300 ${bgClass}`} 
        style={{ width: `${width}%` }} 
      />
      <div className={`text-left pl-2 ${textClass} z-10 font-mono`}>{price.toFixed(2)}</div>
      <div className="text-right text-slate-700 dark:text-slate-300 z-10 font-mono">{amount}</div>
      <div className="text-right pr-2 text-slate-500 dark:text-slate-400 z-10 font-mono">{total}</div>
    </div>
  );
};

export const OrderBook: React.FC<OrderBookProps> = ({ lang, lastPrice: initialLastPrice }) => {
  const t = TRANSLATIONS[lang];
  const [tab, setTab] = useState<'book' | 'trades'>('book');

  // Dynamic Data State
  const [asks, setAsks] = useState(MOCK_ASKS);
  const [bids, setBids] = useState(MOCK_BIDS);
  const [trades, setTrades] = useState<any[]>([]);
  const [lastPrice, setLastPrice] = useState(initialLastPrice);

  // Initialize trades
  useEffect(() => {
    const initTrades = Array.from({length: 20}).map((_, i) => ({
       price: (initialLastPrice + (Math.random() * 5 - 2.5)).toFixed(2),
       amount: (Math.random() * 5).toFixed(3),
       time: new Date().toLocaleTimeString(),
       isBuy: Math.random() > 0.5
    }));
    setTrades(initTrades);
  }, []);

  // Simulator Effect
  useEffect(() => {
    const interval = setInterval(() => {
      // Perturb Last Price
      const newPrice = lastPrice + (Math.random() - 0.5) * 0.5;
      setLastPrice(newPrice);

      // Perturb Order Book
      setAsks(prev => prev.map(a => ({
         ...a,
         amount: Math.max(0, parseFloat(a.amount) + (Math.random() - 0.5)).toFixed(3),
         total: Math.max(0, parseFloat(a.total) + (Math.random() - 0.5) * 2).toFixed(3)
      })));
      setBids(prev => prev.map(b => ({
         ...b,
         amount: Math.max(0, parseFloat(b.amount) + (Math.random() - 0.5)).toFixed(3),
         total: Math.max(0, parseFloat(b.total) + (Math.random() - 0.5) * 2).toFixed(3)
      })));

      // Add new trade occasionally
      if (Math.random() > 0.7) {
        const newTrade = {
            price: newPrice.toFixed(2),
            amount: (Math.random() * 2).toFixed(3),
            time: new Date().toLocaleTimeString(),
            isBuy: Math.random() > 0.5
        };
        setTrades(prev => [newTrade, ...prev.slice(0, 19)]);
      }

    }, 200);

    return () => clearInterval(interval);
  }, [lastPrice]);

  return (
    <div className="flex flex-col h-full bg-white dark:bg-dark-card border-l border-gray-200 dark:border-dark-border">
      {/* Tabs */}
      <div className="flex border-b border-gray-200 dark:border-dark-border shrink-0">
        <button 
          onClick={() => setTab('book')}
          className={`flex-1 py-2 text-sm font-medium ${tab === 'book' ? 'text-brand-500 border-b-2 border-brand-500' : 'text-gray-500 dark:text-gray-400'}`}
        >
          {t.orderBook}
        </button>
        <button 
          onClick={() => setTab('trades')}
          className={`flex-1 py-2 text-sm font-medium ${tab === 'trades' ? 'text-brand-500 border-b-2 border-brand-500' : 'text-gray-500 dark:text-gray-400'}`}
        >
          {t.recentTrades}
        </button>
      </div>

      {/* Header */}
      <div className="grid grid-cols-3 text-xs text-gray-500 dark:text-gray-400 px-2 py-2 font-semibold shrink-0">
        <div className="text-left">{t.price}</div>
        <div className="text-right">{t.amount}</div>
        <div className="text-right">{tab === 'book' ? t.total : 'Time'}</div>
      </div>

      <div className="flex-1 overflow-y-auto overflow-x-hidden relative custom-scrollbar">
        {tab === 'book' ? (
          <div className="flex flex-col h-full">
            {/* Asks (Top Half) */}
            <div className="flex-1 flex flex-col-reverse overflow-hidden">
              {asks.slice(0, 12).map((ask, i) => (
                <Row key={`ask-${i}`} {...ask} price={parseFloat(ask.price)} type="ask" />
              ))}
            </div>

            {/* Current Price (Middle) */}
            <div className="py-2 my-1 border-y border-gray-100 dark:border-slate-700 flex items-center justify-center space-x-2 bg-gray-50 dark:bg-slate-800/50 shrink-0">
               <span className={`text-lg font-bold ${lastPrice >= initialLastPrice ? 'text-trade-up' : 'text-trade-down'}`}>{lastPrice.toFixed(2)}</span>
               {lastPrice >= initialLastPrice ? <ArrowUp size={16} className="text-trade-up" /> : <ArrowDown size={16} className="text-trade-down" />}
            </div>

            {/* Bids (Bottom Half) */}
            <div className="flex-1 overflow-hidden">
               {bids.slice(0, 12).map((bid, i) => (
                <Row key={`bid-${i}`} {...bid} price={parseFloat(bid.price)} type="bid" />
              ))}
            </div>
          </div>
        ) : (
          /* Recent Trades */
          <div className="flex flex-col">
            {trades.map((trade, i) => (
                 <div key={i} className="grid grid-cols-3 text-xs py-1 hover:bg-slate-100 dark:hover:bg-slate-700 animate-in fade-in slide-in-from-top-1 duration-200">
                    <div className={`text-left pl-2 font-mono ${trade.isBuy ? 'text-trade-up' : 'text-trade-down'}`}>
                      {trade.price}
                    </div>
                    <div className="text-right font-mono text-slate-300">{trade.amount}</div>
                    <div className="text-right pr-2 text-slate-500">{trade.time}</div>
                 </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
};

