import React, { useState, useEffect } from 'react';
import { Header } from './components/Header';
import { MarketStats } from './components/MarketStats';
import { CandleChart } from './components/CandleChart';
import { OrderBook } from './components/OrderBook';
import { TradeForm } from './components/TradeForm';
import { PositionTable } from './components/PositionTable';
import { AccountInfo } from './components/AccountInfo';
import { NotificationContainer } from './components/Notification';
import { WalletModal, AssetModal } from './components/Modals';
import { INITIAL_MARKET_DATA, MOCK_POSITIONS, TRANSLATIONS, INITIAL_ACCOUNT_INFO } from './constants';
import { Language, Theme, MarketData, Position, Order, Notification, OrderSide, OrderType, MarginMode, AccountInfo as AccountInfoType } from './types';

export default function App() {
  const [lang, setLang] = useState<Language>('en');
  const [theme, setTheme] = useState<Theme>('dark');
  const [isConnected, setIsConnected] = useState(false);
  const [marketData, setMarketData] = useState<MarketData>(INITIAL_MARKET_DATA);
  const [positions, setPositions] = useState<Position[]>(MOCK_POSITIONS);
  const [orders, setOrders] = useState<Order[]>([]);
  const [notifications, setNotifications] = useState<Notification[]>([]);
  const [accountInfo, setAccountInfo] = useState<AccountInfoType>(INITIAL_ACCOUNT_INFO);

  // Modal States
  const [showWalletModal, setShowWalletModal] = useState(false);
  const [assetModal, setAssetModal] = useState<{ isOpen: boolean, type: 'deposit' | 'withdraw' }>({ isOpen: false, type: 'deposit' });
  const [showMarginModal, setShowMarginModal] = useState<Position | null>(null);

  const addNotification = (type: 'success' | 'error' | 'info', message: string) => {
    const id = Date.now().toString();
    setNotifications(prev => [...prev, { id, type, message }]);
  };

  const removeNotification = (id: string) => {
    setNotifications(prev => prev.filter(n => n.id !== id));
  };

  // Handlers
  const handleConnect = () => {
    setIsConnected(true);
    addNotification('success', TRANSLATIONS[lang].success + ': Wallet Connected');
  };

  const handleAssetConfirm = (amount: number) => {
    if (assetModal.type === 'deposit') {
      setAccountInfo(prev => ({ ...prev, marginBalance: prev.marginBalance + amount, walletBalance: prev.walletBalance - amount }));
      addNotification('success', `${amount} USDC Deposited Successfully`);
    } else {
      setAccountInfo(prev => ({ ...prev, marginBalance: prev.marginBalance - amount, walletBalance: prev.walletBalance + amount }));
      addNotification('success', `${amount} USDC Withdrawn Successfully`);
    }
  };

  const handleOrder = (side: OrderSide, type: OrderType, size: number, price: number, leverage: number, marginMode: MarginMode) => {
    if (!isConnected) {
      setShowWalletModal(true);
      return;
    }

    if (type === OrderType.MARKET) {
      const newPos: Position = {
        id: Date.now().toString(),
        symbol: 'XAU/USDC',
        side,
        size,
        entryPrice: price,
        markPrice: price,
        leverage,
        margin: (size * price) / leverage,
        marginMode,
        pnl: 0,
        pnlPercent: 0,
        liquidationPrice: side === OrderSide.BUY ? price * 0.8 : price * 1.2
      };
      setPositions(prev => [newPos, ...prev]);
      addNotification('success', `${side} ${size} XAU Market Order Filled`);
    } else {
      const newOrder: Order = {
        id: Date.now().toString(),
        symbol: 'XAU/USDC',
        side,
        type,
        price,
        amount: size,
        filled: 0,
        status: 'OPEN',
        time: new Date().toISOString()
      };
      setOrders(prev => [newOrder, ...prev]);
      addNotification('success', 'Limit Order Placed Successfully');
    }
  };

  const handleClosePosition = (id: string) => {
    setPositions(prev => prev.filter(p => p.id !== id));
    addNotification('success', 'Position Closed at Market Price');
  };

  const handleCancelOrder = (id: string) => {
    setOrders(prev => prev.filter(o => o.id !== id));
    addNotification('success', 'Order Canceled');
  };

  const handleCloseAll = () => {
    setPositions([]);
    addNotification('success', 'All Positions Closed');
  };

  const handleCancelAll = () => {
    setOrders([]);
    addNotification('success', 'All Orders Canceled');
  };

  const handleMarginAdjust = (amount: number, type: 'add' | 'remove') => {
    if (!showMarginModal) return;
    setPositions(prev => prev.map(p => {
      if (p.id === showMarginModal.id) {
        return {
          ...p,
          margin: type === 'add' ? p.margin + amount : p.margin - amount
        };
      }
      return p;
    }));
    setShowMarginModal(null);
    addNotification('success', `Margin ${type === 'add' ? 'Added' : 'Removed'} Successfully`);
  };

  return (
    <div className={`flex flex-col h-screen ${theme} bg-gray-50 dark:bg-dark-bg text-slate-900 dark:text-slate-200 font-sans overflow-hidden`}>
      <Header 
        lang={lang} 
        setLang={setLang} 
        theme={theme} 
        setTheme={setTheme}
        isConnected={isConnected}
        onConnectClick={() => setShowWalletModal(true)}
        onDeposit={() => setAssetModal({ isOpen: true, type: 'deposit' })}
        onWithdraw={() => setAssetModal({ isOpen: true, type: 'withdraw' })}
      />

      <MarketStats data={marketData} lang={lang} />

      {/* Main Content Grid */}
      <main className="flex-1 flex overflow-hidden">

        {/* LEFT COLUMN (Flexible Width): Chart + OrderBook + Positions */}
        <div className="flex-1 flex flex-col min-w-0">

          {/* Top Row: Chart (Flex-Grow) + OrderBook (Fixed or Ratio) */}
          <div className="flex-[3] flex min-h-[450px] border-b border-gray-200 dark:border-dark-border">
            {/* Chart */}
            <div className="flex-1 relative border-r border-gray-200 dark:border-dark-border">
               <CandleChart lang={lang} />
            </div>

            {/* OrderBook (Fixed Width 280px) - Same height as Chart parent */}
            <div className="w-[280px] hidden lg:block bg-white dark:bg-dark-card">
              <OrderBook lang={lang} lastPrice={marketData.lastPrice} />
            </div>
          </div>

          {/* Bottom Row: Positions (Spans full width of Left Column) */}
          <div className="flex-[2] min-h-[250px] overflow-hidden">
             <PositionTable 
               positions={positions} 
               orders={orders} 
               lang={lang}
               onClosePosition={handleClosePosition}
               onCancelOrder={handleCancelOrder}
               onEditMargin={(pos) => setShowMarginModal(pos)}
               onCloseAll={handleCloseAll}
               onCancelAll={handleCancelAll}
             />
          </div>
        </div>

        {/* RIGHT COLUMN (Fixed Width 320px): Trade Form + Account Info */}
        <div className="w-[320px] flex flex-col border-l border-gray-200 dark:border-dark-border bg-white dark:bg-dark-card z-10 shrink-0">

          {/* Trade Form (Scrollable or Fixed) */}
          <div className="flex-1 overflow-y-auto">
            <TradeForm 
              lang={lang} 
              isConnected={isConnected} 
              onConnect={() => setShowWalletModal(true)} 
              onOrder={handleOrder}
              lastPrice={marketData.lastPrice}
              availableBalance={accountInfo.marginBalance} 
            />
          </div>

          {/* Account Info (Pinned to bottom of Right Column) */}
          <div className="shrink-0 h-[200px] border-t border-gray-200 dark:border-dark-border">
             <AccountInfo lang={lang} info={accountInfo} />
          </div>
        </div>

      </main>

      <NotificationContainer notifications={notifications} removeNotification={removeNotification} />

      {/* Modals */}
      <WalletModal 
        isOpen={showWalletModal} 
        onClose={() => setShowWalletModal(false)} 
        lang={lang} 
        onConnect={handleConnect} 
      />

      <AssetModal
        isOpen={assetModal.isOpen}
        onClose={() => setAssetModal(prev => ({ ...prev, isOpen: false }))}
        lang={lang}
        type={assetModal.type}
        maxAmount={assetModal.type === 'deposit' ? accountInfo.walletBalance : accountInfo.marginBalance}
        onConfirm={handleAssetConfirm}
      />

      {/* Margin Modal */}
      {showMarginModal && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-[60]">
          <div className="bg-white dark:bg-dark-card p-6 rounded-lg w-80 shadow-2xl border border-gray-200 dark:border-slate-700 animate-in zoom-in duration-200">
             <h3 className="text-lg font-bold mb-4 dark:text-white">Adjust Margin</h3>
             <p className="text-sm text-gray-500 mb-4">{showMarginModal.symbol} - {showMarginModal.marginMode} {showMarginModal.leverage}x</p>
             <div className="flex space-x-2 mb-4">
               <button onClick={() => handleMarginAdjust(100, 'add')} className="flex-1 py-2 bg-trade-up text-white rounded hover:bg-green-600">Add 100</button>
               <button onClick={() => handleMarginAdjust(100, 'remove')} className="flex-1 py-2 bg-trade-down text-white rounded hover:bg-red-600">Remove 100</button>
             </div>
             <button onClick={() => setShowMarginModal(null)} className="w-full py-2 text-gray-500 hover:bg-gray-100 dark:hover:bg-slate-700 rounded">Cancel</button>
          </div>
        </div>
      )}
    </div>
  );
}

import React, { useState, useEffect } from 'react';
import { Language, WalletProvider } from '../types';
import { TRANSLATIONS } from '../constants';
import { X, Wallet, ArrowRight, Loader2, ShieldCheck } from 'lucide-react';

interface ModalProps {
  isOpen: boolean;
  onClose: () => void;
  title: string;
  children: React.ReactNode;
}

const BaseModal: React.FC<ModalProps> = ({ isOpen, onClose, title, children }) => {
  if (!isOpen) return null;
  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/60 backdrop-blur-sm p-4">
      <div className="w-full max-w-md bg-white dark:bg-dark-card border border-gray-200 dark:border-slate-700 rounded-xl shadow-2xl animate-in fade-in zoom-in duration-200">
        <div className="flex items-center justify-between px-6 py-4 border-b border-gray-200 dark:border-slate-700">
          <h3 className="text-lg font-bold text-slate-900 dark:text-white">{title}</h3>
          <button onClick={onClose} className="text-gray-500 hover:text-gray-700 dark:text-gray-400 dark:hover:text-white transition">
            <X size={20} />
          </button>
        </div>
        <div className="p-6">{children}</div>
      </div>
    </div>
  );
};

const WalletIcon = ({ name }: { name: string }) => {
  switch (name) {
    case 'Metamask': return <img src="https://upload.wikimedia.org/wikipedia/commons/3/36/MetaMask_Logo.svg" className="w-6 h-6" alt="metamask" />;
    case 'OKX Wallet': return <img src="https://static.okx.com/cdn/assets/imgs/221/9E9A8E8A38B7B83F.png" className="w-6 h-6 rounded-full" alt="okx" />;
    case 'Binance Wallet': return <img src="https://cryptologos.cc/logos/binance-coin-bnb-logo.svg?v=024" className="w-6 h-6" alt="binance" />;
    case 'WalletConnect': return <img src="https://avatars.githubusercontent.com/u/37784886?s=200&v=4" className="w-6 h-6" alt="wc" />;
    default: return <Wallet size={20} />;
  }
};

// --- Wallet Connect Modal ---
interface WalletModalProps {
  isOpen: boolean;
  onClose: () => void;
  lang: Language;
  onConnect: () => void;
}

export const WalletModal: React.FC<WalletModalProps> = ({ isOpen, onClose, lang, onConnect }) => {
  const t = TRANSLATIONS[lang];
  const [step, setStep] = useState<'select' | 'sign'>('select');
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    if (isOpen) setStep('select');
  }, [isOpen]);

  const handleProviderSelect = () => {
    setLoading(true);
    // Simulate connection delay
    setTimeout(() => {
      setLoading(false);
      setStep('sign');
    }, 1000);
  };

  const handleSign = () => {
    setLoading(true);
    // Simulate signature delay
    setTimeout(() => {
      setLoading(false);
      onConnect();
      onClose();
    }, 1500);
  };

  return (
    <BaseModal isOpen={isOpen} onClose={onClose} title={step === 'select' ? t.selectWallet : t.signToLogin}>
      {step === 'select' ? (
        <div className="space-y-3">
          {['WalletConnect', 'Metamask', 'OKX Wallet', 'Binance Wallet'].map((provider) => (
            <button
              key={provider}
              onClick={handleProviderSelect}
              disabled={loading}
              className="w-full flex items-center justify-between p-4 rounded-lg bg-gray-50 dark:bg-slate-800 hover:bg-gray-100 dark:hover:bg-slate-700 border border-transparent hover:border-brand-500 transition-all group"
            >
              <div className="flex items-center space-x-3">
                <WalletIcon name={provider} />
                <span className="font-semibold text-slate-700 dark:text-slate-200">{provider}</span>
              </div>
              {loading ? <Loader2 className="animate-spin text-brand-500" size={18} /> : <ArrowRight size={18} className="text-gray-400 group-hover:text-brand-500" />}
            </button>
          ))}
        </div>
      ) : (
        <div className="text-center">
          <div className="mx-auto w-16 h-16 bg-brand-500/10 rounded-full flex items-center justify-center mb-4">
            <ShieldCheck size={32} className="text-brand-500" />
          </div>
          <p className="text-sm text-gray-500 dark:text-gray-300 mb-6">
            Please sign the message in your wallet to verify ownership and log in.
          </p>
          <button
            onClick={handleSign}
            disabled={loading}
            className="w-full py-3 bg-brand-500 hover:bg-brand-600 text-white font-bold rounded-lg transition-colors flex items-center justify-center space-x-2"
          >
            {loading ? <Loader2 className="animate-spin" size={18} /> : <span className="font-bold">{t.confirm}</span>}
          </button>
        </div>
      )}
    </BaseModal>
  );
};

// --- Asset Action Modal (Deposit/Withdraw) ---
interface AssetModalProps {
  isOpen: boolean;
  onClose: () => void;
  lang: Language;
  type: 'deposit' | 'withdraw';
  maxAmount: number;
  onConfirm: (amount: number) => void;
}

export const AssetModal: React.FC<AssetModalProps> = ({ isOpen, onClose, lang, type, maxAmount, onConfirm }) => {
  const t = TRANSLATIONS[lang];
  const [amount, setAmount] = useState('');
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    if (isOpen) setAmount('');
  }, [isOpen]);

  const handleConfirm = () => {
    if (!amount || parseFloat(amount) <= 0) return;
    setLoading(true);
    // Simulate contract interaction
    setTimeout(() => {
      setLoading(false);
      onConfirm(parseFloat(amount));
      onClose();
    }, 2000);
  };

  const isValid = amount && parseFloat(amount) > 0 && parseFloat(amount) <= maxAmount;

  return (
    <BaseModal isOpen={isOpen} onClose={onClose} title={type === 'deposit' ? t.deposit : t.withdraw}>
      <div className="space-y-4">
        {/* Network Selection */}
        <div>
          <label className="text-xs font-semibold text-gray-500 dark:text-gray-400 mb-2 block">{t.network}</label>
          <div className="w-full p-3 bg-gray-50 dark:bg-slate-800 border border-gray-200 dark:border-slate-700 rounded-lg flex items-center justify-between cursor-pointer">
            <div className="flex items-center space-x-2">
              <div className="w-5 h-5 rounded-full bg-blue-500"></div>
              <span className="text-sm font-medium text-slate-900 dark:text-white">Arbitrum One</span>
            </div>
            {/* Mock dropdown arrow implies selection but fixed for demo */}
          </div>
        </div>

        {/* Amount Input */}
        <div>
          <div className="flex justify-between mb-2">
             <label className="text-xs font-semibold text-gray-500 dark:text-gray-400">{t.amount}</label>
             <div className="text-xs text-gray-500">
               {type === 'deposit' ? t.walletBalance : t.avail}: <span className="text-slate-900 dark:text-white font-mono">{maxAmount.toLocaleString()} USDC</span>
             </div>
          </div>
          <div className="relative">
            <input
              type="number"
              value={amount}
              onChange={(e) => setAmount(e.target.value)}
              placeholder="0.00"
              className="w-full bg-gray-50 dark:bg-slate-800 border border-gray-200 dark:border-slate-700 rounded-lg p-3 pr-20 text-slate-900 dark:text-white focus:ring-1 focus:ring-brand-500 outline-none transition font-mono"
            />
            <div className="absolute right-2 top-2 flex items-center space-x-1">
               <button 
                 onClick={() => setAmount(maxAmount.toString())}
                 className="text-xs text-brand-500 hover:bg-brand-500/10 px-2 py-1 rounded font-bold"
               >
                 {t.max}
               </button>
               <span className="text-sm text-gray-400 font-medium">USDC</span>
            </div>
          </div>
        </div>

        {/* Info Box */}
        <div className="p-3 bg-blue-50 dark:bg-blue-900/20 rounded border border-blue-100 dark:border-blue-800/50">
           <p className="text-xs text-blue-600 dark:text-blue-400">
             {type === 'deposit' 
               ? "Funds will be deposited into the Vault smart contract on Arbitrum."
               : "Withdrawal will be processed from the Vault to your wallet immediately."}
           </p>
        </div>

        {/* Action Button */}
        <button
          onClick={handleConfirm}
          disabled={!isValid || loading}
          className={`w-full py-3 font-bold rounded-lg transition-all flex items-center justify-center space-x-2 ${
            isValid && !loading
              ? 'bg-brand-500 hover:bg-brand-600 text-white shadow-lg shadow-brand-500/20'
              : 'bg-gray-200 dark:bg-slate-700 text-gray-400 cursor-not-allowed'
          }`}
        >
          {loading && <Loader2 className="animate-spin" size={18} />}
          <span>{loading ? t.processing : t.confirm}</span>
        </button>
      </div>
    </BaseModal>
  );
};

import React, { useState, useMemo, useEffect, useRef } from 'react';
import { AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, BarChart, Bar } from 'recharts';
import { CHART_DATA, MOCK_ASKS, MOCK_BIDS, TRANSLATIONS, TIMEFRAMES } from '../constants';
import { Language } from '../types';
import { ChevronDown, LineChart as LineIcon, BarChart2, Layers } from 'lucide-react';

type ChartType = 'line' | 'candle' | 'depth';
type PriceSourceKey = 'lastPrice' | 'markPrice' | 'indexPrice';

interface CandleChartProps {
  lang: Language;
}

const CandleStickShape = (props: any) => {
  const { x, y, width, height, payload } = props;
  const { open, close, high, low } = payload;
  const isUp = close >= open;
  const color = isUp ? '#10B981' : '#F43F5E';

  const bodyLength = Math.abs(close - open);
  const pixelsPerUnit = bodyLength === 0 ? 0 : height / bodyLength;

  let wickTop = y;
  let wickBottom = y + height;

  if (pixelsPerUnit > 0) {
      const highDiff = high - Math.max(open, close);
      const lowDiff = Math.min(open, close) - low;
      wickTop = y - (highDiff * pixelsPerUnit);
      wickBottom = y + height + (lowDiff * pixelsPerUnit);
  }

  return (
    <g>
      <line x1={x + width / 2} y1={wickTop} x2={x + width / 2} y2={wickBottom} stroke={color} strokeWidth={1} />
      <rect x={x} y={y} width={width} height={Math.max(1, height)} fill={color} stroke="none"/>
    </g>
  );
};

export const CandleChart: React.FC<CandleChartProps> = ({ lang }) => {
  const t = TRANSLATIONS[lang];
  const [chartType, setChartType] = useState<ChartType>('candle');
  const [timeframe, setTimeframe] = useState('15m');
  const [priceSourceKey, setPriceSourceKey] = useState<PriceSourceKey>('lastPrice');
  const [isDropdownOpen, setIsDropdownOpen] = useState(false);
  const dropdownRef = useRef<HTMLDivElement>(null);

  // Dynamic Data Simulation
  const [liveData, setLiveData] = useState(CHART_DATA);
  const [liveAsks, setLiveAsks] = useState(MOCK_ASKS);
  const [liveBids, setLiveBids] = useState(MOCK_BIDS);

  useEffect(() => {
    const interval = setInterval(() => {
      setLiveData(prev => {
        const last = prev[prev.length - 1];
        const change = (Math.random() - 0.5) * 5;
        const newClose = last.close + change;
        const newOpen = last.close;
        const newHigh = Math.max(newOpen, newClose) + Math.random() * 2;
        const newLow = Math.min(newOpen, newClose) - Math.random() * 2;

        return [...prev.slice(1), {
          ...last,
          time: last.time + 1,
          open: newOpen,
          close: newClose,
          high: newHigh,
          low: newLow
        }];
      });

      // Simulating depth updates
      setLiveAsks(prev => prev.map(a => ({ ...a, amount: (parseFloat(a.amount) + (Math.random() - 0.5)).toFixed(3) })));
      setLiveBids(prev => prev.map(b => ({ ...b, amount: (parseFloat(b.amount) + (Math.random() - 0.5)).toFixed(3) })));

    }, 2000);
    return () => clearInterval(interval);
  }, []);

  // Handle outside click for dropdown
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
        setIsDropdownOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const displayData = useMemo(() => {
    if (chartType === 'depth') {
        const bids = [...liveBids]
            .sort((a, b) => b.price - a.price)
            .reduce((acc: any[], item) => {
                const prevTotal = acc.length > 0 ? parseFloat(acc[acc.length - 1].total) : 0;
                const total = prevTotal + parseFloat(item.amount);
                acc.push({ price: item.price, bidTotal: total, total: total.toFixed(3) });
                return acc;
            }, [])
            .reverse();

        const asks = [...liveAsks]
            .sort((a, b) => a.price - b.price)
            .reduce((acc: any[], item) => {
                const prevTotal = acc.length > 0 ? parseFloat(acc[acc.length - 1].total) : 0;
                const total = prevTotal + parseFloat(item.amount);
                acc.push({ price: item.price, askTotal: total, total: total.toFixed(3) });
                return acc;
            }, []);

        return [
            ...bids.map(b => ({ ...b, askTotal: null })), 
            ...asks.map(a => ({ ...a, bidTotal: null }))
        ].sort((a, b) => a.price - b.price);
    } else {
        return liveData.map(d => {
            let val = d.close;
            if (priceSourceKey === 'markPrice') val = d.close * 1.0005;
            if (priceSourceKey === 'indexPrice') val = d.close * 0.9995;
            return {
                ...d,
                displayPrice: val,
                body: [Math.min(d.open, d.close), Math.max(d.open, d.close)]
            };
        });
    }
  }, [chartType, priceSourceKey, liveData, liveAsks, liveBids]);

  return (
    <div className="w-full h-full flex flex-col bg-white dark:bg-dark-bg relative">
      <div className="flex items-center justify-between px-4 py-2 border-b border-gray-100 dark:border-slate-800">
         <div className="flex space-x-1 overflow-x-auto hide-scrollbar mr-2">
           {TIMEFRAMES.map(tf => (
             <button
               key={tf}
               onClick={() => setTimeframe(tf)}
               className={`px-2 py-1 text-xs font-medium rounded transition-colors whitespace-nowrap ${
                 timeframe === tf 
                   ? 'text-brand-500 bg-brand-500/10' 
                   : 'text-gray-500 hover:text-slate-900 dark:text-gray-400 dark:hover:text-slate-200'
               }`}
             >
               {tf}
             </button>
           ))}
         </div>

         <div className="flex items-center space-x-3 shrink-0">
             <div className="flex bg-gray-100 dark:bg-slate-800 rounded p-0.5">
               <button onClick={() => setChartType('line')} className={`p-1.5 rounded transition-colors ${chartType === 'line' ? 'bg-white dark:bg-slate-600 text-brand-500 shadow' : 'text-gray-400 hover:text-gray-600 dark:hover:text-gray-200'}`}>
                 <LineIcon size={14} />
               </button>
               <button onClick={() => setChartType('candle')} className={`p-1.5 rounded transition-colors ${chartType === 'candle' ? 'bg-white dark:bg-slate-600 text-brand-500 shadow' : 'text-gray-400 hover:text-gray-600 dark:hover:text-gray-200'}`}>
                 <BarChart2 size={14} />
               </button>
               <button onClick={() => setChartType('depth')} className={`p-1.5 rounded transition-colors ${chartType === 'depth' ? 'bg-white dark:bg-slate-600 text-brand-500 shadow' : 'text-gray-400 hover:text-gray-600 dark:hover:text-gray-200'}`}>
                 <Layers size={14} />
               </button>
             </div>

             <div className="relative" ref={dropdownRef}>
                 <button 
                    onClick={() => setIsDropdownOpen(!isDropdownOpen)}
                    className="flex items-center space-x-1 text-xs font-bold text-slate-700 dark:text-slate-300 hover:text-brand-500 transition-colors"
                 >
                     <span>{t[priceSourceKey]}</span>
                     <ChevronDown size={14} className={`transition-transform ${isDropdownOpen ? 'rotate-180' : ''}`} />
                 </button>
                 {isDropdownOpen && (
                   <div className="absolute right-0 mt-2 w-32 bg-white dark:bg-dark-card border border-gray-200 dark:border-slate-700 rounded-lg shadow-xl py-1 z-50">
                       {(['lastPrice', 'markPrice', 'indexPrice'] as PriceSourceKey[]).map(key => (
                           <button
                              key={key}
                              onClick={() => {
                                setPriceSourceKey(key);
                                setIsDropdownOpen(false);
                              }}
                              className={`block w-full text-left px-4 py-2 text-xs font-medium hover:bg-gray-100 dark:hover:bg-slate-800 ${
                                  priceSourceKey === key ? 'text-brand-500' : 'text-slate-700 dark:text-slate-300'
                              }`}
                           >
                               {t[key]}
                           </button>
                       ))}
                   </div>
                 )}
             </div>
         </div>
      </div>

      <div className="flex-1 w-full relative">
        <ResponsiveContainer width="100%" height="100%">
          {chartType === 'line' ? (
              <AreaChart data={displayData}>
                <defs>
                  <linearGradient id="colorPrice" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="5%" stopColor="#EAB308" stopOpacity={0.3}/>
                    <stop offset="95%" stopColor="#EAB308" stopOpacity={0}/>
                  </linearGradient>
                </defs>
                <CartesianGrid strokeDasharray="3 3" stroke="#334155" opacity={0.2} vertical={false} />
                <XAxis dataKey="time" hide />
                <YAxis orientation="right" domain={['auto', 'auto']} tick={{fill: '#94a3b8', fontSize: 11}} axisLine={false} tickLine={false} width={50} />
                <Tooltip 
                  contentStyle={{ backgroundColor: '#1E293B', borderColor: '#334155', color: '#f1f5f9' }}
                  itemStyle={{ color: '#EAB308' }}
                  formatter={(value: number) => [value.toFixed(2), t[priceSourceKey]]}
                  labelFormatter={() => ''}
                />
                <Area type="monotone" dataKey="displayPrice" stroke="#EAB308" strokeWidth={2} fillOpacity={1} fill="url(#colorPrice)" isAnimationActive={true} animationDuration={500} />
              </AreaChart>
          ) : chartType === 'candle' ? (
              <BarChart data={displayData}>
                 <CartesianGrid strokeDasharray="3 3" stroke="#334155" opacity={0.2} vertical={false} />
                 <XAxis dataKey="time" hide />
                 <YAxis orientation="right" domain={['dataMin - 5', 'dataMax + 5']} tick={{fill: '#94a3b8', fontSize: 11}} axisLine={false} tickLine={false} width={50} />
                 <Tooltip cursor={{fill: 'transparent'}} content={<CustomTooltip />} />
                 <Bar dataKey="body" shape={<CandleStickShape />} isAnimationActive={true} animationDuration={500} />
              </BarChart>
          ) : (
              <AreaChart data={displayData}>
                 <CartesianGrid strokeDasharray="3 3" stroke="#334155" opacity={0.2} vertical={false} />
                 <XAxis dataKey="price" type="number" domain={['auto', 'auto']} tick={{fill: '#94a3b8', fontSize: 11}} axisLine={false} tickLine={false} tickCount={6} />
                 <YAxis orientation="right" tick={{fill: '#94a3b8', fontSize: 11}} axisLine={false} tickLine={false} width={50} />
                 <Tooltip contentStyle={{ backgroundColor: '#1E293B', borderColor: '#334155', color: '#f1f5f9' }} />
                 <Area type="step" dataKey="bidTotal" stroke="#10B981" fill="#10B981" fillOpacity={0.3} strokeWidth={2} name="Bid Depth" isAnimationActive={true} animationDuration={500} />
                 <Area type="step" dataKey="askTotal" stroke="#F43F5E" fill="#F43F5E" fillOpacity={0.3} strokeWidth={2} name="Ask Depth" isAnimationActive={true} animationDuration={500} />
              </AreaChart>
          )}
        </ResponsiveContainer>
      </div>

      <div className="absolute top-1/2 left-1/2 transform -translate-x-1/2 -translate-y-1/2 pointer-events-none opacity-[0.03]">
         <div className="text-8xl font-bold text-slate-900 dark:text-white">GOLD</div>
      </div>
    </div>
  );
};

const CustomTooltip = ({ active, payload }: any) => {
   if (active && payload && payload.length) {
       const d = payload[0].payload;
       return (
           <div className="bg-dark-card border border-dark-border p-2 rounded shadow-lg text-xs">
               <div className="text-gray-400 mb-1">Time: {d.time}</div>
               <div className="grid grid-cols-2 gap-x-4 gap-y-1">
                   <span className="text-gray-400">O:</span> <span className={d.open < d.close ? 'text-trade-up' : 'text-trade-down'}>{d.open.toFixed(2)}</span>
                   <span className="text-gray-400">H:</span> <span className="text-slate-200">{d.high.toFixed(2)}</span>
                   <span className="text-gray-400">L:</span> <span className="text-slate-200">{d.low.toFixed(2)}</span>
                   <span className="text-gray-400">C:</span> <span className={d.open < d.close ? 'text-trade-up' : 'text-trade-down'}>{d.close.toFixed(2)}</span>
               </div>
           </div>
       );
   }
   return null;
};

import React, { useState, useEffect, useRef } from 'react';
import { Language, MarginMode, OrderType, OrderSide } from '../types';
import { TRANSLATIONS } from '../constants';
import { Edit3, X } from 'lucide-react';

interface TradeFormProps {
  lang: Language;
  isConnected: boolean;
  onConnect: () => void;
  onOrder: (side: OrderSide, type: OrderType, size: number, price: number, leverage: number, marginMode: MarginMode) => void;
  lastPrice: number;
  availableBalance: number;
}

export const TradeForm: React.FC<TradeFormProps> = ({ lang, isConnected, onConnect, onOrder, lastPrice, availableBalance }) => {
  const t = TRANSLATIONS[lang];

  // Form State
  const [type, setType] = useState<OrderType>(OrderType.MARKET);
  const [marginMode, setMarginMode] = useState<MarginMode>(MarginMode.CROSS);
  const [leverage, setLeverage] = useState<number>(20);
  const [amount, setAmount] = useState<string>('');
  const [price, setPrice] = useState<string>('');
  const [sliderValue, setSliderValue] = useState(0);

  // UI State
  const [showLeveragePopup, setShowLeveragePopup] = useState(false);

  // Derived Values
  const effectivePrice = type === OrderType.LIMIT && price ? parseFloat(price) : lastPrice;
  const maxAmount = effectivePrice > 0 ? (availableBalance * leverage) / effectivePrice : 0;

  const handleSliderChange = (val: number) => {
    setSliderValue(val);
    if (maxAmount > 0) {
      const newAmount = (maxAmount * val / 100).toFixed(4);
      setAmount(newAmount);
    }
  };

  const handleAmountChange = (val: string) => {
    setAmount(val);
    const num = parseFloat(val);
    if (!isNaN(num) && maxAmount > 0) {
      setSliderValue(Math.min(100, (num / maxAmount) * 100));
    } else {
      setSliderValue(0);
    }
  };

  const handleOrderClick = (side: OrderSide) => {
    if (!isConnected) {
      onConnect();
      return;
    }
    if (!amount || parseFloat(amount) <= 0) return;
    onOrder(side, type, parseFloat(amount), effectivePrice, leverage, marginMode);
    setAmount('');
    setSliderValue(0);
  };

  const parsedAmount = parseFloat(amount) || 0;
  const marginCost = parsedAmount * effectivePrice / leverage;
  const liqPriceLong = effectivePrice * (1 - 1/leverage + 0.005);
  const liqPriceShort = effectivePrice * (1 + 1/leverage - 0.005);

  return (
    <div className="flex flex-col h-full bg-white dark:bg-dark-card border-l border-gray-200 dark:border-dark-border p-4 relative">

      {/* 1. Header: Margin Mode & Leverage */}
      <div className="flex justify-between items-center mb-4">
        <div className="flex bg-gray-100 dark:bg-slate-800 rounded border border-gray-200 dark:border-slate-700 p-0.5">
          <button
            onClick={() => setMarginMode(MarginMode.CROSS)}
            className={`px-3 py-1.5 text-xs font-bold rounded transition-all ${
              marginMode === MarginMode.CROSS
                ? 'bg-slate-500/30 text-brand-500 shadow-sm'
                : 'text-gray-500 hover:text-gray-700 dark:hover:text-gray-300'
            }`}
          >
            {t.cross}
          </button>
          <button
            onClick={() => setMarginMode(MarginMode.ISOLATED)}
            className={`px-3 py-1.5 text-xs font-bold rounded transition-all ${
              marginMode === MarginMode.ISOLATED
                ? 'bg-slate-500/30 text-brand-500 shadow-sm'
                : 'text-gray-500 hover:text-gray-700 dark:hover:text-gray-300'
            }`}
          >
            {t.isolated}
          </button>
        </div>

        <button
          onClick={() => setShowLeveragePopup(true)}
          className="flex items-center space-x-1 bg-gray-100 dark:bg-slate-800 hover:bg-gray-200 dark:hover:bg-slate-700 px-3 py-1.5 rounded text-xs font-bold text-slate-900 dark:text-white transition-colors border border-gray-200 dark:border-slate-700"
        >
          <span>{leverage}x</span>
          <Edit3 size={12} className="text-gray-500" />
        </button>
      </div>

      {/* 2. Order Type Toggle */}
      <div className="flex bg-gray-100 dark:bg-slate-800 border border-gray-200 dark:border-slate-700 rounded p-0.5 mb-4">
        <button
          onClick={() => setType(OrderType.MARKET)}
          className={`flex-1 py-1.5 text-xs font-bold rounded transition-all ${
            type === OrderType.MARKET
              ? 'bg-slate-500 text-white shadow'
              : 'text-gray-500 hover:text-gray-700 dark:hover:text-gray-300'
          }`}
        >
          {t.market}
        </button>
        <button
          onClick={() => setType(OrderType.LIMIT)}
          className={`flex-1 py-1.5 text-xs font-bold rounded transition-all ${
            type === OrderType.LIMIT
              ? 'bg-slate-500 text-white shadow'
              : 'text-gray-500 hover:text-gray-700 dark:hover:text-gray-300'
          }`}
        >
          {t.limit}
        </button>
      </div>

      {/* 3. Price Input */}
      <div className="mb-3">
        <div className="text-xs text-gray-500 mb-1">{t.price}</div>
        <div className="relative">
          <input
            type={type === OrderType.LIMIT ? "number" : "text"}
            value={type === OrderType.LIMIT ? price : ""}
            onChange={(e) => setPrice(e.target.value)}
            disabled={type === OrderType.MARKET}
            placeholder={type === OrderType.MARKET ? `${t.market} ${t.price}` : lastPrice.toFixed(2)}
            className={`w-full bg-transparent border rounded p-2.5 text-sm outline-none transition font-mono ${
               type === OrderType.MARKET 
                 ? 'border-gray-200 dark:border-slate-700 text-gray-500 italic cursor-not-allowed bg-gray-50 dark:bg-slate-800/50' 
                 : 'border-gray-300 dark:border-slate-600 text-slate-900 dark:text-white focus:border-brand-500'
            }`}
          />
        </div>
      </div>

      {/* 4. Amount Input */}
      <div className="mb-1">
        <div className="flex justify-between text-xs mb-1">
          <span className="text-gray-500">{t.amount}</span>
          <span className="text-gray-500">{t.avail}: <span className="text-slate-900 dark:text-slate-200 font-mono">{availableBalance.toFixed(2)} USDC</span></span>
        </div>
        <div className="relative flex items-center">
          <input
            type="number"
            value={amount}
            onChange={(e) => handleAmountChange(e.target.value)}
            className="w-full bg-transparent border border-gray-300 dark:border-slate-600 rounded p-2.5 pr-20 text-sm text-slate-900 dark:text-white focus:border-brand-500 outline-none transition font-bold font-mono"
            placeholder="0.00"
          />
          <div className="absolute right-0 h-full flex items-center pr-2">
             <span className="bg-gray-200 dark:bg-slate-700 text-xs font-bold px-2 py-1 rounded text-slate-700 dark:text-slate-300">XAU</span>
          </div>
        </div>
      </div>

      {/* 5. Slider */}
      <div className="mb-8 px-1 mt-6 relative">
        <input
          type="range"
          min="0"
          max="100"
          step="1"
          value={sliderValue}
          onChange={(e) => handleSliderChange(parseFloat(e.target.value))}
          className="w-full h-1 bg-gray-200 dark:bg-slate-700 rounded-lg appearance-none cursor-pointer accent-brand-500 z-10 relative"
        />
        <div className="flex justify-between mt-2 text-[10px] text-gray-500 font-medium">
          <span className="cursor-pointer hover:text-brand-500" onClick={() => handleSliderChange(0)}>0%</span>
          <span className="cursor-pointer hover:text-brand-500" onClick={() => handleSliderChange(25)}>25%</span>
          <span className="cursor-pointer hover:text-brand-500" onClick={() => handleSliderChange(50)}>50%</span>
          <span className="cursor-pointer hover:text-brand-500" onClick={() => handleSliderChange(75)}>75%</span>
          <span className="cursor-pointer hover:text-brand-500" onClick={() => handleSliderChange(100)}>100%</span>
        </div>
        {sliderValue > 0 && (
          <div 
             className="absolute -top-7 transform -translate-x-1/2 bg-brand-500 text-white text-[10px] font-bold py-0.5 px-1.5 rounded-full pointer-events-none"
             style={{ left: `${sliderValue}%` }}
          >
            {Math.round(sliderValue)}%
          </div>
        )}
      </div>

      {/* 6. Action Buttons */}
      <div className="grid grid-cols-2 gap-3 mb-4">
        <button
          onClick={() => handleOrderClick(OrderSide.BUY)}
          className="py-3 bg-trade-up hover:bg-green-600 text-white font-bold rounded-lg transition-colors shadow-lg shadow-green-900/20"
        >
          {t.buyLong}
        </button>
        <button
          onClick={() => handleOrderClick(OrderSide.SELL)}
          className="py-3 bg-trade-down hover:bg-red-600 text-white font-bold rounded-lg transition-colors shadow-lg shadow-red-900/20"
        >
          {t.sellShort}
        </button>
      </div>

      {/* 7. Bottom Info Grid */}
      <div className="grid grid-cols-2 gap-4 text-xs border-t border-dashed border-gray-200 dark:border-slate-700 pt-4 mt-auto">
        <div className="space-y-1.5">
           <div className="flex justify-between">
             <span className="text-gray-500">{t.liqPrice}</span>
             <span className="text-orange-500 font-mono">{liqPriceLong.toFixed(2)}</span>
           </div>
           <div className="flex justify-between">
             <span className="text-gray-500">{t.margin}</span>
             <span className="text-slate-900 dark:text-slate-300 font-mono">{marginCost.toFixed(1)}</span>
           </div>
           <div className="flex justify-between">
             <span className="text-gray-500">{t.max}</span>
             <span className="text-slate-900 dark:text-slate-300 font-mono">{maxAmount.toFixed(2)}</span>
           </div>
        </div>

        <div className="space-y-1.5 pl-4 border-l border-gray-200 dark:border-slate-800">
           <div className="flex justify-between">
             <span className="text-gray-500">{t.liqPrice}</span>
             <span className="text-orange-500 font-mono">{liqPriceShort.toFixed(2)}</span>
           </div>
           <div className="flex justify-between">
             <span className="text-gray-500">{t.margin}</span>
             <span className="text-slate-900 dark:text-slate-300 font-mono">{marginCost.toFixed(1)}</span>
           </div>
           <div className="flex justify-between">
             <span className="text-gray-500">{t.max}</span>
             <span className="text-slate-900 dark:text-slate-300 font-mono">{maxAmount.toFixed(2)}</span>
           </div>
        </div>
      </div>

      {/* Leverage Popup Modal */}
      {showLeveragePopup && (
        <>
          <div className="fixed inset-0 bg-black/50 z-20 backdrop-blur-[1px]" onClick={() => setShowLeveragePopup(false)} />
          <div className="absolute top-16 left-4 right-4 bg-white dark:bg-dark-card border border-gray-200 dark:border-slate-700 rounded-lg shadow-2xl z-30 p-4 animate-in zoom-in-95 duration-200">
            <div className="flex justify-between items-center mb-4">
              <span className="font-bold text-sm text-slate-900 dark:text-white">Adjust Leverage</span>
              <button onClick={() => setShowLeveragePopup(false)} className="text-gray-500 hover:text-slate-900 dark:hover:text-white"><X size={16} /></button>
            </div>

            <div className="bg-gray-100 dark:bg-slate-800 rounded border border-gray-200 dark:border-slate-700 p-2 mb-6 text-center">
               <span className="text-2xl font-bold text-brand-500">{leverage}x</span>
            </div>

            <input
              type="range"
              min="1"
              max="20"
              step="1"
              value={leverage}
              onChange={(e) => setLeverage(parseInt(e.target.value))}
              className="w-full h-2 bg-gray-200 dark:bg-slate-700 rounded-lg appearance-none cursor-pointer accent-brand-500 mb-4"
            />
            <div className="flex justify-between text-xs text-gray-500 mb-4 font-mono">
              <span>1x</span>
              <span>10x</span>
