import React, { useState, useEffect, useRef } from 'react';
import { Language, MarginMode, OrderType, OrderSide } from '../types';
import { TRANSLATIONS } from '../constants';
import { Edit3, X } from 'lucide-react';

interface TradeFormProps {
  lang: Language;
  isConnected: boolean;
  onConnect: () => void;
  onOrder: (side: OrderSide, type: OrderType, size: number, price: number, leverage: number, marginMode: MarginMode) => void;
  lastPrice: number;
  availableBalance: number;
}

export const TradeForm: React.FC<TradeFormProps> = ({ lang, isConnected, onConnect, onOrder, lastPrice, availableBalance }) => {
  const t = TRANSLATIONS[lang];

  // Form State
  const [type, setType] = useState<OrderType>(OrderType.MARKET);
  const [marginMode, setMarginMode] = useState<MarginMode>(MarginMode.CROSS);
  const [leverage, setLeverage] = useState<number>(20);
  const [amount, setAmount] = useState<string>('');
  const [price, setPrice] = useState<string>('');
  const [sliderValue, setSliderValue] = useState(0);

  // UI State
  const [showLeveragePopup, setShowLeveragePopup] = useState(false);

  // Derived Values
  const effectivePrice = type === OrderType.LIMIT && price ? parseFloat(price) : lastPrice;
  const maxAmount = effectivePrice > 0 ? (availableBalance * leverage) / effectivePrice : 0;

  const handleSliderChange = (val: number) => {
    setSliderValue(val);
    if (maxAmount > 0) {
      const newAmount = (maxAmount * val / 100).toFixed(4);
      setAmount(newAmount);
    }
  };

  const handleAmountChange = (val: string) => {
    setAmount(val);
    const num = parseFloat(val);
    if (!isNaN(num) && maxAmount > 0) {
      setSliderValue(Math.min(100, (num / maxAmount) * 100));
    } else {
      setSliderValue(0);
    }
  };

  const handleOrderClick = (side: OrderSide) => {
    if (!isConnected) {
      onConnect();
      return;
    }
    if (!amount || parseFloat(amount) <= 0) return;
    onOrder(side, type, parseFloat(amount), effectivePrice, leverage, marginMode);
    setAmount('');
    setSliderValue(0);
  };

  const parsedAmount = parseFloat(amount) || 0;
  const marginCost = parsedAmount * effectivePrice / leverage;
  const liqPriceLong = effectivePrice * (1 - 1/leverage + 0.005);
  const liqPriceShort = effectivePrice * (1 + 1/leverage - 0.005);

  return (
    <div className="flex flex-col h-full bg-white dark:bg-dark-card border-l border-gray-200 dark:border-dark-border p-4 relative">

      {/* 1. Header: Margin Mode & Leverage */}
      <div className="flex justify-between items-center mb-4">
        <div className="flex bg-gray-100 dark:bg-slate-800 rounded border border-gray-200 dark:border-slate-700 p-0.5">
          <button
            onClick={() => setMarginMode(MarginMode.CROSS)}
            className={`px-3 py-1.5 text-xs font-bold rounded transition-all ${
              marginMode === MarginMode.CROSS
                ? 'bg-slate-500/30 text-brand-500 shadow-sm'
                : 'text-gray-500 hover:text-gray-700 dark:hover:text-gray-300'
            }`}
          >
            {t.cross}
          </button>
          <button
            onClick={() => setMarginMode(MarginMode.ISOLATED)}
            className={`px-3 py-1.5 text-xs font-bold rounded transition-all ${
              marginMode === MarginMode.ISOLATED
                ? 'bg-slate-500/30 text-brand-500 shadow-sm'
                : 'text-gray-500 hover:text-gray-700 dark:hover:text-gray-300'
            }`}
          >
            {t.isolated}
          </button>
        </div>

        <button
          onClick={() => setShowLeveragePopup(true)}
          className="flex items-center space-x-1 bg-gray-100 dark:bg-slate-800 hover:bg-gray-200 dark:hover:bg-slate-700 px-3 py-1.5 rounded text-xs font-bold text-slate-900 dark:text-white transition-colors border border-gray-200 dark:border-slate-700"
        >
          <span>{leverage}x</span>
          <Edit3 size={12} className="text-gray-500" />
        </button>
      </div>

      {/* 2. Order Type Toggle */}
      <div className="flex bg-gray-100 dark:bg-slate-800 border border-gray-200 dark:border-slate-700 rounded p-0.5 mb-4">
        <button
          onClick={() => setType(OrderType.MARKET)}
          className={`flex-1 py-1.5 text-xs font-bold rounded transition-all ${
            type === OrderType.MARKET
              ? 'bg-slate-500 text-white shadow'
              : 'text-gray-500 hover:text-gray-700 dark:hover:text-gray-300'
          }`}
        >
          {t.market}
        </button>
        <button
          onClick={() => setType(OrderType.LIMIT)}
          className={`flex-1 py-1.5 text-xs font-bold rounded transition-all ${
            type === OrderType.LIMIT
              ? 'bg-slate-500 text-white shadow'
              : 'text-gray-500 hover:text-gray-700 dark:hover:text-gray-300'
          }`}
        >
          {t.limit}
        </button>
      </div>

      {/* 3. Price Input */}
      <div className="mb-3">
        <div className="text-xs text-gray-500 mb-1">{t.price}</div>
        <div className="relative">
          <input
            type={type === OrderType.LIMIT ? "number" : "text"}
            value={type === OrderType.LIMIT ? price : ""}
            onChange={(e) => setPrice(e.target.value)}
            disabled={type === OrderType.MARKET}
            placeholder={type === OrderType.MARKET ? `${t.market} ${t.price}` : lastPrice.toFixed(2)}
            className={`w-full bg-transparent border rounded p-2.5 text-sm outline-none transition font-mono ${
               type === OrderType.MARKET 
                 ? 'border-gray-200 dark:border-slate-700 text-gray-500 italic cursor-not-allowed bg-gray-50 dark:bg-slate-800/50' 
                 : 'border-gray-300 dark:border-slate-600 text-slate-900 dark:text-white focus:border-brand-500'
            }`}
          />
        </div>
      </div>

      {/* 4. Amount Input */}
      <div className="mb-1">
        <div className="flex justify-between text-xs mb-1">
          <span className="text-gray-500">{t.amount}</span>
          <span className="text-gray-500">{t.avail}: <span className="text-slate-900 dark:text-slate-200 font-mono">{availableBalance.toFixed(2)} USDC</span></span>
        </div>
        <div className="relative flex items-center">
          <input
            type="number"
            value={amount}
            onChange={(e) => handleAmountChange(e.target.value)}
            className="w-full bg-transparent border border-gray-300 dark:border-slate-600 rounded p-2.5 pr-20 text-sm text-slate-900 dark:text-white focus:border-brand-500 outline-none transition font-bold font-mono"
            placeholder="0.00"
          />
          <div className="absolute right-0 h-full flex items-center pr-2">
             <span className="bg-gray-200 dark:bg-slate-700 text-xs font-bold px-2 py-1 rounded text-slate-700 dark:text-slate-300">XAU</span>
          </div>
        </div>
      </div>

      {/* 5. Slider with Circle Thumb */}
      <div className="mb-8 px-1 mt-10 relative">
        <input
          type="range"
          min="0"
          max="100"
          step="1"
          value={sliderValue}
          onChange={(e) => handleSliderChange(parseFloat(e.target.value))}
          className="w-full h-1 bg-gray-200 dark:bg-slate-700 rounded-lg appearance-none cursor-pointer accent-transparent z-10 relative"
          style={{
            WebkitAppearance: 'none',
            background: `linear-gradient(to right, #EAB308 0%, #EAB308 ${sliderValue}%, ${theme === 'dark' ? '#334155' : '#E2E8F0'} ${sliderValue}%, ${theme === 'dark' ? '#334155' : '#E2E8F0'} 100%)`
          }}
        />
        {/* Customized Circle Thumb with Text */}
        <div 
          className="absolute -top-[14px] w-9 h-9 bg-brand-500 border-2 border-white dark:border-slate-900 rounded-full flex items-center justify-center text-[10px] font-bold text-slate-900 shadow-lg pointer-events-none transition-all duration-75 transform -translate-x-1/2"
          style={{ left: `${sliderValue}%` }}
        >
          {Math.round(sliderValue)}%
        </div>

        <div className="flex justify-between mt-4 text-[10px] text-gray-500 font-medium">
          <span className="cursor-pointer hover:text-brand-500" onClick={() => handleSliderChange(0)}>0%</span>
          <span className="cursor-pointer hover:text-brand-500" onClick={() => handleSliderChange(25)}>25%</span>
          <span className="cursor-pointer hover:text-brand-500" onClick={() => handleSliderChange(50)}>50%</span>
          <span className="cursor-pointer hover:text-brand-500" onClick={() => handleSliderChange(75)}>75%</span>
          <span className="cursor-pointer hover:text-brand-500" onClick={() => handleSliderChange(100)}>100%</span>
        </div>
      </div>

      {/* 6. Action Buttons */}
      <div className="grid grid-cols-2 gap-3 mb-4">
        <button
          onClick={() => handleOrderClick(OrderSide.BUY)}
          className="py-3 bg-trade-up hover:bg-green-600 text-white font-bold rounded-lg transition-colors shadow-lg shadow-green-900/20"
        >
          {t.buyLong}
        </button>
        <button
          onClick={() => handleOrderClick(OrderSide.SELL)}
          className="py-3 bg-trade-down hover:bg-red-600 text-white font-bold rounded-lg transition-colors shadow-lg shadow-red-900/20"
        >
          {t.sellShort}
        </button>
      </div>

      {/* 7. Bottom Info Grid */}
      <div className="grid grid-cols-2 gap-4 text-xs border-t border-dashed border-gray-200 dark:border-slate-700 pt-4 mt-auto">
        <div className="space-y-1.5">
           <div className="flex justify-between">
             <span className="text-gray-500">{t.liqPrice}</span>
             <span className="text-orange-500 font-mono">{liqPriceLong.toFixed(2)}</span>
           </div>
           <div className="flex justify-between">
             <span className="text-gray-500">{t.margin}</span>
             <span className="text-slate-900 dark:text-slate-300 font-mono">{marginCost.toFixed(1)}</span>
           </div>
           <div className="flex justify-between">
             <span className="text-gray-500">{t.max}</span>
             <span className="text-slate-900 dark:text-slate-300 font-mono">{maxAmount.toFixed(2)}</span>
           </div>
        </div>

        <div className="space-y-1.5 pl-4 border-l border-gray-200 dark:border-slate-800">
           <div className="flex justify-between">
             <span className="text-gray-500">{t.liqPrice}</span>
             <span className="text-orange-500 font-mono">{liqPriceShort.toFixed(2)}</span>
           </div>
           <div className="flex justify-between">
             <span className="text-gray-500">{t.margin}</span>
             <span className="text-slate-900 dark:text-slate-300 font-mono">{marginCost.toFixed(1)}</span>
           </div>
           <div className="flex justify-between">
             <span className="text-gray-500">{t.max}</span>
             <span className="text-slate-900 dark:text-slate-300 font-mono">{maxAmount.toFixed(2)}</span>
           </div>
        </div>
      </div>

      {/* Leverage Popup Modal */}
      {showLeveragePopup && (
        <>
          <div className="fixed inset-0 bg-black/50 z-[100] backdrop-blur-[1px]" onClick={() => setShowLeveragePopup(false)} />
          <div className="absolute top-16 left-4 right-4 bg-white dark:bg-dark-card border border-gray-200 dark:border-slate-700 rounded-lg shadow-2xl z-[101] p-4 animate-in zoom-in-95 duration-200">
            <div className="flex justify-between items-center mb-4">
              <span className="font-bold text-sm text-slate-900 dark:text-white">Adjust Leverage</span>
              <button onClick={() => setShowLeveragePopup(false)} className="text-gray-500 hover:text-slate-900 dark:hover:text-white"><X size={16} /></button>
            </div>

            <div className="bg-gray-100 dark:bg-slate-800 rounded border border-gray-200 dark:border-slate-700 p-2 mb-6 text-center">
               <span className="text-2xl font-bold text-brand-500">{leverage}x</span>
            </div>

            <input
              type="range"
              min="1"
              max="20"
              step="1"
              value={leverage}
              onChange={(e) => setLeverage(parseInt(e.target.value))}
              className="w-full h-2 bg-gray-200 dark:bg-slate-700 rounded-lg appearance-none cursor-pointer accent-brand-500 mb-4"
            />
            <div className="flex justify-between text-xs text-gray-500 mb-4 font-mono">
              <span>1x</span>
              <span>10x</span>
              <span>20x</span>
            </div>
             <button 
               onClick={() => setShowLeveragePopup(false)}
               className="w-full py-2 bg-brand-500 hover:bg-brand-600 text-white font-bold rounded text-sm transition-colors"
             >
               Confirm
             </button>
          </div>
        </>
      )}

    </div>
  );
};

import React, { useState } from 'react';
import { Position, Order, Language, MarginMode, OrderType } from '../types';
import { TRANSLATIONS, MOCK_HISTORY, MOCK_TRADES, MOCK_ASSETS, INITIAL_MARKET_DATA } from '../constants';
import { XCircle, Edit3, Trash2, X, ChevronDown, Repeat } from 'lucide-react';

interface PositionTableProps {
  positions: Position[];
  orders: Order[];
  lang: Language;
  onClosePosition: (id: string, type: OrderType, price?: number, amount?: number) => void;
  onCancelOrder: (id: string) => void;
  onEditMargin: (position: Position) => void;
  onCloseAll: () => void;
  onCancelAll: () => void;
}

export const PositionTable: React.FC<PositionTableProps> = ({ 
  positions, 
  orders, 
  lang, 
  onClosePosition, 
  onCancelOrder,
  onEditMargin,
  onCloseAll,
  onCancelAll
}) => {
  const t = TRANSLATIONS[lang];
  const [activeTab, setActiveTab] = useState<'positions' | 'orders' | 'history' | 'trades' | 'assets'>('positions');
  const [closingPos, setClosingPos] = useState<Position | null>(null);

  const CloseModal = ({ pos, onClose }: { pos: Position, onClose: () => void }) => {
    const [closeType, setCloseType] = useState<OrderType>(OrderType.MARKET);
    const [closePrice, setClosePrice] = useState<string>(INITIAL_MARKET_DATA.lastPrice.toFixed(2));
    const [closeAmount, setCloseAmount] = useState<string>(pos.size.toString());
    const [unit, setUnit] = useState<'XAU' | 'USDC'>('XAU');
    const [sliderVal, setSliderVal] = useState(100);

    const handleConfirm = () => {
      onClosePosition(pos.id, closeType, parseFloat(closePrice), parseFloat(closeAmount));
      onClose();
    };

    const handleSlider = (val: number) => {
      setSliderVal(val);
      setCloseAmount((pos.size * val / 100).toFixed(4));
    };

    const estPnl = (parseFloat(closeAmount) || 0) * (closeType === OrderType.MARKET ? pos.markPrice : parseFloat(closePrice) || pos.markPrice) - (parseFloat(closeAmount) || 0) * pos.entryPrice;
    const isLong = pos.side === 'BUY';

    return (
      <div className="fixed inset-0 z-[200] flex items-center justify-center bg-black/70 backdrop-blur-sm p-4">
        <div className="w-full max-w-[400px] bg-[#f9f9f9] dark:bg-[#1a1c22] border border-gray-200 dark:border-slate-800 rounded-lg shadow-2xl overflow-hidden animate-in fade-in zoom-in duration-200">
          <div className="flex items-center justify-between px-6 py-4 border-b border-gray-100 dark:border-slate-800">
            <h3 className="text-lg font-bold text-slate-900 dark:text-white">{t.closePos}</h3>
            <button onClick={onClose} className="text-gray-400 hover:text-slate-900 dark:hover:text-white transition"><X size={20} /></button>
          </div>

          <div className="p-6 space-y-5">
            <div className="flex justify-between text-sm">
              <span className="text-gray-500">{t.tradingPair}</span>
              <span className="font-bold text-teal-600 dark:text-teal-400 font-mono">
                {pos.symbol} / {isLong ? t.long : t.short} / {pos.leverage}x
              </span>
            </div>
            <div className="flex justify-between text-sm">
              <span className="text-gray-500">{t.entryPrice}</span>
              <span className="text-slate-900 dark:text-slate-300 font-mono">{pos.entryPrice.toFixed(4)}</span>
            </div>
            <div className="flex justify-between text-sm">
              <span className="text-gray-500">{t.markPrice}</span>
              <span className="text-slate-900 dark:text-slate-300 font-mono">{pos.markPrice.toFixed(4)}</span>
            </div>

            <div className="h-px bg-gray-100 dark:bg-slate-800" />

            <div className="grid grid-cols-2 gap-4">
              <div className="space-y-1.5">
                <label className="text-xs text-gray-500">{t.closePrice}</label>
                <input 
                  type="number"
                  disabled={closeType === OrderType.MARKET}
                  value={closeType === OrderType.MARKET ? "" : closePrice}
                  onChange={e => setClosePrice(e.target.value)}
                  placeholder={closeType === OrderType.MARKET ? t.market : ""}
                  className="w-full bg-gray-100 dark:bg-slate-800/50 border border-gray-200 dark:border-slate-700 rounded p-2 text-sm font-mono outline-none"
                />
              </div>
              <div className="space-y-1.5">
                <label className="text-xs text-gray-500">{t.limit}/{t.market}</label>
                <div 
                  onClick={() => setCloseType(prev => prev === OrderType.MARKET ? OrderType.LIMIT : OrderType.MARKET)}
                  className="flex items-center justify-between bg-gray-100 dark:bg-slate-800/50 border border-gray-200 dark:border-slate-700 rounded p-2 text-sm cursor-pointer hover:bg-gray-200 dark:hover:bg-slate-700 transition"
                >
                  <span className="text-slate-900 dark:text-slate-300">{closeType === OrderType.MARKET ? t.market : t.limit}</span>
                  <Repeat size={14} className="text-gray-500" />
                </div>
              </div>
            </div>

            <div className="space-y-1.5">
              <label className="text-xs text-gray-500">{t.closeAmount}</label>
              <div className="relative">
                <input 
                  type="number"
                  value={closeAmount}
                  onChange={e => setCloseAmount(e.target.value)}
                  className="w-full bg-gray-100 dark:bg-slate-800/50 border border-gray-200 dark:border-slate-700 rounded p-2 pr-20 text-sm font-mono outline-none"
                />
                <div className="absolute right-0 top-0 h-full flex items-center pr-2 border-l border-gray-200 dark:border-slate-700 ml-2">
                   <button onClick={() => setUnit(u => u === 'XAU' ? 'USDC' : 'XAU')} className="flex items-center text-xs font-bold text-gray-500 px-2 space-x-1">
                     <span>{unit}</span>
                     <ChevronDown size={12} />
                   </button>
                </div>
              </div>
            </div>

            <div className="relative pt-4 pb-2">
              <div className="flex justify-between h-1 bg-gray-200 dark:bg-slate-800 rounded relative">
                <div className="absolute h-full bg-[#dca85e] rounded" style={{ width: `${sliderVal}%` }} />
                {[0, 25, 50, 75, 100].map(v => (
                   <div 
                    key={v} 
                    onClick={() => handleSlider(v)}
                    className="w-2 h-2 bg-gray-400 dark:bg-slate-600 rounded-sm cursor-pointer z-10 -translate-y-[2px]" 
                   />
                ))}
              </div>
              <div className="flex justify-between text-[10px] text-gray-500 mt-2 font-mono">
                <span>0%</span>
                <span>100%</span>
              </div>
            </div>

            <div className="space-y-1">
              <div className="flex justify-between text-xs">
                <span className="text-gray-500">{t.heldAmount}</span>
                <span className="text-slate-900 dark:text-slate-300 font-mono">{pos.size} XAU</span>
              </div>
              <div className="flex justify-between text-xs">
                <span className="text-gray-500">{t.estPnl}</span>
                <span className={`font-mono font-bold ${estPnl >= 0 ? 'text-teal-600 dark:text-teal-400' : 'text-trade-down'}`}>
                  {estPnl.toFixed(2)} USDC
                </span>
              </div>
            </div>

            <div className="grid grid-cols-2 gap-4 pt-2">
              <button 
                onClick={onClose}
                className="py-2.5 border border-[#dca85e] text-[#dca85e] rounded font-bold text-sm hover:bg-[#dca85e]/10 transition"
              >
                {t.cancel}
              </button>
              <button 
                onClick={handleConfirm}
                className="py-2.5 bg-[#dca85e] hover:bg-[#c99750] text-slate-900 rounded font-bold text-sm transition shadow-lg shadow-[#dca85e]/20"
              >
                {t.confirm}
              </button>
            </div>
          </div>
        </div>
      </div>
    );
  };

  return (
    <div className="flex flex-col h-full bg-white dark:bg-dark-card border-t border-gray-200 dark:border-dark-border overflow-hidden">
      <div className="flex items-center justify-between px-4 border-b border-gray-200 dark:border-dark-border overflow-x-auto shrink-0">
        <div className="flex space-x-6 shrink-0">
          {[
            { id: 'positions', label: t.positions },
            { id: 'orders', label: t.openOrders },
            { id: 'history', label: t.history },
            { id: 'trades', label: t.tradeHistory },
            { id: 'assets', label: t.assetsHistory },
          ].map(tab => (
            <button
              key={tab.id}
              onClick={() => setActiveTab(tab.id as any)}
              className={`py-3 text-sm font-medium border-b-2 transition-colors whitespace-nowrap ${
                activeTab === tab.id 
                  ? 'border-brand-500 text-brand-500' 
                  : 'border-transparent text-gray-500 dark:text-gray-400 hover:text-slate-900 dark:hover:text-slate-200'
              }`}
            >
              {tab.label}
              {(tab.id === 'positions' && positions.length > 0) && ` (${positions.length})`}
              {(tab.id === 'orders' && orders.length > 0) && ` (${orders.length})`}
            </button>
          ))}
        </div>

        <div className="flex space-x-3 ml-4">
          {activeTab === 'positions' && positions.length > 0 && (
            <button onClick={onCloseAll} className="text-xs text-trade-down hover:bg-trade-down/10 px-2 py-1 rounded transition-colors">{t.closeAll}</button>
          )}
          {activeTab === 'orders' && orders.length > 0 && (
             <button onClick={onCancelAll} className="text-xs text-trade-down hover:bg-trade-down/10 px-2 py-1 rounded transition-colors">{t.cancelAll}</button>
          )}
        </div>
      </div>

      <div className="flex-1 overflow-auto custom-scrollbar">
        {activeTab === 'positions' && (
          <table className="w-full text-left text-sm border-collapse min-w-[900px]">
            <thead className="sticky top-0 bg-white dark:bg-dark-card z-10 shadow-sm">
              <tr className="text-gray-500 dark:text-gray-400 border-b border-gray-200 dark:border-slate-800">
                <th className="py-3 px-4 font-medium">{t.symbol}</th>
                <th className="py-3 px-4 font-medium">{t.nominalValue}</th>
                <th className="py-3 px-4 font-medium">{t.entryPrice}</th>
                <th className="py-3 px-4 font-medium">{t.markPrice}</th>
                <th className="py-3 px-4 font-medium">{t.liqPrice}</th>
                <th className="py-3 px-4 font-medium">{t.margin}</th>
                <th className="py-3 px-4 font-medium text-right">{t.unrealizedPnl}</th>
                <th className="py-3 px-4 font-medium text-right">{t.action}</th>
              </tr>
            </thead>
            <tbody className="text-slate-700 dark:text-slate-300">
              {positions.length === 0 ? (
                <tr><td colSpan={8} className="text-center py-20 text-gray-500">No Positions</td></tr>
              ) : positions.map((pos) => {
                const isLong = pos.side === 'BUY';
                return (
                  <tr key={pos.id} className="border-b border-gray-100 dark:border-slate-800/50 hover:bg-gray-50 dark:hover:bg-slate-800/30 transition-colors">
                    <td className="py-4 px-4">
                      <div className="flex flex-col">
                        <span className="font-bold text-slate-900 dark:text-white text-base font-mono">{pos.symbol}</span>
                        <div className="flex items-center space-x-2 mt-0.5">
                           <span className={`text-xs font-bold ${isLong ? 'text-trade-up' : 'text-trade-down'}`}>
                             {isLong ? t.long : t.short}
                           </span>
                           <span className="text-[10px] text-gray-500 font-bold bg-gray-100 dark:bg-slate-800 px-1 rounded">
                             {pos.leverage}x
                           </span>
                        </div>
                      </div>
                    </td>
                    <td className="py-4 px-4">
                       <div className="flex flex-col">
                         <span className="font-mono text-slate-900 dark:text-slate-200">{(pos.size * pos.markPrice).toFixed(2)} USDC</span>
                         <span className="text-xs text-gray-500 font-mono">{pos.size} XAU</span>
                       </div>
                    </td>
                    <td className="py-4 px-4 font-mono">{pos.entryPrice.toFixed(2)}</td>
                    <td className="py-4 px-4 font-mono text-slate-400">{pos.markPrice.toFixed(2)}</td>
                    <td className="py-4 px-4 text-orange-500 font-mono">{pos.liquidationPrice.toFixed(2)}</td>
                    <td className="py-4 px-4">
                      <div className="flex flex-col">
                        <div className="flex items-center space-x-1 font-mono">
                          <span>{pos.margin.toFixed(2)}</span>
                          {pos.marginMode === MarginMode.ISOLATED && (
                            <button onClick={() => onEditMargin(pos)} className="text-gray-400 hover:text-brand-500"><Edit3 size={12} /></button>
                          )}
                        </div>
                        <span className="text-[10px] text-gray-500 font-bold uppercase">{pos.marginMode === MarginMode.CROSS ? t.cross : t.isolated}</span>
                      </div>
                    </td>
                    <td className={`py-4 px-4 text-right font-mono ${pos.pnl >= 0 ? 'text-trade-up' : 'text-trade-down'}`}>
                      <div className="font-bold">{pos.pnl >= 0 ? '+' : ''}{pos.pnl.toFixed(2)}</div>
                      <div className="text-xs">{pos.pnlPercent >= 0 ? '+' : ''}{pos.pnlPercent.toFixed(2)}%</div>
                    </td>
                    <td className="py-4 px-4 text-right">
                      <button 
                        onClick={() => setClosingPos(pos)}
                        className="px-4 py-1.5 bg-gray-100 dark:bg-slate-800 hover:bg-brand-500 hover:text-white rounded font-bold text-xs transition-all shadow-sm"
                      >
                        {t.market} / {t.limit}
                      </button>
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        )}

        {/* Placeholder for other tabs (Order History, Trades, etc) - remains roughly as before or expanded as needed */}
        {activeTab !== 'positions' && (
           <div className="p-4 text-gray-500 text-center py-20">Demo data for {activeTab}</div>
        )}
      </div>

      {closingPos && <CloseModal pos={closingPos} onClose={() => setClosingPos(null)} />}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Header } from './components/Header';
import { MarketStats } from './components/MarketStats';
import { CandleChart } from './components/CandleChart';
import { OrderBook } from './components/OrderBook';
import { TradeForm } from './components/TradeForm';
import { PositionTable } from './components/PositionTable';
import { AccountInfo } from './components/AccountInfo';
import { NotificationContainer } from './components/Notification';
import { WalletModal, AssetModal } from './components/Modals';
import { INITIAL_MARKET_DATA, MOCK_POSITIONS, TRANSLATIONS, INITIAL_ACCOUNT_INFO } from './constants';
import { Language, Theme, MarketData, Position, Order, Notification, OrderSide, OrderType, MarginMode, AccountInfo as AccountInfoType } from './types';

export default function App() {
  const [lang, setLang] = useState<Language>('en');
  const [theme, setTheme] = useState<Theme>('dark');
  const [isConnected, setIsConnected] = useState(false);
  const [marketData, setMarketData] = useState<MarketData>(INITIAL_MARKET_DATA);
  const [positions, setPositions] = useState<Position[]>(MOCK_POSITIONS);
  const [orders, setOrders] = useState<Order[]>([]);
  const [notifications, setNotifications] = useState<Notification[]>([]);
  const [accountInfo, setAccountInfo] = useState<AccountInfoType>(INITIAL_ACCOUNT_INFO);

  const [showWalletModal, setShowWalletModal] = useState(false);
  const [assetModal, setAssetModal] = useState<{ isOpen: boolean, type: 'deposit' | 'withdraw' }>({ isOpen: false, type: 'deposit' });
  const [showMarginModal, setShowMarginModal] = useState<Position | null>(null);

  const addNotification = (type: 'success' | 'error' | 'info', message: string) => {
    const id = Date.now().toString();
    setNotifications(prev => [...prev, { id, type, message }]);
  };

  const removeNotification = (id: string) => {
    setNotifications(prev => prev.filter(n => n.id !== id));
  };

  const handleConnect = () => {
    setIsConnected(true);
    addNotification('success', TRANSLATIONS[lang].success + ': Wallet Connected');
  };

  const handleAssetConfirm = (amount: number) => {
    if (assetModal.type === 'deposit') {
      setAccountInfo(prev => ({ ...prev, marginBalance: prev.marginBalance + amount, walletBalance: prev.walletBalance - amount }));
      addNotification('success', `${amount} USDC Deposited Successfully`);
    } else {
      setAccountInfo(prev => ({ ...prev, marginBalance: prev.marginBalance - amount, walletBalance: prev.walletBalance + amount }));
      addNotification('success', `${amount} USDC Withdrawn Successfully`);
    }
  };

  const handleOrder = (side: OrderSide, type: OrderType, size: number, price: number, leverage: number, marginMode: MarginMode) => {
    if (!isConnected) {
      setShowWalletModal(true);
      return;
    }

    if (type === OrderType.MARKET) {
      const newPos: Position = {
        id: Date.now().toString(),
        symbol: 'XAUUSDC',
        side,
        size,
        entryPrice: price,
        markPrice: price,
        leverage,
        margin: (size * price) / leverage,
        marginMode,
        pnl: 0,
        pnlPercent: 0,
        liquidationPrice: side === OrderSide.BUY ? price * 0.8 : price * 1.2
      };
      setPositions(prev => [newPos, ...prev]);
      addNotification('success', `${side === 'BUY' ? 'Long' : 'Short'} ${size} XAU Filled`);
    } else {
      const newOrder: Order = {
        id: Date.now().toString(),
        symbol: 'XAUUSDC',
        side,
        type,
        price,
        amount: size,
        filled: 0,
        status: 'OPEN',
        time: new Date().toISOString().replace('T', ' ').substring(0, 19)
      };
      setOrders(prev => [newOrder, ...prev]);
      addNotification('success', 'Limit Order Placed');
    }
  };

  const handleClosePosition = (id: string, type: OrderType, price?: number, amountToClose?: number) => {
    const pos = positions.find(p => p.id === id);
    if (!pos) return;

    if (type === OrderType.MARKET) {
      if (!amountToClose || amountToClose >= pos.size) {
        setPositions(prev => prev.filter(p => p.id !== id));
        addNotification('success', 'Position Closed at Market Price');
      } else {
        setPositions(prev => prev.map(p => p.id === id ? { ...p, size: p.size - amountToClose } : p));
        addNotification('success', `Partial Close: ${amountToClose} XAU at Market`);
      }
    } else {
      addNotification('info', `Limit Close Order Placed at ${price}`);
    }
  };

  const handleCancelOrder = (id: string) => {
    setOrders(prev => prev.filter(o => o.id !== id));
    addNotification('success', 'Order Canceled');
  };

  const handleCloseAll = () => {
    setPositions([]);
    addNotification('success', 'All Positions Closed');
  };

  const handleCancelAll = () => {
    setOrders([]);
    addNotification('success', 'All Orders Canceled');
  };

  const handleMarginAdjust = (amount: number, type: 'add' | 'remove') => {
    if (!showMarginModal) return;
    setPositions(prev => prev.map(p => {
      if (p.id === showMarginModal.id) {
        return {
          ...p,
          margin: type === 'add' ? p.margin + amount : p.margin - amount
        };
      }
      return p;
    }));
    setShowMarginModal(null);
    addNotification('success', `Margin ${type === 'add' ? 'Added' : 'Removed'}`);
  };

  return (
    <div className={`flex flex-col h-screen ${theme} bg-gray-50 dark:bg-dark-bg text-slate-900 dark:text-slate-200 font-sans overflow-hidden transition-colors`}>
      <Header 
        lang={lang} 
        setLang={setLang} 
        theme={theme} 
        setTheme={setTheme}
        isConnected={isConnected}
        onConnectClick={() => setShowWalletModal(true)}
        onDeposit={() => setAssetModal({ isOpen: true, type: 'deposit' })}
        onWithdraw={() => setAssetModal({ isOpen: true, type: 'withdraw' })}
      />

      <MarketStats data={marketData} lang={lang} />

      <main className="flex-1 flex overflow-hidden">
        <div className="flex-1 flex flex-col min-w-0">
          <div className="flex-[3] flex min-h-[450px] border-b border-gray-200 dark:border-dark-border">
            <div className="flex-1 relative border-r border-gray-200 dark:border-dark-border">
               <CandleChart lang={lang} />
            </div>
            <div className="w-[300px] hidden lg:block bg-white dark:bg-dark-card shrink-0">
              <OrderBook lang={lang} lastPrice={marketData.lastPrice} />
            </div>
          </div>

          <div className="flex-[2] min-h-[300px] overflow-hidden">
             <PositionTable 
               positions={positions} 
               orders={orders} 
               lang={lang}
               onClosePosition={handleClosePosition}
               onCancelOrder={handleCancelOrder}
               onEditMargin={(pos) => setShowMarginModal(pos)}
               onCloseAll={handleCloseAll}
               onCancelAll={handleCancelAll}
             />
          </div>
        </div>

        <div className="w-[340px] flex flex-col border-l border-gray-200 dark:border-dark-border bg-white dark:bg-dark-card z-10 shrink-0">
          <div className="flex-1 overflow-y-auto">
            <TradeForm 
              lang={lang} 
              isConnected={isConnected} 
              onConnect={() => setShowWalletModal(true)} 
              onOrder={handleOrder}
              lastPrice={marketData.lastPrice}
              availableBalance={accountInfo.marginBalance} 
            />
          </div>
          <div className="shrink-0 border-t border-gray-200 dark:border-dark-border">
             <AccountInfo lang={lang} info={accountInfo} />
          </div>
        </div>
      </main>

      <NotificationContainer notifications={notifications} removeNotification={removeNotification} />

      <WalletModal isOpen={showWalletModal} onClose={() => setShowWalletModal(false)} lang={lang} onConnect={handleConnect} />

      <AssetModal
        isOpen={assetModal.isOpen}
        onClose={() => setAssetModal(prev => ({ ...prev, isOpen: false }))}
        lang={lang}
        type={assetModal.type}
        maxAmount={assetModal.type === 'deposit' ? accountInfo.walletBalance : accountInfo.marginBalance}
        onConfirm={handleAssetConfirm}
      />

      {showMarginModal && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-[300]">
          <div className="bg-white dark:bg-dark-card p-6 rounded-lg w-80 shadow-2xl border border-gray-200 dark:border-slate-700 animate-in zoom-in duration-200">
             <h3 className="text-lg font-bold mb-4 dark:text-white">Adjust Margin</h3>
             <p className="text-sm text-gray-500 mb-4">{showMarginModal.symbol} - {showMarginModal.marginMode} {showMarginModal.leverage}x</p>
             <div className="flex space-x-2 mb-4">
               <button onClick={() => handleMarginAdjust(100, 'add')} className="flex-1 py-2 bg-trade-up text-white rounded hover:bg-green-600">Add 100</button>
               <button onClick={() => handleMarginAdjust(100, 'remove')} className="flex-1 py-2 bg-trade-down text-white rounded hover:bg-red-600">Remove 100</button>
             </div>
             <button onClick={() => setShowMarginModal(null)} className="w-full py-2 text-gray-500 hover:bg-gray-100 dark:hover:bg-slate-700 rounded">Cancel</button>
          </div>
        </div>
      )}
    </div>
  );
}

import React, { useState, useEffect, useRef } from 'react';
import { Language, MarginMode, OrderType, OrderSide, Theme } from '../types';
import { TRANSLATIONS } from '../constants';
import { Edit3, X } from 'lucide-react';

interface TradeFormProps {
  lang: Language;
  theme: Theme;
  isConnected: boolean;
  onConnect: () => void;
  onOrder: (side: OrderSide, type: OrderType, size: number, price: number, leverage: number, marginMode: MarginMode) => void;
  lastPrice: number;
  availableBalance: number;
}

export const TradeForm: React.FC<TradeFormProps> = ({ lang, theme, isConnected, onConnect, onOrder, lastPrice, availableBalance }) => {
  const t = TRANSLATIONS[lang];

  // Form State
  const [type, setType] = useState<OrderType>(OrderType.MARKET);
  const [marginMode, setMarginMode] = useState<MarginMode>(MarginMode.CROSS);
  const [leverage, setLeverage] = useState<number>(20);
  const [amount, setAmount] = useState<string>('');
  const [price, setPrice] = useState<string>('');
  const [sliderValue, setSliderValue] = useState(0);

  // UI State
  const [showLeveragePopup, setShowLeveragePopup] = useState(false);

  // Derived Values
  const effectivePrice = type === OrderType.LIMIT && price ? parseFloat(price) : lastPrice;
  const maxAmount = effectivePrice > 0 ? (availableBalance * leverage) / effectivePrice : 0;

  const handleSliderChange = (val: number) => {
    setSliderValue(val);
    if (maxAmount > 0) {
      const newAmount = (maxAmount * val / 100).toFixed(4);
      setAmount(newAmount);
    }
  };

  const handleAmountChange = (val: string) => {
    setAmount(val);
    const num = parseFloat(val);
    if (!isNaN(num) && maxAmount > 0) {
      setSliderValue(Math.min(100, (num / maxAmount) * 100));
    } else {
      setSliderValue(0);
    }
  };

  const handleOrderClick = (side: OrderSide) => {
    if (!isConnected) {
      onConnect();
      return;
    }
    if (!amount || parseFloat(amount) <= 0) return;
    onOrder(side, type, parseFloat(amount), effectivePrice, leverage, marginMode);
    setAmount('');
    setSliderValue(0);
  };

  const parsedAmount = parseFloat(amount) || 0;
  const marginCost = parsedAmount * effectivePrice / leverage;
  const liqPriceLong = effectivePrice * (1 - 1/leverage + 0.005);
  const liqPriceShort = effectivePrice * (1 + 1/leverage - 0.005);

  return (
    <div className="flex flex-col h-full bg-white dark:bg-dark-card border-l border-gray-200 dark:border-dark-border p-4 relative">

      {/* 1. Header: Margin Mode & Leverage */}
      <div className="flex justify-between items-center mb-4">
        <div className="flex bg-gray-100 dark:bg-slate-800 rounded border border-gray-200 dark:border-slate-700 p-0.5">
          <button
            onClick={() => setMarginMode(MarginMode.CROSS)}
            className={`px-3 py-1.5 text-xs font-bold rounded transition-all ${
              marginMode === MarginMode.CROSS
                ? 'bg-slate-500/30 text-brand-500 shadow-sm'
                : 'text-gray-500 hover:text-gray-700 dark:hover:text-gray-300'
            }`}
          >
            {t.cross}
          </button>
          <button
            onClick={() => setMarginMode(MarginMode.ISOLATED)}
            className={`px-3 py-1.5 text-xs font-bold rounded transition-all ${
              marginMode === MarginMode.ISOLATED
                ? 'bg-slate-500/30 text-brand-500 shadow-sm'
                : 'text-gray-500 hover:text-gray-700 dark:hover:text-gray-300'
            }`}
          >
            {t.isolated}
          </button>
        </div>

        <button
          onClick={() => setShowLeveragePopup(true)}
          className="flex items-center space-x-1 bg-gray-100 dark:bg-slate-800 hover:bg-gray-200 dark:hover:bg-slate-700 px-3 py-1.5 rounded text-xs font-bold text-slate-900 dark:text-white transition-colors border border-gray-200 dark:border-slate-700"
        >
          <span>{leverage}x</span>
          <Edit3 size={12} className="text-gray-500" />
        </button>
      </div>

      {/* 2. Order Type Toggle */}
      <div className="flex bg-gray-100 dark:bg-slate-800 border border-gray-200 dark:border-slate-700 rounded p-0.5 mb-4">
        <button
          onClick={() => setType(OrderType.MARKET)}
          className={`flex-1 py-1.5 text-xs font-bold rounded transition-all ${
            type === OrderType.MARKET
              ? 'bg-slate-500 text-white shadow'
              : 'text-gray-500 hover:text-gray-700 dark:hover:text-gray-300'
          }`}
        >
          {t.market}
        </button>
        <button
          onClick={() => setType(OrderType.LIMIT)}
          className={`flex-1 py-1.5 text-xs font-bold rounded transition-all ${
            type === OrderType.LIMIT
              ? 'bg-slate-500 text-white shadow'
              : 'text-gray-500 hover:text-gray-700 dark:hover:text-gray-300'
          }`}
        >
          {t.limit}
        </button>
      </div>

      {/* 3. Price Input */}
      <div className="mb-3">
        <div className="text-xs text-gray-500 mb-1">{t.price}</div>
        <div className="relative">
          <input
            type={type === OrderType.LIMIT ? "number" : "text"}
            value={type === OrderType.LIMIT ? price : ""}
            onChange={(e) => setPrice(e.target.value)}
            disabled={type === OrderType.MARKET}
            placeholder={type === OrderType.MARKET ? `${t.market} ${t.price}` : lastPrice.toFixed(2)}
            className={`w-full bg-transparent border rounded p-2.5 text-sm outline-none transition font-mono ${
               type === OrderType.MARKET 
                 ? 'border-gray-200 dark:border-slate-700 text-gray-500 italic cursor-not-allowed bg-gray-50 dark:bg-slate-800/50' 
                 : 'border-gray-300 dark:border-slate-600 text-slate-900 dark:text-white focus:border-brand-500'
            }`}
          />
        </div>
      </div>

      {/* 4. Amount Input */}
      <div className="mb-1">
        <div className="flex justify-between text-xs mb-1">
          <span className="text-gray-500">{t.amount}</span>
          <span className="text-gray-500">{t.avail}: <span className="text-slate-900 dark:text-slate-200 font-mono">{availableBalance.toFixed(2)} USDC</span></span>
        </div>
        <div className="relative flex items-center">
          <input
            type="number"
            value={amount}
            onChange={(e) => handleAmountChange(e.target.value)}
            className="w-full bg-transparent border border-gray-300 dark:border-slate-600 rounded p-2.5 pr-20 text-sm text-slate-900 dark:text-white focus:border-brand-500 outline-none transition font-bold font-mono"
            placeholder="0.00"
          />
          <div className="absolute right-0 h-full flex items-center pr-2">
             <span className="bg-gray-200 dark:bg-slate-700 text-xs font-bold px-2 py-1 rounded text-slate-700 dark:text-slate-300">XAU</span>
          </div>
        </div>
      </div>

      {/* 5. Slider with Circle Thumb */}
      <div className="mb-8 px-1 mt-10 relative">
        <input
          type="range"
          min="0"
          max="100"
          step="1"
          value={sliderValue}
          onChange={(e) => handleSliderChange(parseFloat(e.target.value))}
          className="w-full h-1 bg-gray-200 dark:bg-slate-700 rounded-lg appearance-none cursor-pointer accent-transparent z-10 relative"
          style={{
            WebkitAppearance: 'none',
            // Fix: theme is now available from props
            background: `linear-gradient(to right, #EAB308 0%, #EAB308 ${sliderValue}%, ${theme === 'dark' ? '#334155' : '#E2E8F0'} ${sliderValue}%, ${theme === 'dark' ? '#334155' : '#E2E8F0'} 100%)`
          }}
        />
        {/* Customized Circle Thumb with Text */}
        <div 
          className="absolute -top-[14px] w-9 h-9 bg-brand-500 border-2 border-white dark:border-slate-900 rounded-full flex items-center justify-center text-[10px] font-bold text-slate-900 shadow-lg pointer-events-none transition-all duration-75 transform -translate-x-1/2"
          style={{ left: `${sliderValue}%` }}
        >
          {Math.round(sliderValue)}%
        </div>

        <div className="flex justify-between mt-4 text-[10px] text-gray-500 font-medium">
          <span className="cursor-pointer hover:text-brand-500" onClick={() => handleSliderChange(0)}>0%</span>
          <span className="cursor-pointer hover:text-brand-500" onClick={() => handleSliderChange(25)}>25%</span>
          <span className="cursor-pointer hover:text-brand-500" onClick={() => handleSliderChange(50)}>50%</span>
          <span className="cursor-pointer hover:text-brand-500" onClick={() => handleSliderChange(75)}>75%</span>
          <span className="cursor-pointer hover:text-brand-500" onClick={() => handleSliderChange(100)}>100%</span>
        </div>
      </div>

      {/* 6. Action Buttons */}
      <div className="grid grid-cols-2 gap-3 mb-4">
        <button
          onClick={() => handleOrderClick(OrderSide.BUY)}
          className="py-3 bg-trade-up hover:bg-green-600 text-white font-bold rounded-lg transition-colors shadow-lg shadow-green-900/20"
        >
          {t.buyLong}
        </button>
        <button
          onClick={() => handleOrderClick(OrderSide.SELL)}
          className="py-3 bg-trade-down hover:bg-red-600 text-white font-bold rounded-lg transition-colors shadow-lg shadow-red-900/20"
        >
          {t.sellShort}
        </button>
      </div>

      {/* 7. Bottom Info Grid */}
      <div className="grid grid-cols-2 gap-4 text-xs border-t border-dashed border-gray-200 dark:border-slate-700 pt-4 mt-auto">
        <div className="space-y-1.5">
           <div className="flex justify-between">
             <span className="text-gray-500">{t.liqPrice}</span>
             <span className="text-orange-500 font-mono">{liqPriceLong.toFixed(2)}</span>
           </div>
           <div className="flex justify-between">
             <span className="text-gray-500">{t.margin}</span>
             <span className="text-slate-900 dark:text-slate-300 font-mono">{marginCost.toFixed(1)}</span>
           </div>
           <div className="flex justify-between">
             <span className="text-gray-500">{t.max}</span>
             <span className="text-slate-900 dark:text-slate-300 font-mono">{maxAmount.toFixed(2)}</span>
           </div>
        </div>

        <div className="space-y-1.5 pl-4 border-l border-gray-200 dark:border-slate-800">
           <div className="flex justify-between">
             <span className="text-gray-500">{t.liqPrice}</span>
             <span className="text-orange-500 font-mono">{liqPriceShort.toFixed(2)}</span>
           </div>
           <div className="flex justify-between">
             <span className="text-gray-500">{t.margin}</span>
             <span className="text-slate-900 dark:text-slate-300 font-mono">{marginCost.toFixed(1)}</span>
           </div>
           <div className="flex justify-between">
             <span className="text-gray-500">{t.max}</span>
             <span className="text-slate-900 dark:text-slate-300 font-mono">{maxAmount.toFixed(2)}</span>
           </div>
        </div>
      </div>

      {/* Leverage Popup Modal */}
      {showLeveragePopup && (
        <>
          <div className="fixed inset-0 bg-black/50 z-[100] backdrop-blur-[1px]" onClick={() => setShowLeveragePopup(false)} />
          <div className="absolute top-16 left-4 right-4 bg-white dark:bg-dark-card border border-gray-200 dark:border-slate-700 rounded-lg shadow-2xl z-[101] p-4 animate-in zoom-in-95 duration-200">
            <div className="flex justify-between items-center mb-4">
              <span className="font-bold text-sm text-slate-900 dark:text-white">Adjust Leverage</span>
              <button onClick={() => setShowLeveragePopup(false)} className="text-gray-500 hover:text-slate-900 dark:hover:text-white"><X size={16} /></button>
            </div>

            <div className="bg-gray-100 dark:bg-slate-800 rounded border border-gray-200 dark:border-slate-700 p-2 mb-6 text-center">
               <span className="text-2xl font-bold text-brand-500">{leverage}x</span>
            </div>

            <input
              type="range"
              min="1"
              max="20"
              step="1"
              value={leverage}
              onChange={(e) => setLeverage(parseInt(e.target.value))}
              className="w-full h-2 bg-gray-200 dark:bg-slate-700 rounded-lg appearance-none cursor-pointer accent-brand-500 mb-4"
            />
            <div className="flex justify-between text-xs text-gray-500 mb-4 font-mono">
              <span>1x</span>
              <span>10x</span>
              <span>20x</span>
            </div>
             <button 
               onClick={() => setShowLeveragePopup(false)}
               className="w-full py-2 bg-brand-500 hover:bg-brand-600 text-white font-bold rounded text-sm transition-colors"
             >
               Confirm
             </button>
          </div>
        </>
      )}

    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Header } from './components/Header';
import { MarketStats } from './components/MarketStats';
import { CandleChart } from './components/CandleChart';
import { OrderBook } from './components/OrderBook';
import { TradeForm } from './components/TradeForm';
import { PositionTable } from './components/PositionTable';
import { AccountInfo } from './components/AccountInfo';
import { NotificationContainer } from './components/Notification';
import { WalletModal, AssetModal } from './components/Modals';
import { INITIAL_MARKET_DATA, MOCK_POSITIONS, TRANSLATIONS, INITIAL_ACCOUNT_INFO } from './constants';
import { Language, Theme, MarketData, Position, Order, Notification, OrderSide, OrderType, MarginMode, AccountInfo as AccountInfoType } from './types';

export default function App() {
  const [lang, setLang] = useState<Language>('en');
  const [theme, setTheme] = useState<Theme>('dark');
  const [isConnected, setIsConnected] = useState(false);
  const [marketData, setMarketData] = useState<MarketData>(INITIAL_MARKET_DATA);
  const [positions, setPositions] = useState<Position[]>(MOCK_POSITIONS);
  const [orders, setOrders] = useState<Order[]>([]);
  const [notifications, setNotifications] = useState<Notification[]>([]);
  const [accountInfo, setAccountInfo] = useState<AccountInfoType>(INITIAL_ACCOUNT_INFO);

  const [showWalletModal, setShowWalletModal] = useState(false);
  const [assetModal, setAssetModal] = useState<{ isOpen: boolean, type: 'deposit' | 'withdraw' }>({ isOpen: false, type: 'deposit' });
  const [showMarginModal, setShowMarginModal] = useState<Position | null>(null);

  const addNotification = (type: 'success' | 'error' | 'info', message: string) => {
    const id = Date.now().toString();
    setNotifications(prev => [...prev, { id, type, message }]);
  };

  const removeNotification = (id: string) => {
    setNotifications(prev => prev.filter(n => n.id !== id));
  };

  const handleConnect = () => {
    setIsConnected(true);
    addNotification('success', TRANSLATIONS[lang].success + ': Wallet Connected');
  };

  const handleAssetConfirm = (amount: number) => {
    if (assetModal.type === 'deposit') {
      setAccountInfo(prev => ({ ...prev, marginBalance: prev.marginBalance + amount, walletBalance: prev.walletBalance - amount }));
      addNotification('success', `${amount} USDC Deposited Successfully`);
    } else {
      setAccountInfo(prev => ({ ...prev, marginBalance: prev.marginBalance - amount, walletBalance: prev.walletBalance + amount }));
      addNotification('success', `${amount} USDC Withdrawn Successfully`);
    }
  };

  const handleOrder = (side: OrderSide, type: OrderType, size: number, price: number, leverage: number, marginMode: MarginMode) => {
    if (!isConnected) {
      setShowWalletModal(true);
      return;
    }

    if (type === OrderType.MARKET) {
      const newPos: Position = {
        id: Date.now().toString(),
        symbol: 'XAUUSDC',
        side,
        size,
        entryPrice: price,
        markPrice: price,
        leverage,
        margin: (size * price) / leverage,
        marginMode,
        pnl: 0,
        pnlPercent: 0,
        liquidationPrice: side === OrderSide.BUY ? price * 0.8 : price * 1.2
      };
      setPositions(prev => [newPos, ...prev]);
      addNotification('success', `${side === 'BUY' ? 'Long' : 'Short'} ${size} XAU Filled`);
    } else {
      const newOrder: Order = {
        id: Date.now().toString(),
        symbol: 'XAUUSDC',
        side,
        type,
        price,
        amount: size,
        filled: 0,
        status: 'OPEN',
        time: new Date().toISOString().replace('T', ' ').substring(0, 19)
      };
      setOrders(prev => [newOrder, ...prev]);
      addNotification('success', 'Limit Order Placed');
    }
  };

  const handleClosePosition = (id: string, type: OrderType, price?: number, amountToClose?: number) => {
    const pos = positions.find(p => p.id === id);
    if (!pos) return;

    if (type === OrderType.MARKET) {
      if (!amountToClose || amountToClose >= pos.size) {
        setPositions(prev => prev.filter(p => p.id !== id));
        addNotification('success', 'Position Closed at Market Price');
      } else {
        setPositions(prev => prev.map(p => p.id === id ? { ...p, size: p.size - amountToClose } : p));
        addNotification('success', `Partial Close: ${amountToClose} XAU at Market`);
      }
    } else {
      addNotification('info', `Limit Close Order Placed at ${price}`);
    }
  };

  const handleCancelOrder = (id: string) => {
    setOrders(prev => prev.filter(o => o.id !== id));
    addNotification('success', 'Order Canceled');
  };

  const handleCloseAll = () => {
    setPositions([]);
    addNotification('success', 'All Positions Closed');
  };

  const handleCancelAll = () => {
    setOrders([]);
    addNotification('success', 'All Orders Canceled');
  };

  const handleMarginAdjust = (amount: number, type: 'add' | 'remove') => {
    if (!showMarginModal) return;
    setPositions(prev => prev.map(p => {
      if (p.id === showMarginModal.id) {
        return {
          ...p,
          margin: type === 'add' ? p.margin + amount : p.margin - amount
        };
      }
      return p;
    }));
    setShowMarginModal(null);
    addNotification('success', `Margin ${type === 'add' ? 'Added' : 'Removed'}`);
  };

  return (
    <div className={`flex flex-col h-screen ${theme} bg-gray-50 dark:bg-dark-bg text-slate-900 dark:text-slate-200 font-sans overflow-hidden transition-colors`}>
      <Header 
        lang={lang} 
        setLang={setLang} 
        theme={theme} 
        setTheme={setTheme}
        isConnected={isConnected}
        onConnectClick={() => setShowWalletModal(true)}
        onDeposit={() => setAssetModal({ isOpen: true, type: 'deposit' })}
        onWithdraw={() => setAssetModal({ isOpen: true, type: 'withdraw' })}
      />

      <MarketStats data={marketData} lang={lang} />

      <main className="flex-1 flex overflow-hidden">
        <div className="flex-1 flex flex-col min-w-0">
          <div className="flex-[3] flex min-h-[450px] border-b border-gray-200 dark:border-dark-border">
            <div className="flex-1 relative border-r border-gray-200 dark:border-dark-border">
               <CandleChart lang={lang} />
            </div>
            <div className="w-[300px] hidden lg:block bg-white dark:bg-dark-card shrink-0">
              <OrderBook lang={lang} lastPrice={marketData.lastPrice} />
            </div>
          </div>

          <div className="flex-[2] min-h-[300px] overflow-hidden">
             <PositionTable 
               positions={positions} 
               orders={orders} 
               lang={lang}
               onClosePosition={handleClosePosition}
               onCancelOrder={handleCancelOrder}
               onEditMargin={(pos) => setShowMarginModal(pos)}
               onCloseAll={handleCloseAll}
               onCancelAll={handleCancelAll}
             />
          </div>
        </div>

        <div className="w-[340px] flex flex-col border-l border-gray-200 dark:border-dark-border bg-white dark:bg-dark-card z-10 shrink-0">
          <div className="flex-1 overflow-y-auto">
            <TradeForm 
              lang={lang} 
              theme={theme}
              isConnected={isConnected} 
              onConnect={() => setShowWalletModal(true)} 
              onOrder={handleOrder}
              lastPrice={marketData.lastPrice}
              availableBalance={accountInfo.marginBalance} 
            />
          </div>
          <div className="shrink-0 border-t border-gray-200 dark:border-dark-border">
             <AccountInfo lang={lang} info={accountInfo} />
          </div>
        </div>
      </main>

      <NotificationContainer notifications={notifications} removeNotification={removeNotification} />

      <WalletModal isOpen={showWalletModal} onClose={() => setShowWalletModal(false)} lang={lang} onConnect={handleConnect} />

      <AssetModal
        isOpen={assetModal.isOpen}
        onClose={() => setAssetModal(prev => ({ ...prev, isOpen: false }))}
        lang={lang}
        type={assetModal.type}
        maxAmount={assetModal.type === 'deposit' ? accountInfo.walletBalance : accountInfo.marginBalance}
        onConfirm={handleAssetConfirm}
      />

      {showMarginModal && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-[300]">
          <div className="bg-white dark:bg-dark-card p-6 rounded-lg w-80 shadow-2xl border border-gray-200 dark:border-slate-700 animate-in zoom-in duration-200">
             <h3 className="text-lg font-bold mb-4 dark:text-white">Adjust Margin</h3>
             <p className="text-sm text-gray-500 mb-4">{showMarginModal.symbol} - {showMarginModal.marginMode} {showMarginModal.leverage}x</p>
             <div className="flex space-x-2 mb-4">
               <button onClick={() => handleMarginAdjust(100, 'add')} className="flex-1 py-2 bg-trade-up text-white rounded hover:bg-green-600">Add 100</button>
               <button onClick={() => handleMarginAdjust(100, 'remove')} className="flex-1 py-2 bg-trade-down text-white rounded hover:bg-red-600">Remove 100</button>
             </div>
             <button onClick={() => setShowMarginModal(null)} className="w-full py-2 text-gray-500 hover:bg-gray-100 dark:hover:bg-slate-700 rounded">Cancel</button>
          </div>
        </div>
      )}
    </div>
  );
}

import React, { useState, useEffect } from 'react';
import { MOCK_ASKS, MOCK_BIDS, TRANSLATIONS, INITIAL_MARKET_DATA } from '../constants';
import { Language } from '../types';
import { ArrowUp, ArrowDown } from 'lucide-react';

interface OrderBookProps {
  lang: Language;
  lastPrice: number;
}

const Row = ({ price, amount, total, type }: { price: number, amount: string, total: string, type: 'ask' | 'bid' }) => {
  const bgClass = type === 'ask' ? 'bg-trade-down' : 'bg-trade-up';
  const textClass = type === 'ask' ? 'text-trade-down' : 'text-trade-up';
  const width = Math.min(parseFloat(total) * 1, 100); 

  return (
    <div className="grid grid-cols-3 text-xs py-1 hover:bg-slate-100 dark:hover:bg-slate-700 cursor-pointer transition-colors relative group items-center">
      <div 
        className={`absolute top-0 right-0 h-full opacity-10 transition-all duration-300 ${bgClass}`} 
        style={{ width: `${width}%` }} 
      />
      <div className={`text-left pl-2 ${textClass} z-10 font-mono`}>{price.toFixed(2)}</div>
      <div className="text-right text-slate-700 dark:text-slate-300 z-10 font-mono">{amount}</div>
      <div className="text-right pr-2 text-slate-500 dark:text-gray-400 z-10 font-mono">{total}</div>
    </div>
  );
};

export const OrderBook: React.FC<OrderBookProps> = ({ lang, lastPrice: initialLastPrice }) => {
  const t = TRANSLATIONS[lang];
  const [tab, setTab] = useState<'book' | 'trades'>('book');
  const [asks, setAsks] = useState(MOCK_ASKS);
  const [bids, setBids] = useState(MOCK_BIDS);
  const [lastPrice, setLastPrice] = useState(initialLastPrice);

  useEffect(() => {
    const interval = setInterval(() => {
      const newPrice = lastPrice + (Math.random() - 0.5) * 0.5;
      setLastPrice(newPrice);

      setAsks(prev => prev.map(a => ({
         ...a,
         amount: Math.max(0, parseFloat(a.amount) + (Math.random() - 0.5)).toFixed(3),
         total: Math.max(0, parseFloat(a.total) + (Math.random() - 0.5) * 2).toFixed(3)
      })));
      setBids(prev => prev.map(b => ({
         ...b,
         amount: Math.max(0, parseFloat(b.amount) + (Math.random() - 0.5)).toFixed(3),
         total: Math.max(0, parseFloat(b.total) + (Math.random() - 0.5) * 2).toFixed(3)
      })));
    }, 500);

    return () => clearInterval(interval);
  }, [lastPrice]);

  return (
    <div className="flex flex-col h-full bg-white dark:bg-dark-card border-l border-gray-200 dark:border-dark-border overflow-hidden select-none">
      <div className="flex border-b border-gray-200 dark:border-dark-border shrink-0">
        <button 
          onClick={() => setTab('book')}
          className={`flex-1 py-2 text-sm font-medium transition-colors ${tab === 'book' ? 'text-brand-500 border-b-2 border-brand-500' : 'text-gray-500'}`}
        >
          {t.orderBook}
        </button>
        <button 
          onClick={() => setTab('trades')}
          className={`flex-1 py-2 text-sm font-medium transition-colors ${tab === 'trades' ? 'text-brand-500 border-b-2 border-brand-500' : 'text-gray-500'}`}
        >
          {tab === 'trades' ? t.recentTrades : 'Trades'}
        </button>
      </div>

      <div className="grid grid-cols-3 text-[10px] text-gray-500 dark:text-gray-400 px-2 py-2 font-semibold shrink-0 uppercase tracking-tighter">
        <div className="text-left">{t.price}</div>
        <div className="text-right">{t.amount}</div>
        <div className="text-right pr-2">{tab === 'book' ? t.total : 'Time'}</div>
      </div>

      <div className="flex-1 flex flex-col justify-between overflow-hidden">
        {tab === 'book' ? (
          <>
            <div className="flex flex-col justify-end overflow-hidden">
              {asks.slice(0, 8).map((ask, i) => (
                <Row key={`ask-${i}`} {...ask} price={ask.price} type="ask" />
              ))}
            </div>

            <div className="py-2 my-1 border-y border-gray-100 dark:border-slate-800 bg-gray-50 dark:bg-slate-900/40 shrink-0 flex items-center justify-center space-x-4">
               <div className="flex items-center space-x-1">
                 <span className={`text-xl font-bold font-mono ${lastPrice >= initialLastPrice ? 'text-trade-up' : 'text-trade-down'}`}>{lastPrice.toFixed(2)}</span>
                 {lastPrice >= initialLastPrice ? <ArrowUp size={16} className="text-trade-up" /> : <ArrowDown size={16} className="text-trade-down" />}
               </div>
               <div className="text-[11px] text-slate-500 font-mono mt-0.5">{INITIAL_MARKET_DATA.markPrice.toFixed(2)}</div>
            </div>

            <div className="overflow-hidden">
               {bids.slice(0, 8).map((bid, i) => (
                <Row key={`bid-${i}`} {...bid} price={bid.price} type="bid" />
              ))}
            </div>
          </>
        ) : (
          <div className="flex flex-col p-2 space-y-1">
             <span className="text-center text-xs text-gray-500 py-10">Demo trades loading...</span>
          </div>
        )}
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { Language, MarginMode, OrderType, OrderSide, Theme } from '../types';
import { TRANSLATIONS } from '../constants';
import { Edit3, X } from 'lucide-react';

interface TradeFormProps {
  lang: Language;
  theme: Theme;
  isConnected: boolean;
  onConnect: () => void;
  onOrder: (side: OrderSide, type: OrderType, size: number, price: number, leverage: number, marginMode: MarginMode) => void;
  lastPrice: number;
  availableBalance: number;
}

export const CustomSlider: React.FC<{ value: number; onChange: (v: number) => void; theme: Theme }> = ({ value, onChange, theme }) => {
  return (
    <div className="relative w-full h-10 flex items-center group">
       <input
          type="range"
          min="0"
          max="100"
          step="1"
          value={value}
          onChange={(e) => onChange(parseFloat(e.target.value))}
          className="w-full h-1.5 bg-gray-200 dark:bg-slate-800 rounded-lg appearance-none cursor-pointer accent-transparent z-10 relative"
          style={{
            WebkitAppearance: 'none',
            background: `linear-gradient(to right, #DCA85E 0%, #DCA85E ${value}%, ${theme === 'dark' ? '#334155' : '#E2E8F0'} ${value}%, ${theme === 'dark' ? '#334155' : '#E2E8F0'} 100%)`
          }}
        />
        <div 
          className="absolute top-[2px] w-9 h-9 bg-[#DCA85E] border-2 border-white dark:border-slate-900 rounded-full flex items-center justify-center text-[11px] font-bold text-slate-900 shadow-[2px_2px_4px_rgba(0,0,0,0.3)] pointer-events-none transition-all duration-75 transform -translate-x-1/2 z-20"
          style={{ left: `${value}%` }}
        >
          {Math.round(value)}%
        </div>
    </div>
  );
};

export const TradeForm: React.FC<TradeFormProps> = ({ lang, theme, isConnected, onConnect, onOrder, lastPrice, availableBalance }) => {
  const t = TRANSLATIONS[lang];
  const [type, setType] = useState<OrderType>(OrderType.MARKET);
  const [marginMode, setMarginMode] = useState<MarginMode>(MarginMode.CROSS);
  const [leverage, setLeverage] = useState<number>(20);
  const [amount, setAmount] = useState<string>('');
  const [price, setPrice] = useState<string>('');
  const [sliderValue, setSliderValue] = useState(0);
  const [showLeveragePopup, setShowLeveragePopup] = useState(false);

  const effectivePrice = type === OrderType.LIMIT && price ? parseFloat(price) : lastPrice;
  const maxAmount = effectivePrice > 0 ? (availableBalance * leverage) / effectivePrice : 0;

  const handleSliderChange = (val: number) => {
    setSliderValue(val);
    if (maxAmount > 0) {
      setAmount((maxAmount * val / 100).toFixed(4));
    }
  };

  const handleOrderClick = (side: OrderSide) => {
    if (!isConnected) { onConnect(); return; }
    if (!amount || parseFloat(amount) <= 0) return;
    onOrder(side, type, parseFloat(amount), effectivePrice, leverage, marginMode);
    setAmount('');
    setSliderValue(0);
  };

  return (
    <div className="flex flex-col h-full bg-white dark:bg-dark-card border-l border-gray-200 dark:border-dark-border p-4 relative">
      <div className="flex justify-between items-center mb-4">
        <div className="flex bg-gray-100 dark:bg-slate-800 rounded border border-gray-200 dark:border-slate-700 p-0.5">
          <button onClick={() => setMarginMode(MarginMode.CROSS)} className={`px-3 py-1.5 text-xs font-bold rounded transition-all ${marginMode === MarginMode.CROSS ? 'bg-slate-500/30 text-brand-500' : 'text-gray-500'}`}>{t.cross}</button>
          <button onClick={() => setMarginMode(MarginMode.ISOLATED)} className={`px-3 py-1.5 text-xs font-bold rounded transition-all ${marginMode === MarginMode.ISOLATED ? 'bg-slate-500/30 text-brand-500' : 'text-gray-500'}`}>{t.isolated}</button>
        </div>
        <button onClick={() => setShowLeveragePopup(true)} className="flex items-center space-x-1 bg-gray-100 dark:bg-slate-800 hover:bg-gray-200 px-3 py-1.5 rounded text-xs font-bold text-slate-900 dark:text-white border border-gray-200 dark:border-slate-700">
          <span>{leverage}x</span><Edit3 size={12} className="text-gray-500" />
        </button>
      </div>

      <div className="flex bg-gray-100 dark:bg-slate-800 border border-gray-200 dark:border-slate-700 rounded p-0.5 mb-4">
        <button onClick={() => setType(OrderType.MARKET)} className={`flex-1 py-1.5 text-xs font-bold rounded ${type === OrderType.MARKET ? 'bg-slate-500 text-white' : 'text-gray-500'}`}>{t.market}</button>
        <button onClick={() => setType(OrderType.LIMIT)} className={`flex-1 py-1.5 text-xs font-bold rounded ${type === OrderType.LIMIT ? 'bg-slate-500 text-white' : 'text-gray-500'}`}>{t.limit}</button>
      </div>

      <div className="mb-3">
        <div className="text-xs text-gray-500 mb-1">{t.price}</div>
        <input type={type === OrderType.LIMIT ? "number" : "text"} value={type === OrderType.LIMIT ? price : ""} onChange={(e) => setPrice(e.target.value)} disabled={type === OrderType.MARKET} placeholder={type === OrderType.MARKET ? `${t.market} ${t.price}` : lastPrice.toFixed(2)} className="w-full bg-transparent border border-gray-200 dark:border-slate-700 rounded p-2.5 text-sm font-mono outline-none" />
      </div>

      <div className="mb-1">
        <div className="flex justify-between text-xs mb-1"><span className="text-gray-500">{t.amount}</span><span className="text-gray-500">{t.avail}: <span className="font-mono">{availableBalance.toFixed(2)} USDC</span></span></div>
        <div className="relative flex items-center">
          <input type="number" value={amount} onChange={(e) => setAmount(e.target.value)} className="w-full bg-transparent border border-gray-300 dark:border-slate-600 rounded p-2.5 pr-20 text-sm font-bold font-mono outline-none" placeholder="0.00" />
          <div className="absolute right-0 h-full flex items-center pr-2"><span className="bg-gray-200 dark:bg-slate-700 text-xs font-bold px-2 py-1 rounded">XAU</span></div>
        </div>
      </div>

      <div className="mt-4 mb-8">
        <CustomSlider value={sliderValue} onChange={handleSliderChange} theme={theme} />
      </div>

      <div className="grid grid-cols-2 gap-3 mb-4">
        <button onClick={() => handleOrderClick(OrderSide.BUY)} className="py-3 bg-trade-up hover:bg-green-600 text-white font-bold rounded-lg shadow-lg shadow-green-900/20">{t.buyLong}</button>
        <button onClick={() => handleOrderClick(OrderSide.SELL)} className="py-3 bg-trade-down hover:bg-red-600 text-white font-bold rounded-lg shadow-lg shadow-red-900/20">{t.sellShort}</button>
      </div>

      {showLeveragePopup && (
        <>
          <div className="fixed inset-0 bg-black/50 z-[100] backdrop-blur-[1px]" onClick={() => setShowLeveragePopup(false)} />
          <div className="absolute top-16 left-4 right-4 bg-white dark:bg-dark-card border border-gray-200 dark:border-slate-700 rounded-lg shadow-2xl z-[101] p-4 animate-in zoom-in-95 duration-200">
             <div className="flex justify-between items-center mb-4"><span className="font-bold text-sm">Adjust Leverage</span><button onClick={() => setShowLeveragePopup(false)}><X size={16} /></button></div>
             <div className="bg-gray-100 dark:bg-slate-800 rounded p-2 mb-6 text-center"><span className="text-2xl font-bold text-brand-500">{leverage}x</span></div>
             <input type="range" min="1" max="20" step="1" value={leverage} onChange={(e) => setLeverage(parseInt(e.target.value))} className="w-full h-2 bg-gray-200 rounded-lg appearance-none cursor-pointer accent-brand-500 mb-4" />
             <button onClick={() => setShowLeveragePopup(false)} className="w-full py-2 bg-brand-500 text-white font-bold rounded text-sm">Confirm</button>
          </div>
        </>
      )}
    </div>
  );
};

import React, { useState } from 'react';
import { Position, Order, Language, MarginMode, OrderType, Theme } from '../types';
