interface PositionTableProps {
  positions: Position[];
  orders: Order[];
  lang: Language;
  theme: Theme;
  onClosePosition: (id: string, type: OrderType, price?: number, amount?: number) => void;
  onCancelOrder: (id: string) => void;
  onEditMargin: (position: Position) => void;
  onCloseAll: () => void;
  onCancelAll: () => void;
}

export const PositionTable: React.FC<PositionTableProps> = ({ positions, orders, lang, theme, onClosePosition, onCancelOrder, onEditMargin, onCloseAll, onCancelAll }) => {
  const t = TRANSLATIONS[lang];
  const [activeTab, setActiveTab] = useState<'positions' | 'orders' | 'history' | 'trades' | 'assets'>('positions');
  const [closingPos, setClosingPos] = useState<Position | null>(null);

  const CloseModal = ({ pos, onClose }: { pos: Position, onClose: () => void }) => {
