import React, { useState, useRef, useEffect } from 'react';
import { Language, Theme } from '../types';
import { TRANSLATIONS } from '../constants';
import { Moon, Sun, Globe, Wallet, Settings } from 'lucide-react';
import { AccountPopover, SettingsModal } from './Modals';

interface HeaderProps {
  lang: Language;
  setLang: (l: Language) => void;
  theme: Theme;
  setTheme: (t: Theme) => void;
  isConnected: boolean;
  onConnectClick: () => void;
  onDeposit: () => void;
  onWithdraw: () => void;
  onDisconnect: () => void;
}

export const Header: React.FC<HeaderProps> = ({ 
  lang, setLang, theme, setTheme, isConnected, onConnectClick, onDeposit, onWithdraw, onDisconnect 
}) => {
  const t = TRANSLATIONS[lang];
  const [langOpen, setLangOpen] = useState(false);
  const [popoverOpen, setPopoverOpen] = useState(false);
  const [settingsOpen, setSettingsOpen] = useState(false);
  const popoverRef = useRef<HTMLDivElement>(null);

  const toggleTheme = () => {
    const newTheme = theme === 'dark' ? 'light' : 'dark';
    setTheme(newTheme);
    document.documentElement.classList.toggle('dark', newTheme === 'dark');
  };

  useEffect(() => {
    const handleClickOutside = (e: MouseEvent) => {
      if (popoverRef.current && !popoverRef.current.contains(e.target as Node)) setPopoverOpen(false);
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  return (
    <header className="h-14 bg-white dark:bg-dark-card border-b border-gray-200 dark:border-dark-border px-4 flex items-center justify-between sticky top-0 z-50">
      <div className="flex items-center space-x-8">
        <div className="flex items-center space-x-2 cursor-pointer">
          <div className="w-8 h-8 bg-[#DCA85E] rounded flex items-center justify-center font-bold text-white shadow-inner">G</div>
          <span className="text-xl font-bold text-slate-900 dark:text-white hidden md:block">GoldenDex</span>
        </div>
      </div>

      <div className="flex items-center space-x-4">
        {isConnected && (
           <div className="relative" ref={popoverRef}>
              <button 
                onClick={() => setPopoverOpen(!popoverOpen)}
                className="flex items-center space-x-2 px-4 py-1.5 rounded bg-gray-100 dark:bg-slate-800 text-slate-900 dark:text-slate-200 border border-gray-200 dark:border-slate-700 font-mono text-sm font-bold hover:border-brand-500 transition-colors"
              >
                <span>0x4b...5591</span>
              </button>
              {popoverOpen && (
                 <AccountPopover 
                    lang={lang} 
                    onClose={() => setPopoverOpen(false)} 
                    onDisconnect={() => { onDisconnect(); setPopoverOpen(false); }} 
                    onDeposit={onDeposit} 
                    onWithdraw={onWithdraw} 
                 />
              )}
           </div>
        )}

        {!isConnected && (
           <button onClick={onConnectClick} className="bg-brand-500 text-white px-4 py-1.5 rounded font-bold text-sm hover:bg-brand-600 transition-colors">{t.connectWallet}</button>
        )}

        <div className="flex items-center space-x-3 border-l border-gray-200 dark:border-slate-700 pl-4">
          <div className="relative">
            <button onClick={() => setLangOpen(!langOpen)} className="text-gray-500 hover:text-white flex items-center space-x-1 border border-gray-200 dark:border-slate-700 px-2 py-1 rounded text-xs font-bold">
               <img src={lang === 'en' ? 'https://flagcdn.com/w20/us.png' : 'https://flagcdn.com/w20/cn.png'} className="w-4" alt="flag" />
               <span className="hidden sm:block uppercase">{lang === 'zh-CN' ? '简体中文' : 'EN'}</span>
            </button>
            {langOpen && (
              <div className="absolute right-0 mt-2 w-32 bg-white dark:bg-dark-card border border-gray-200 dark:border-slate-700 rounded-lg shadow-xl py-1 z-50">
                <button onClick={() => {setLang('en'); setLangOpen(false)}} className="block w-full text-left px-4 py-2 text-sm hover:bg-slate-800">English</button>
                <button onClick={() => {setLang('zh-CN'); setLangOpen(false)}} className="block w-full text-left px-4 py-2 text-sm hover:bg-slate-800">简体中文</button>
              </div>
            )}
          </div>
          <button onClick={toggleTheme} className="text-gray-500 hover:text-white border border-gray-200 dark:border-slate-700 p-1.5 rounded">{theme === 'dark' ? <Sun size={18} /> : <Moon size={18} />}</button>
          <button onClick={() => setSettingsOpen(true)} className="text-gray-500 hover:text-white border border-gray-200 dark:border-slate-700 p-1.5 rounded"><Settings size={18} /></button>
        </div>
      </div>
      <SettingsModal isOpen={settingsOpen} onClose={() => setSettingsOpen(false)} lang={lang} />
    </header>
  );
};

import React, { useState } from 'react';
import { Header } from './components/Header';
import { MarketStats } from './components/MarketStats';
import { CandleChart } from './components/CandleChart';
import { OrderBook } from './components/OrderBook';
import { TradeForm } from './components/TradeForm';
import { PositionTable } from './components/PositionTable';
import { AccountInfo } from './components/AccountInfo';
import { NotificationContainer } from './components/Notification';
import { WalletModal, AssetModal, MarginManageModal } from './components/Modals';
import { INITIAL_MARKET_DATA, MOCK_POSITIONS, TRANSLATIONS, INITIAL_ACCOUNT_INFO } from './constants';
import { Language, Theme, MarketData, Position, Order, Notification, OrderSide, OrderType, MarginMode, AccountInfo as AccountInfoType } from './types';

export default function App() {
  const [lang, setLang] = useState<Language>('zh-CN');
  const [theme, setTheme] = useState<Theme>('dark');
  const [isConnected, setIsConnected] = useState(false);
  const [marketData, setMarketData] = useState<MarketData>(INITIAL_MARKET_DATA);
  const [positions, setPositions] = useState<Position[]>(MOCK_POSITIONS);
  const [orders, setOrders] = useState<Order[]>([]);
  const [notifications, setNotifications] = useState<Notification[]>([]);
  const [accountInfo, setAccountInfo] = useState<AccountInfoType>(INITIAL_ACCOUNT_INFO);

  const [showWalletModal, setShowWalletModal] = useState(false);
  const [assetModal, setAssetModal] = useState<{ isOpen: boolean, type: 'deposit' | 'withdraw' }>({ isOpen: false, type: 'deposit' });
  const [marginManage, setMarginManage] = useState<{ isOpen: boolean; type: 'add' | 'extract'; pos: Position | null }>({ isOpen: false, type: 'add', pos: null });

  const addNotification = (type: 'success' | 'error' | 'info', message: string) => {
    const id = Date.now().toString();
    setNotifications(prev => [...prev, { id, type, message }]);
  };

  const handleOrder = (side: OrderSide, type: OrderType, size: number, price: number, leverage: number, marginMode: MarginMode) => {
    if (!isConnected) { setShowWalletModal(true); return; }
    if (type === OrderType.MARKET) {
      const newPos: Position = { id: Date.now().toString(), symbol: 'XAUUSDC', side, size, entryPrice: price, markPrice: price, leverage, margin: (size * price) / leverage, marginMode, pnl: 0, pnlPercent: 0, liquidationPrice: side === OrderSide.BUY ? price * 0.8 : price * 1.2 };
      setPositions(prev => [newPos, ...prev]);
      addNotification('success', 'Position Opened');
    }
  };

  const handleClosePosition = (id: string, type: OrderType, price?: number, amountToClose?: number) => {
    setPositions(prev => prev.filter(p => p.id !== id));
    addNotification('success', 'Position Closed');
  };

  const handleAdjustMargin = (amount: number) => {
    if (!marginManage.pos) return;
    setPositions(prev => prev.map(p => {
       if (p.id === marginManage.pos?.id) {
         const adj = marginManage.type === 'add' ? amount : -amount;
         return { ...p, margin: p.margin + adj };
       }
       return p;
    }));
    addNotification('success', 'Margin Adjusted');
  };

  return (
    <div className={`flex flex-col h-screen ${theme} bg-gray-50 dark:bg-dark-bg text-slate-900 dark:text-slate-200 font-sans overflow-hidden transition-colors`}>
      <Header 
        lang={lang} setLang={setLang} theme={theme} setTheme={setTheme}
        isConnected={isConnected} 
        onConnectClick={() => setShowWalletModal(true)} 
        onDeposit={() => setAssetModal({ isOpen: true, type: 'deposit' })}
        onWithdraw={() => setAssetModal({ isOpen: true, type: 'withdraw' })}
        onDisconnect={() => { setIsConnected(false); setPositions([]); }}
      />
      <MarketStats data={marketData} lang={lang} />
      <main className="flex-1 flex overflow-hidden">
        <div className="flex-1 flex flex-col min-w-0">
          <div className="flex-[3] flex border-b border-gray-200 dark:border-dark-border">
            <div className="flex-1 relative border-r border-gray-200 dark:border-dark-border"><CandleChart lang={lang} /></div>
            <div className="w-[280px] hidden lg:block bg-white dark:bg-dark-card shrink-0"><OrderBook lang={lang} lastPrice={marketData.lastPrice} /></div>
          </div>
          <div className="flex-[2] min-h-[300px] overflow-hidden">
             <PositionTable 
               positions={positions} orders={orders} lang={lang} theme={theme}
               onClosePosition={handleClosePosition}
               onCancelOrder={(id) => setOrders(o => o.filter(x => x.id !== id))}
               onEditMargin={(pos) => setMarginManage({ isOpen: true, type: 'add', pos })}
               onCloseAll={() => setPositions([])}
               onCancelAll={() => setOrders([])}
             />
          </div>
        </div>
        <div className="w-[340px] flex flex-col border-l border-gray-200 dark:border-dark-border bg-white dark:bg-dark-card z-10 shrink-0">
          <div className="flex-1 overflow-y-auto">
            <TradeForm lang={lang} theme={theme} isConnected={isConnected} onConnect={() => setShowWalletModal(true)} onOrder={handleOrder} lastPrice={marketData.lastPrice} availableBalance={accountInfo.marginBalance} />
          </div>
          <div className="shrink-0 border-t border-gray-200 dark:border-dark-border"><AccountInfo lang={lang} info={accountInfo} /></div>
        </div>
      </main>

      <NotificationContainer notifications={notifications} removeNotification={(id) => setNotifications(n => n.filter(x => x.id !== id))} />
      <WalletModal isOpen={showWalletModal} onClose={() => setShowWalletModal(false)} lang={lang} onConnect={() => setIsConnected(true)} />
      <AssetModal isOpen={assetModal.isOpen} onClose={() => setAssetModal(prev => ({ ...prev, isOpen: false }))} lang={lang} type={assetModal.type} maxAmount={assetModal.type === 'deposit' ? accountInfo.walletBalance : accountInfo.marginBalance} onConfirm={() => addNotification('success', 'Asset Transferred')} />

      {marginManage.isOpen && marginManage.pos && (
         <MarginManageModal 
            isOpen={true} onClose={() => setMarginManage(m => ({...m, isOpen: false}))}
            lang={lang} theme={theme} type={marginManage.type} pos={marginManage.pos}
            available={marginManage.type === 'add' ? accountInfo.marginBalance : marginManage.pos.margin - 100}
            onConfirm={handleAdjustMargin}
         />
      )}
    </div>
  );
}

