export const MarginManageModal: React.FC<{ isOpen: boolean; onClose: () => void; lang: Language; type: 'add' | 'extract'; pos: Position; theme: Theme; available: number; onConfirm: (v: number) => void; }> = ({ isOpen, onClose, lang, type, pos, theme, available, onConfirm }) => {
  const t = TRANSLATIONS[lang];
  const [amount, setAmount] = useState('');
  const [sliderVal, setSliderVal] = useState(0);

  const numAmount = parseFloat(amount) || 0;
  const newMargin = type === 'add' ? pos.margin + numAmount : pos.margin - numAmount;
  const isLong = pos.side === 'BUY';
  const newLiq = isLong ? pos.liquidationPrice * (pos.margin / newMargin) : pos.liquidationPrice * (newMargin / pos.margin);

  const handleConfirm = () => { if (numAmount > 0) { onConfirm(numAmount); onClose(); } };
  const handleSlider = (v: number) => { setSliderVal(v); setAmount((available * v / 100).toFixed(2)); };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-[300] flex items-center justify-center bg-black/60 backdrop-blur-sm p-4">
      <div className="w-full max-w-[420px] bg-white dark:bg-[#1a1c22] border border-gray-200 dark:border-slate-800 rounded-lg shadow-2xl overflow-hidden animate-in fade-in zoom-in duration-200">
        <div className="flex items-center justify-between px-6 py-4 border-b border-gray-100 dark:border-slate-800">
           <h3 className="text-lg font-bold">{type === 'add' ? t.addMargin : t.removeMargin}</h3>
           <button onClick={onClose} className="text-gray-400 hover:text-white transition"><X size={20} /></button>
        </div>
        <div className="p-6 space-y-5">
           <div className="flex justify-between items-center text-sm border-b border-gray-100 dark:border-slate-800 pb-3">
              <span className="text-gray-500">{t.contract}</span>
              <span className="font-bold text-[#10B981] font-mono">{pos.symbol} / {isLong ? t.long : t.short}</span>
           </div>

           <div className="space-y-2">
              <div className="flex justify-between text-xs font-bold text-gray-500">
                 <span>{t.amount}</span>
                 <span>{type === 'add' ? t.avail : t.availExtract}: {available.toLocaleString()} USDC</span>
              </div>
              <div className="relative">
                 <input type="number" value={amount} onChange={e => setAmount(e.target.value)} placeholder={t.amount} className="w-full bg-transparent border border-gray-200 dark:border-slate-700 rounded p-2.5 pr-14 text-sm font-mono focus:border-brand-500 outline-none" />
                 <span className="absolute right-3 top-2.5 text-xs text-gray-500 font-bold">USDC</span>
              </div>
              <div className="flex justify-between space-x-2 pt-1">
                 {[25, 50, 75, 100].map(v => (
                   <button key={v} onClick={() => handleSlider(v)} className="flex-1 py-1.5 border border-gray-200 dark:border-slate-700 text-xs font-bold text-gray-500 rounded hover:border-brand-500 hover:text-brand-500 transition-all">{v}%</button>
                 ))}
              </div>
              <div className="pt-2"><CustomSlider value={sliderVal} onChange={handleSlider} theme={theme} /></div>
           </div>

           <div className="bg-gray-50 dark:bg-slate-900/40 p-4 rounded-lg space-y-4">
              <div className="flex justify-between items-center text-xs">
                 <span className="text-gray-500">{t.margin}</span>
                 <div className="flex items-center space-x-3 font-mono font-bold text-slate-300">
                    <span>{pos.margin.toFixed(2)}</span><ArrowRightIcon size={12} className="text-[#10B981]" /><span>{newMargin.toFixed(2)}</span>
                 </div>
              </div>
              <div className="flex justify-between items-center text-xs">
                 <span className="text-gray-500">{t.liqPrice}</span>
                 <div className="flex items-center space-x-3 font-mono font-bold text-slate-300">
                    <span>{pos.liquidationPrice.toFixed(2)}</span><ArrowRightIcon size={12} className="text-[#10B981]" /><span>{newLiq.toFixed(2)}</span>
                 </div>
              </div>
              <div className="flex justify-between items-center text-xs">
                 <span className="text-gray-500">{t.leverage}</span>
                 <div className="flex items-center space-x-3 font-mono font-bold text-slate-300">
                    <span>{pos.leverage}x</span><ArrowRightIcon size={12} className="text-[#10B981]" /><span>{(pos.margin * pos.leverage / newMargin).toFixed(1)}x</span>
                 </div>
              </div>
           </div>

           <div className="grid grid-cols-2 gap-4 pt-4">
              <button onClick={onClose} className="py-3 bg-gray-400 hover:bg-gray-500 text-white font-bold rounded-lg transition-all">{t.cancel}</button>
              <button onClick={handleConfirm} className="py-3 bg-[#8B5E14] hover:bg-[#7a5212] text-white font-bold rounded-lg transition-all shadow-xl">{t.confirm}</button>
           </div>
