import React, { useState } from 'react';
import { Position, Order, Language, MarginMode, OrderType, Theme } from '../types';
import { TRANSLATIONS, INITIAL_MARKET_DATA } from '../constants';
import { Edit3, Trash2, X, ChevronDown, Repeat } from 'lucide-react';
import { CustomSlider } from './TradeForm';

interface PositionTableProps {
  positions: Position[];
  orders: Order[];
  lang: Language;
  theme: Theme;
  onClosePosition: (id: string, type: OrderType, price?: number, amount?: number) => void;
  onCancelOrder: (id: string) => void;
  onEditMargin: (position: Position) => void;
  onCloseAll: () => void;
  onCancelAll: () => void;
}

export const PositionTable: React.FC<PositionTableProps> = ({ positions, orders, lang, theme, onClosePosition, onCancelOrder, onEditMargin, onCloseAll, onCancelAll }) => {
  const t = TRANSLATIONS[lang];
  const [activeTab, setActiveTab] = useState<'positions' | 'orders' | 'history' | 'trades' | 'assets'>('positions');
  const [closingPos, setClosingPos] = useState<Position | null>(null);

  const CloseModal = ({ pos, onClose }: { pos: Position, onClose: () => void }) => {
    const [closeType, setCloseType] = useState<OrderType>(OrderType.MARKET);
    const [closePrice, setClosePrice] = useState<string>(INITIAL_MARKET_DATA.lastPrice.toFixed(2));
    const [closeAmount, setCloseAmount] = useState<string>(pos.size.toString());
    const [sliderVal, setSliderVal] = useState(100);

    const handleConfirm = () => { onClosePosition(pos.id, closeType, parseFloat(closePrice), parseFloat(closeAmount)); onClose(); };
    const handleSlider = (val: number) => { setSliderVal(val); setCloseAmount((pos.size * val / 100).toFixed(4)); };

    const estPnl = (parseFloat(closeAmount) || 0) * (closeType === OrderType.MARKET ? pos.markPrice : parseFloat(closePrice) || pos.markPrice) - (parseFloat(closeAmount) || 0) * pos.entryPrice;

    return (
      <div className="fixed inset-0 z-[200] flex items-center justify-center bg-black/70 backdrop-blur-sm p-4">
        <div className="w-full max-w-[400px] bg-[#f9f9f9] dark:bg-[#1a1c22] border border-gray-200 dark:border-slate-800 rounded-lg shadow-2xl overflow-hidden animate-in fade-in zoom-in duration-200">
          <div className="flex items-center justify-between px-6 py-4 border-b border-gray-100 dark:border-slate-800">
            <h3 className="text-lg font-bold">{t.closePos}</h3>
            <button onClick={onClose} className="text-gray-400 hover:text-white transition"><X size={20} /></button>
          </div>
          <div className="p-6 space-y-4">
            <div className="flex justify-between text-sm"><span className="text-gray-500">{t.tradingPair}</span><span className="font-bold text-teal-600 font-mono">{pos.symbol} / {pos.side === 'BUY' ? t.long : t.short} / {pos.leverage}x</span></div>
            <div className="grid grid-cols-2 gap-4">
              <div className="space-y-1.5"><label className="text-xs text-gray-500">{t.closePrice}</label><input type="number" disabled={closeType === OrderType.MARKET} value={closeType === OrderType.MARKET ? "" : closePrice} onChange={e => setClosePrice(e.target.value)} placeholder={closeType === OrderType.MARKET ? t.market : ""} className="w-full bg-gray-100 dark:bg-slate-800/50 border border-gray-200 dark:border-slate-700 rounded p-2 text-sm font-mono outline-none" /></div>
              <div className="space-y-1.5"><label className="text-xs text-gray-500">Type</label><div onClick={() => setCloseType(prev => prev === OrderType.MARKET ? OrderType.LIMIT : OrderType.MARKET)} className="flex items-center justify-between bg-gray-100 dark:bg-slate-800 border border-gray-200 dark:border-slate-700 rounded p-2 text-sm cursor-pointer"><span className="font-mono">{closeType === OrderType.MARKET ? t.market : t.limit}</span><Repeat size={14} className="text-gray-500" /></div></div>
            </div>
            <div className="space-y-1.5"><label className="text-xs text-gray-500">{t.closeAmount}</label><div className="relative"><input type="number" value={closeAmount} onChange={e => setCloseAmount(e.target.value)} className="w-full bg-gray-100 dark:bg-slate-800 border border-gray-200 dark:border-slate-700 rounded p-2 pr-12 text-sm font-mono outline-none" /><div className="absolute right-3 top-2.5 text-xs text-gray-500">XAU</div></div></div>
