  const textClass = type === 'ask' ? 'text-trade-down' : 'text-trade-up';
  const width = Math.min(parseFloat(total) * 1, 100); 

  return (
    <div className="grid grid-cols-3 text-xs py-1 hover:bg-slate-100 dark:hover:bg-slate-700 cursor-pointer transition-colors relative group min-h-[1.5rem] items-center">
      <div 
        className={`absolute top-0 right-0 h-full opacity-10 transition-all duration-300 ${bgClass}`} 
        style={{ width: `${width}%` }} 
      />
