import React, { useState } from 'react';
import { Position, Order, Language, MarginMode, OrderType, Theme } from '../types';
import { TRANSLATIONS, INITIAL_MARKET_DATA } from '../constants';
import { Edit3, Trash2, X, ChevronDown, Repeat } from 'lucide-react';
import { CustomSlider } from './TradeForm';

interface PositionTableProps {
  positions: Position[];
  orders: Order[];
  lang: Language;
  theme: Theme;
  onClosePosition: (id: string, type: OrderType, price?: number, amount?: number) => void;
  onCancelOrder: (id: string) => void;
  onEditMargin: (position: Position) => void;
  onCloseAll: () => void;
  onCancelAll: () => void;
}

export const PositionTable: React.FC<PositionTableProps> = ({ positions, orders, lang, theme, onClosePosition, onCancelOrder, onEditMargin, onCloseAll, onCancelAll }) => {
  const t = TRANSLATIONS[lang];
  const [activeTab, setActiveTab] = useState<'positions' | 'orders' | 'history' | 'trades' | 'assets'>('positions');
  const [closingPos, setClosingPos] = useState<Position | null>(null);

  const CloseModal = ({ pos, onClose }: { pos: Position, onClose: () => void }) => {
    const [closeType, setCloseType] = useState<OrderType>(OrderType.MARKET);
    const [closePrice, setClosePrice] = useState<string>(INITIAL_MARKET_DATA.lastPrice.toFixed(2));
    const [closeAmount, setCloseAmount] = useState<string>(pos.size.toString());
    const [sliderVal, setSliderVal] = useState(100);

    const handleSlider = (val: number) => {
      setSliderVal(val);
      setCloseAmount((pos.size * val / 100).toFixed(4));
    };

    const isLong = pos.side === 'BUY';
    const estPnl = (parseFloat(closeAmount) || 0) * (closeType === OrderType.MARKET ? pos.markPrice : parseFloat(closePrice) || pos.markPrice) - (parseFloat(closeAmount) || 0) * pos.entryPrice;

    return (
      <div className="fixed inset-0 z-[200] flex items-center justify-center bg-black/70 backdrop-blur-sm p-4">
        <div className="w-full max-w-[400px] bg-white dark:bg-[#1a1c22] border border-gray-200 dark:border-slate-800 rounded-lg shadow-2xl overflow-hidden animate-in fade-in zoom-in duration-200">
          <div className="flex items-center justify-between px-6 py-4 border-b border-gray-100 dark:border-slate-800">
            <h3 className="text-lg font-bold">{t.closePos}</h3>
            <button onClick={onClose} className="text-gray-400 hover:text-white transition"><X size={20} /></button>
          </div>
          <div className="p-6 space-y-4">
            <div className="flex justify-between text-sm"><span className="text-gray-500">{t.tradingPair}</span><span className="font-bold text-teal-600 font-mono">{pos.symbol} / {isLong ? t.long : t.short}</span></div>
            <div className="grid grid-cols-2 gap-4">
              <div className="space-y-1.5"><label className="text-xs text-gray-500">{t.closePrice}</label><input type="number" disabled={closeType === OrderType.MARKET} value={closeType === OrderType.MARKET ? "" : closePrice} onChange={e => setClosePrice(e.target.value)} placeholder={closeType === OrderType.MARKET ? t.market : ""} className="w-full bg-gray-100 dark:bg-slate-800 border border-gray-200 dark:border-slate-700 rounded p-2 text-sm font-mono outline-none" /></div>
              <div className="space-y-1.5"><label className="text-xs text-gray-500">Mode</label><div onClick={() => setCloseType(prev => prev === OrderType.MARKET ? OrderType.LIMIT : OrderType.MARKET)} className="flex items-center justify-between bg-gray-100 dark:bg-slate-800 border border-gray-200 dark:border-slate-700 rounded p-2 text-sm cursor-pointer"><span className="text-slate-900 dark:text-slate-300">{closeType === OrderType.MARKET ? t.market : t.limit}</span><Repeat size={14} className="text-gray-500" /></div></div>
            </div>
            <div className="space-y-1.5"><label className="text-xs text-gray-500">{t.closeAmount}</label><div className="relative"><input type="number" value={closeAmount} onChange={e => setCloseAmount(e.target.value)} className="w-full bg-gray-100 dark:bg-slate-800 border border-gray-200 dark:border-slate-700 rounded p-2 pr-12 text-sm font-mono outline-none" /><div className="absolute right-3 top-2.5 text-xs text-gray-500">XAU</div></div></div>
            <div className="pt-4"><CustomSlider value={sliderVal} onChange={handleSlider} theme={theme} /></div>
            <div className="flex justify-between text-xs pt-2"><span className="text-gray-500">{t.estPnl}</span><span className={`font-mono font-bold ${estPnl >= 0 ? 'text-teal-600' : 'text-trade-down'}`}>{estPnl.toFixed(2)} USDC</span></div>
            <div className="grid grid-cols-2 gap-4 pt-4">
              <button onClick={onClose} className="py-2.5 border border-[#dca85e] text-[#dca85e] rounded font-bold">{t.cancel}</button>
              <button onClick={() => { onClosePosition(pos.id, closeType, parseFloat(closePrice), parseFloat(closeAmount)); onClose(); }} className="py-2.5 bg-[#dca85e] text-slate-900 rounded font-bold">{t.confirm}</button>
            </div>
          </div>
        </div>
      </div>
    );
  };

  return (
    <div className="flex flex-col h-full bg-white dark:bg-dark-card border-t border-gray-200 dark:border-dark-border overflow-hidden">
      <div className="flex items-center px-4 border-b border-gray-200 dark:border-dark-border shrink-0">
        {['positions', 'orders', 'history', 'trades', 'assets'].map(tabId => (
          <button key={tabId} onClick={() => setActiveTab(tabId as any)} className={`py-3 px-3 text-sm font-medium border-b-2 transition-all whitespace-nowrap ${activeTab === tabId ? 'border-brand-500 text-brand-500' : 'border-transparent text-gray-500 hover:text-white'}`}>{t[tabId as keyof typeof t] || tabId}</button>
        ))}
      </div>

      <div className="flex-1 overflow-auto">
        {activeTab === 'positions' ? (
          <table className="w-full text-left text-xs border-collapse min-w-[900px]">
            <thead className="sticky top-0 bg-white dark:bg-dark-card z-10 shadow-sm border-b border-gray-200 dark:border-slate-800">
              <tr className="text-gray-500 uppercase">
                <th className="py-2 px-4 font-semibold">{t.symbol}</th>
                <th className="py-2 px-4 font-semibold">{t.nominalValue}</th>
                <th className="py-2 px-4 font-semibold">{t.entryPrice}</th>
                <th className="py-2 px-4 font-semibold">{t.markPrice}</th>
                <th className="py-2 px-4 font-semibold">{t.liqPrice}</th>
                <th className="py-2 px-4 font-semibold">{t.margin}</th>
                <th className="py-2 px-4 font-semibold text-right">{t.unrealizedPnl}</th>
                <th className="py-2 px-4 font-semibold text-right">{t.action}</th>
              </tr>
            </thead>
            <tbody>
              {positions.map(pos => (
                <tr key={pos.id} className="border-b border-gray-100 dark:border-slate-800/30 hover:bg-gray-50 dark:hover:bg-slate-800/20">
                  <td className="py-2 px-4">
                    <div className="flex flex-col">
                      <span className="font-bold text-slate-900 dark:text-white font-mono text-sm">{pos.symbol}</span>
                      <div className="flex items-center space-x-2"><span className={`font-bold ${pos.side === 'BUY' ? 'text-trade-up' : 'text-trade-down'}`}>{pos.side === 'BUY' ? t.long : t.short}</span><span className="text-[10px] text-gray-500 font-bold bg-gray-100 dark:bg-slate-800 px-1 rounded">{pos.leverage}x</span></div>
                    </div>
                  </td>
                  <td className="py-2 px-4 font-mono">{(pos.size * pos.markPrice).toFixed(2)} USDC</td>
                  <td className="py-2 px-4 font-mono">{pos.entryPrice.toFixed(2)}</td>
                  <td className="py-2 px-4 font-mono text-slate-400">{pos.markPrice.toFixed(2)}</td>
                  <td className="py-2 px-4 text-orange-500 font-mono">{pos.liquidationPrice.toFixed(2)}</td>
                  <td className="py-2 px-4 font-mono">
                    <div className="flex flex-col leading-none">
                      <div className="flex items-center space-x-1"><span>{pos.margin.toFixed(2)}</span>{pos.marginMode === MarginMode.ISOLATED && <button onClick={() => onEditMargin(pos)} className="text-gray-400"><Edit3 size={10} /></button>}</div>
                      <span className="text-[9px] text-gray-500 uppercase mt-1">{pos.marginMode === MarginMode.CROSS ? t.cross : t.isolated}</span>
                    </div>
                  </td>
                  <td className={`py-2 px-4 text-right font-mono ${pos.pnl >= 0 ? 'text-trade-up' : 'text-trade-down'}`}><div>{pos.pnl >= 0 ? '+' : ''}{pos.pnl.toFixed(2)}</div><div className="text-[10px] opacity-70">{pos.pnlPercent.toFixed(2)}%</div></td>
                  <td className="py-2 px-4 text-right"><button onClick={() => setClosingPos(pos)} className="px-3 py-1 bg-slate-100 dark:bg-slate-800 hover:bg-brand-500 hover:text-white rounded font-bold transition-all shadow-sm">{t.market} / {t.limit}</button></td>
                </tr>
              ))}
            </tbody>
          </table>
        ) : <div className="p-10 text-center text-gray-500">History Demo Data</div>}
      </div>
      {closingPos && <CloseModal pos={closingPos} onClose={() => setClosingPos(null)} />}
    </div>
  );
};

