                    <div className="flex flex-col">
                      <span className="font-bold text-slate-900 dark:text-white font-mono text-sm">{pos.symbol}</span>
                      <div className="flex items-center space-x-2"><span className={`font-bold ${pos.side === 'BUY' ? 'text-trade-up' : 'text-trade-down'}`}>{pos.side === 'BUY' ? t.long : t.short}</span><span className="text-[10px] text-gray-500 font-bold bg-gray-100 dark:bg-slate-800 px-1 rounded">{pos.leverage}x</span></div>
                    </div>
                  </td>
                  <td className="py-1 px-4 font-mono dark:text-white">{(pos.size * pos.markPrice).toFixed(2)} USDC</td>
                  <td className="py-1 px-4 font-mono dark:text-white">{pos.entryPrice.toFixed(2)}</td>
                  <td className="py-1 px-4 font-mono text-slate-400">{pos.markPrice.toFixed(2)}</td>
                  <td className="py-1 px-4 text-orange-500 font-mono">{pos.liquidationPrice.toFixed(2)}</td>
                  <td className="py-1 px-4 font-mono dark:text-white">
                    <div className="flex flex-col leading-none">
                      <div className="flex items-center space-x-1"><span>{pos.margin.toFixed(2)}</span>{pos.marginMode === MarginMode.ISOLATED && <button onClick={() => onEditMargin(pos)} className="text-gray-400"><Edit3 size={10} /></button>}</div>
                      <span className="text-[9px] text-gray-500 uppercase mt-0.5">{pos.marginMode === MarginMode.CROSS ? t.cross : t.isolated}</span>
                    </div>
                  </td>
                  <td className={`py-1 px-4 text-right font-mono ${pos.pnl >= 0 ? 'text-trade-up' : 'text-trade-down'}`}><div>{pos.pnl >= 0 ? '+' : ''}{pos.pnl.toFixed(2)}</div><div className="text-[10px] opacity-70">{pos.pnlPercent.toFixed(2)}%</div></td>
                  <td className="py-1 px-4 text-right"><button onClick={() => setClosingPos(pos)} className="px-3 py-1 bg-slate-100 dark:bg-slate-800 hover:bg-brand-500 dark:text-white rounded font-bold transition-all shadow-sm">{t.market} / {t.limit}</button></td>
                </tr>
              ))}
            </tbody>
          </table>
        ) : <div className="p-10 text-center text-gray-500">{t[activeTab as keyof typeof t] || activeTab} Demo Data</div>}
      </div>
      {closingPos && <CloseModal pos={closingPos} onClose={() => setClosingPos(null)} />}
    </div>
  );
};

