                  <td className="py-2 px-4"><span className={`px-2 py-0.5 rounded text-[10px] font-bold ${a.status === 'completed' ? 'bg-teal-500/10 text-teal-500' : 'bg-slate-100 dark:bg-slate-800 text-gray-500'}`}>{t[a.status as keyof typeof t] || a.status}</span></td>
                  <td className="py-2 px-4 text-gray-500">{a.time}</td>
