export const MarginManageModal: React.FC<{ isOpen: boolean; onClose: () => void; lang: Language; type: 'add' | 'extract'; pos: Position; theme: Theme; available: number; onConfirm: (v: number) => void; }> = ({ isOpen, onClose, lang, type, pos, theme, available, onConfirm }) => {
  const t = TRANSLATIONS[lang];
  const [amount, setAmount] = useState('');
  const [sliderVal, setSliderVal] = useState(0);

  const numAmount = parseFloat(amount) || 0;
  const isAdd = type === 'add';
  const newMargin = isAdd ? pos.margin + numAmount : Math.max(0, pos.margin - numAmount);

  // Dynamic comparison calculations
  const notional = pos.size * pos.markPrice;
  const oldLeverage = notional / pos.margin;
  const newLeverage = newMargin > 0 ? notional / newMargin : oldLeverage;

  const oldLiq = pos.liquidationPrice;
  const liqDiff = (oldLiq * (numAmount / pos.margin)) * (isAdd ? -1 : 1);
  const newLiq = oldLiq + liqDiff;

  const oldMarginRate = (pos.margin / notional) * 100;
  const newMarginRate = (newMargin / notional) * 100;

  const handleSlider = (v: number) => { setSliderVal(v); setAmount((available * v / 100).toFixed(2)); };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-[300] flex items-center justify-center bg-black/60 backdrop-blur-sm p-4">
      <div className="w-full max-w-[420px] bg-white dark:bg-[#1a1c22] border border-gray-200 dark:border-slate-800 rounded-lg shadow-2xl overflow-hidden animate-in fade-in zoom-in duration-200">
        <div className="flex items-center justify-between px-6 py-4 border-b border-gray-100 dark:border-slate-800">
           <h3 className="text-lg font-bold dark:text-white">{isAdd ? t.addMargin : t.removeMargin}</h3>
           <button onClick={onClose} className="text-gray-400 hover:text-white transition"><X size={20} /></button>
        </div>
        <div className="p-6 space-y-5">
           <div className="flex flex-col border-b border-gray-100 dark:border-slate-800 pb-3">
              <div className="flex justify-between items-center text-sm mb-1">
                <span className="text-gray-500">{t.contract}</span>
                <span className="font-bold text-[#10B981] font-mono">{pos.symbol} / {pos.side === 'BUY' ? t.long : t.short}</span>
              </div>
              <div className="flex justify-between text-[11px] text-gray-500">
                <span>{t.entryPrice}: <span className="font-mono">{pos.entryPrice.toFixed(2)}</span></span>
                <span>{t.markPrice}: <span className="font-mono">{pos.markPrice.toFixed(2)}</span></span>
              </div>
           </div>

           <div className="space-y-2">
              <div className="flex justify-between text-xs font-bold text-gray-500">
                 <span>{t.amount}</span>
                 <span>{isAdd ? t.avail : t.availExtract}: {available.toLocaleString()} USDC</span>
              </div>
              <div className="relative">
                 <input type="number" value={amount} onChange={e => setAmount(e.target.value)} placeholder={t.amount} className="w-full bg-transparent border border-gray-200 dark:border-slate-700 rounded p-2.5 pr-14 text-sm font-mono focus:border-brand-500 outline-none dark:text-white" />
                 <span className="absolute right-3 top-2.5 text-xs text-gray-500 font-bold">USDC</span>
              </div>
              <div className="pt-2"><CustomSlider value={sliderVal} onChange={handleSlider} theme={theme} /></div>
           </div>

           <div className="space-y-4 pt-2 border-t border-gray-100 dark:border-slate-800">
              <div className="flex justify-between items-center text-xs">
                 <span className="text-gray-500">{t.margin}</span>
                 <div className="flex items-center space-x-3 font-mono font-bold dark:text-white">
                    <span>{pos.margin.toFixed(2)}</span><ArrowRightIcon size={12} className="text-[#10B981]" /><span>{newMargin.toFixed(2)}</span>
                 </div>
              </div>
              <div className="flex justify-between items-center text-xs">
                 <span className="text-gray-500">{t.liqPrice}</span>
                 <div className="flex items-center space-x-3 font-mono font-bold dark:text-white">
                    <span>{pos.liquidationPrice.toFixed(2)}</span><ArrowRightIcon size={12} className="text-[#10B981]" /><span>{newLiq.toFixed(2)}</span>
                 </div>
              </div>
              <div className="flex justify-between items-center text-xs">
                 <span className="text-gray-500">{t.leverage}</span>
                 <div className="flex items-center space-x-3 font-mono font-bold dark:text-white">
                    <span>{oldLeverage.toFixed(2)}x</span><ArrowRightIcon size={12} className="text-[#10B981]" /><span>{newLeverage.toFixed(2)}x</span>
                 </div>
              </div>
              <div className="flex justify-between items-center text-xs">
                 <span className="text-gray-500">{t.marginRate}</span>
                 <div className="flex items-center space-x-3 font-mono font-bold dark:text-white">
                    <span>{oldMarginRate.toFixed(2)}%</span><ArrowRightIcon size={12} className="text-[#10B981]" /><span>{newMarginRate.toFixed(2)}%</span>
                 </div>
              </div>
           </div>

           <div className="grid grid-cols-2 gap-4 pt-4">
              <button onClick={onClose} className="py-3 bg-gray-400 hover:bg-gray-500 text-white font-bold rounded-lg transition">{t.cancel}</button>
              <button 
                onClick={() => onConfirm(numAmount)} 
                disabled={numAmount <= 0 || numAmount > available}
                className="py-3 bg-[#8B5E14] hover:bg-[#7a5212] text-white font-bold rounded-lg shadow-xl shadow-[#8B5E14]/20 transition disabled:opacity-50 disabled:cursor-not-allowed"
              >
                {t.confirm}
              </button>
           </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { MOCK_ASKS, MOCK_BIDS, TRANSLATIONS, INITIAL_MARKET_DATA } from '../constants';
import { Language } from '../types';
import { ArrowUp, ArrowDown } from 'lucide-react';

interface OrderBookProps {
  lang: Language;
  lastPrice: number;
}

const Row = ({ price, amount, total, type }: { price: number, amount: string, total: string, type: 'ask' | 'bid' }) => {
  const bgClass = type === 'ask' ? 'bg-trade-down' : 'bg-trade-up';
  const textClass = type === 'ask' ? 'text-trade-down' : 'text-trade-up';
  const width = Math.min(parseFloat(total) * 1, 100); 

  return (
    <div className="grid grid-cols-3 text-xs py-1 hover:bg-slate-100 dark:hover:bg-slate-700 cursor-pointer transition-colors relative group items-center">
      <div 
        className={`absolute top-0 right-0 h-full opacity-10 transition-all duration-300 ${bgClass}`} 
        style={{ width: `${width}%` }} 
      />
      <div className={`text-left pl-2 ${textClass} z-10 font-mono`}>{price.toFixed(2)}</div>
      <div className="text-right text-slate-700 dark:text-slate-300 z-10 font-mono">{amount}</div>
      <div className="text-right pr-2 text-slate-500 dark:text-gray-400 z-10 font-mono">{total}</div>
    </div>
  );
};

export const OrderBook: React.FC<OrderBookProps> = ({ lang, lastPrice: initialLastPrice }) => {
  const t = TRANSLATIONS[lang];
  const [tab, setTab] = useState<'book' | 'trades'>('book');
  const [asks, setAsks] = useState(MOCK_ASKS);
  const [bids, setBids] = useState(MOCK_BIDS);
  const [lastPrice, setLastPrice] = useState(initialLastPrice);
  const [trades, setTrades] = useState<any[]>([]);

  // Simulation effect for Order Book and Trades
  useEffect(() => {
    // Initial trades
    const initialTrades = Array.from({ length: 15 }, (_, i) => ({
      id: `initial-${i}`,
      price: initialLastPrice + (Math.random() - 0.5) * 5,
      amount: (Math.random() * 2).toFixed(3),
      time: new Date(Date.now() - i * 5000).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit', hour12: false }),
      side: Math.random() > 0.5 ? 'BUY' : 'SELL'
    }));
    setTrades(initialTrades);

    const interval = setInterval(() => {
      // Update Price
      const priceChange = (Math.random() - 0.5) * 0.5;
      const newPrice = lastPrice + priceChange;
      setLastPrice(newPrice);

      // Update Order Book
      setAsks(prev => prev.map(a => ({
         ...a,
         amount: Math.max(0.1, parseFloat(a.amount) + (Math.random() - 0.5)).toFixed(3),
         total: Math.max(1, parseFloat(a.total) + (Math.random() - 0.5) * 2).toFixed(3)
      })));
      setBids(prev => prev.map(b => ({
         ...b,
         amount: Math.max(0.1, parseFloat(b.amount) + (Math.random() - 0.5)).toFixed(3),
         total: Math.max(1, parseFloat(b.total) + (Math.random() - 0.5) * 2).toFixed(3)
      })));

      // Occasional new trade
      if (Math.random() > 0.4) {
        const side = Math.random() > 0.5 ? 'BUY' : 'SELL';
        const newTrade = {
          id: Date.now().toString(),
          price: newPrice,
          amount: (Math.random() * 1.2).toFixed(3),
          time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit', hour12: false }),
          side
        };
        setTrades(prev => [newTrade, ...prev].slice(0, 20));
      }
    }, 1000);

    return () => clearInterval(interval);
  }, [lastPrice, initialLastPrice]);

  return (
    <div className="flex flex-col h-full bg-white dark:bg-dark-card border-l border-gray-200 dark:border-dark-border overflow-hidden select-none">
      <div className="flex border-b border-gray-200 dark:border-dark-border shrink-0">
        <button 
          onClick={() => setTab('book')}
          className={`flex-1 py-2 text-sm font-medium transition-colors ${tab === 'book' ? 'text-brand-500 border-b-2 border-brand-500' : 'text-gray-500'}`}
        >
          {t.orderBook}
        </button>
        <button 
          onClick={() => setTab('trades')}
          className={`flex-1 py-2 text-sm font-medium transition-colors ${tab === 'trades' ? 'text-brand-500 border-b-2 border-brand-500' : 'text-gray-500'}`}
        >
          {t.recentTrades}
        </button>
      </div>

      <div className="grid grid-cols-3 text-[10px] text-gray-500 dark:text-gray-400 px-2 py-2 font-semibold shrink-0 uppercase tracking-tighter">
        <div className="text-left">{t.price}</div>
        <div className="text-right">{t.amount}</div>
        <div className="text-right pr-2">{tab === 'book' ? t.total : t.time}</div>
      </div>

      <div className="flex-1 flex flex-col overflow-hidden">
        {tab === 'book' ? (
          <div className="flex-1 flex flex-col justify-between overflow-hidden">
            <div className="flex flex-col justify-end overflow-hidden">
              {asks.slice(0, 12).map((ask, i) => (
                <Row key={`ask-${i}`} {...ask} price={ask.price} type="ask" />
              ))}
            </div>

            <div className="py-2 my-1 border-y border-gray-100 dark:border-slate-800 bg-gray-50 dark:bg-slate-900/40 shrink-0 flex items-center justify-center space-x-4">
               <div className="flex items-center space-x-1">
                 <span className={`text-xl font-bold font-mono ${lastPrice >= initialLastPrice ? 'text-trade-up' : 'text-trade-down'}`}>{lastPrice.toFixed(2)}</span>
                 {lastPrice >= initialLastPrice ? <ArrowUp size={16} className="text-trade-up" /> : <ArrowDown size={16} className="text-trade-down" />}
               </div>
               <div className="text-[11px] text-slate-500 font-mono mt-0.5">{INITIAL_MARKET_DATA.markPrice.toFixed(2)}</div>
            </div>

            <div className="overflow-hidden">
               {bids.slice(0, 12).map((bid, i) => (
                <Row key={`bid-${i}`} {...bid} price={bid.price} type="bid" />
              ))}
            </div>
          </div>
        ) : (
          <div className="flex-1 overflow-y-auto hide-scrollbar">
             {trades.map((trade) => (
               <div key={trade.id} className="grid grid-cols-3 text-xs py-1.5 hover:bg-slate-100 dark:hover:bg-slate-700 cursor-pointer transition-colors px-2">
                 <div className={`text-left font-mono font-bold ${trade.side === 'BUY' ? 'text-trade-up' : 'text-trade-down'}`}>
                   {trade.price.toFixed(2)}
                 </div>
                 <div className="text-right text-slate-700 dark:text-slate-300 font-mono">
                   {trade.amount}
                 </div>
                 <div className="text-right text-slate-500 dark:text-gray-400 font-mono">
                   {trade.time}
                 </div>
               </div>
             ))}
          </div>
        )}
      </div>
    </div>
  );
};

import React, { useState, useRef, useEffect } from 'react';
import { Language, Theme } from '../types';
import { TRANSLATIONS } from '../constants';
import { Moon, Sun, Globe, Wallet, Settings, ChevronDown, Plus } from 'lucide-react';
import { AccountPopover, SettingsModal, EmailModal } from './Modals';

interface HeaderProps {
  lang: Language;
  setLang: (l: Language) => void;
  theme: Theme;
  setTheme: (t: Theme) => void;
  isConnected: boolean;
  onConnectClick: () => void;
  onDeposit: () => void;
  onWithdraw: () => void;
  onDisconnect: () => void;
}

export const Header: React.FC<HeaderProps> = ({ 
  lang, setLang, theme, setTheme, isConnected, onConnectClick, onDeposit, onWithdraw, onDisconnect 
}) => {
  const t = TRANSLATIONS[lang];
  const [langOpen, setLangOpen] = useState(false);
  const [accountOpen, setAccountOpen] = useState(false);
  const [settingsOpen, setSettingsOpen] = useState(false);
  const [isEmailBound, setIsEmailBound] = useState(false);
  const [emailOpen, setEmailOpen] = useState(false);
  const popoverRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const handleClickOutside = (e: MouseEvent) => {
      if (popoverRef.current && !popoverRef.current.contains(e.target as Node)) setAccountOpen(false);
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const toggleTheme = () => {
    const newTheme = theme === 'dark' ? 'light' : 'dark';
    setTheme(newTheme);
    if (newTheme === 'dark') {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
  };

  return (
    <header className="h-14 bg-white dark:bg-dark-card border-b border-gray-200 dark:border-dark-border px-4 flex items-center justify-between sticky top-0 z-50">
      <div className="flex items-center space-x-10">
        <div className="flex items-center cursor-pointer">
          <img 
            src="https://r.jina.ai/i/6f9038ba986e4e8992c478a572c64993" 
            alt="GoldenDex" 
            className="h-7 w-auto object-contain"
          />
        </div>

        <nav className="flex items-center h-14">
          <button className="px-1 h-full flex items-center text-sm font-bold text-brand-500 border-b-2 border-brand-500 transition-colors">
            {t.perp}
          </button>
        </nav>
      </div>

      <div className="flex items-center space-x-4">
        {isConnected && (
           <button 
             onClick={onDeposit}
             className="flex items-center space-x-1 px-3 py-1.5 rounded-lg bg-[#DCA85E] text-slate-900 font-bold text-sm shadow hover:bg-[#c99750] transition-colors"
           >
             <Plus size={16} />
             <span>{t.deposit}</span>
           </button>
        )}

        {isConnected ? (
          <div className="relative" ref={popoverRef}>
            <button 
              onClick={() => setAccountOpen(!accountOpen)}
              className="flex items-center space-x-2 px-4 py-1.5 rounded-lg bg-gray-100 dark:bg-slate-800 text-slate-900 dark:text-slate-200 border border-gray-200 dark:border-slate-700 font-mono text-sm font-bold transition hover:border-brand-500"
            >
              <span>0x4b...5591</span>
              <ChevronDown size={14} className={`transition ${accountOpen ? 'rotate-180' : ''}`} />
            </button>
            {accountOpen && (
              <AccountPopover 
                lang={lang} 
                onClose={() => setAccountOpen(false)} 
                onDisconnect={() => { onDisconnect(); setAccountOpen(false); }} 
                onDeposit={onDeposit} 
                onWithdraw={onWithdraw} 
              />
            )}
          </div>
        ) : (
          <button onClick={onConnectClick} className="bg-brand-500 text-white px-4 py-1.5 rounded-full font-bold text-sm hover:bg-brand-600 transition-all">{t.connectWallet}</button>
        )}

        <div className="flex items-center space-x-2 border-l border-gray-200 dark:border-slate-700 pl-4">
          <div className="relative">
            <button onClick={() => setLangOpen(!langOpen)} className="flex items-center space-x-1 border border-gray-200 dark:border-slate-700 h-[38px] px-2.5 rounded-lg text-xs font-bold bg-white dark:bg-slate-800 transition hover:border-brand-500">
               <span className="uppercase text-gray-500 dark:text-gray-400">
                  {lang === 'en' ? '🇺🇸 English' : lang === 'zh-CN' ? '🇨🇳 简体中文' : '🇨🇳 繁體中文'}
               </span>
               <ChevronDown size={12} className="text-gray-500" />
            </button>
            {langOpen && (
              <div className="absolute right-0 mt-2 w-40 bg-white dark:bg-dark-card border border-gray-200 dark:border-slate-700 rounded-lg shadow-xl py-1 z-50">
                <button onClick={() => {setLang('en'); setLangOpen(false)}} className="block w-full text-left px-4 py-2 text-sm hover:bg-slate-100 dark:hover:bg-slate-800 dark:text-white">🇺🇸 English</button>
                <button onClick={() => {setLang('zh-CN'); setLangOpen(false)}} className="block w-full text-left px-4 py-2 text-sm hover:bg-slate-100 dark:hover:bg-slate-800 dark:text-white">🇨🇳 简体中文</button>
                <button onClick={() => {setLang('zh-TW'); setLangOpen(false)}} className="block w-full text-left px-4 py-2 text-sm hover:bg-slate-100 dark:hover:bg-slate-800 dark:text-white">🇨🇳 繁體中文</button>
              </div>
            )}
          </div>
          <button onClick={toggleTheme} className="text-gray-500 border border-gray-200 dark:border-slate-700 p-2 h-[38px] w-[38px] flex items-center justify-center rounded-lg bg-white dark:bg-slate-800 hover:border-brand-500 transition">{theme === 'dark' ? <Sun size={18} /> : <Moon size={18} />}</button>
          <button onClick={() => setSettingsOpen(true)} className="text-gray-500 border border-gray-200 dark:border-slate-700 p-2 h-[38px] w-[38px] flex items-center justify-center rounded-lg bg-white dark:bg-slate-800 hover:border-brand-500 transition"><Settings size={18} /></button>
        </div>
      </div>
      <SettingsModal 
        isOpen={settingsOpen} 
        onClose={() => setSettingsOpen(false)} 
        lang={lang} 
        isEmailBound={isEmailBound} 
        onBindClick={() => setEmailOpen(true)} 
      />
      <EmailModal 
        isOpen={emailOpen} 
        onClose={() => setEmailOpen(false)} 
        lang={lang} 
        onBind={() => { setIsEmailBound(true); setEmailOpen(false); }} 
      />
    </header>
  );
};

