const InfoRow = ({ 
  label, 
  value, 
  explanation, 
  isPnL = false 
}: { 
  label: string; 
  value: string; 
  explanation?: string; 
  isPnL?: boolean;
}) => {
  const [showTooltip, setShowTooltip] = useState(false);
