        <span className="text-xs text-gray-500 dark:text-gray-400 font-medium">{label}</span>
      </div>
      <span className={`text-xs font-mono font-bold ${colorClass}`}>{value}</span>

      {showTooltip && explanation && (
        <div className="absolute bottom-full mb-2 right-0 z-[2000] w-64 p-3 bg-white dark:bg-slate-800 border border-gray-200 dark:border-slate-700 rounded-lg shadow-2xl text-xs text-gray-600 dark:text-gray-300 leading-relaxed animate-in fade-in slide-in-from-bottom-2 duration-150 ring-1 ring-black/5 pointer-events-none">
