export const TradeForm: React.FC<TradeFormProps> = ({ lang, theme, isConnected, onConnect, onOrder, lastPrice, availableBalance, currentSymbol }) => {
  const t = TRANSLATIONS[lang];
  const [type, setType] = useState<OrderType>(OrderType.MARKET);
  const [marginMode, setMarginMode] = useState<MarginMode>(MarginMode.CROSS);
  const [leverage, setLeverage] = useState<number>(20);
  const [amount, setAmount] = useState<string>('');
  const [price, setPrice] = useState<string>('');
  const [unit, setUnit] = useState<'ASSET' | 'USDC'>('ASSET');
  const [sliderValue, setSliderValue] = useState(0);
  const [showLeveragePopup, setShowLeveragePopup] = useState(false);

  const assetSymbol = currentSymbol.replace('USDC', '');
  const effectivePrice = type === OrderType.LIMIT && price ? parseFloat(price) : lastPrice;

  const inputNum = parseFloat(amount) || 0;
  const xauAmount = unit === 'ASSET' ? inputNum : inputNum / effectivePrice;
  const usdcValue = unit === 'USDC' ? inputNum : inputNum * effectivePrice;

  const marginReq = usdcValue / leverage;
  const maxOpenUSDC = availableBalance * leverage;
  const estFee = usdcValue * 0.0005;

  const handleSliderChange = (val: number) => {
    setSliderValue(val);
    const targetUSDC = maxOpenUSDC * (val / 100);
    if (unit === 'USDC') {
      setAmount(targetUSDC.toFixed(2));
    } else {
      setAmount((targetUSDC / effectivePrice).toFixed(4));
    }
  };

  const handleOrderClick = (side: OrderSide) => {
    if (!isConnected) { onConnect(); return; }
    if (xauAmount <= 0) return;
    onOrder(side, type, xauAmount, effectivePrice, leverage, marginMode);
    setAmount('');
    setSliderValue(0);
  };

  const InfoRow = ({ label, value, color }: { label: string, value: string, color?: string }) => (
    <div className="flex justify-between text-xs py-1">
      <span className="text-gray-500 dark:text-gray-400">{label}</span>
      <span className={`font-mono font-medium ${color || 'text-slate-900 dark:text-slate-200'}`}>{value}</span>
    </div>
  );

  const calcLiqPrice = (side: OrderSide) => {
    if (effectivePrice <= 0) return "0.00";
    const factor = side === OrderSide.BUY ? (1 - 0.9 / leverage) : (1 + 0.9 / leverage);
    return (effectivePrice * factor).toFixed(2);
  };

  return (
    <div className="flex flex-col h-full bg-white dark:bg-dark-card border-l border-gray-200 dark:border-dark-border p-4 relative">
      <div className="flex justify-between items-center mb-4">
        <div className="flex bg-gray-100 dark:bg-slate-800 rounded border border-gray-200 dark:border-slate-700 p-0.5">
          <button onClick={() => setMarginMode(MarginMode.CROSS)} className={`px-3 py-1.5 text-xs font-bold rounded transition-all ${marginMode === MarginMode.CROSS ? 'bg-slate-500/30 text-brand-500' : 'text-gray-500'}`}>{t.cross}</button>
          <button onClick={() => setMarginMode(MarginMode.ISOLATED)} className={`px-3 py-1.5 text-xs font-bold rounded transition-all ${marginMode === MarginMode.ISOLATED ? 'bg-slate-500/30 text-brand-500' : 'text-gray-500'}`}>{t.isolated}</button>
        </div>
        <button onClick={() => setShowLeveragePopup(true)} className="flex items-center space-x-1 bg-gray-100 dark:bg-slate-800 hover:bg-gray-200 px-3 py-1.5 rounded text-xs font-bold text-slate-900 dark:text-white border border-gray-200 dark:border-slate-700">
          <span>{leverage}x</span><Edit3 size={12} className="text-gray-500" />
        </button>
      </div>

      <div className="flex bg-gray-100 dark:bg-slate-800 border border-gray-200 dark:border-slate-700 rounded p-0.5 mb-4">
        <button onClick={() => setType(OrderType.MARKET)} className={`flex-1 py-1.5 text-xs font-bold rounded transition-all ${type === OrderType.MARKET ? 'bg-slate-500 text-white shadow' : 'text-gray-500'}`}>{t.market}</button>
        <button onClick={() => setType(OrderType.LIMIT)} className={`flex-1 py-1.5 text-xs font-bold rounded transition-all ${type === OrderType.LIMIT ? 'bg-slate-500 text-white shadow' : 'text-gray-500'}`}>{t.limit}</button>
      </div>

      <div className="mb-3">
        <div className="text-xs text-gray-500 mb-1">{t.price}</div>
        <input type={type === OrderType.LIMIT ? "number" : "text"} value={type === OrderType.LIMIT ? price : ""} onChange={(e) => setPrice(e.target.value)} disabled={type === OrderType.MARKET} placeholder={type === OrderType.MARKET ? `${t.market} ${t.price}` : lastPrice.toFixed(2)} className="w-full bg-transparent border border-gray-200 dark:border-slate-700 rounded p-2.5 text-sm font-mono outline-none dark:text-white" />
      </div>

      <div className="mb-1">
        <div className="flex justify-between text-xs mb-1">
          <span className="text-gray-500">{t.amount}</span>
          <span className="text-gray-500">{t.avail}: <span className="font-mono">{availableBalance.toFixed(2)} USDC</span></span>
        </div>
        <div className="relative flex items-center">
          <input type="number" value={amount} onChange={(e) => setAmount(e.target.value)} className="w-full bg-transparent border border-gray-300 dark:border-slate-600 rounded p-2.5 pr-24 text-sm font-bold font-mono outline-none dark:text-white" placeholder="0.00" />
          <button 
            onClick={() => setUnit(u => u === 'ASSET' ? 'USDC' : 'ASSET')}
            className="absolute right-0 h-full flex items-center pr-2 group"
          >
            <span className="bg-gray-200 dark:bg-slate-700 text-xs font-bold px-2 py-1 rounded flex items-center space-x-1 group-hover:bg-slate-600 transition-colors uppercase">
              <span>{unit === 'ASSET' ? assetSymbol : 'USDC'}</span>
              <Repeat size={10} className="text-gray-500" />
            </span>
          </button>
        </div>
      </div>

      <div className="mt-4 mb-4">
        <CustomSlider value={sliderValue} onChange={handleSliderChange} theme={theme} />
      </div>

      <div className="grid grid-cols-2 gap-3 mb-6">
        <div className="flex flex-col">
          <button onClick={() => handleOrderClick(OrderSide.BUY)} className="py-4 bg-trade-up hover:bg-green-600 text-white font-bold rounded-lg shadow-lg shadow-green-900/20 mb-3">{t.buyLong}</button>
          <div className="px-1 space-y-1">
             <InfoRow label={t.liqPrice} value={calcLiqPrice(OrderSide.BUY)} color="text-trade-up" />
             <InfoRow label={t.margin} value={marginReq.toFixed(2)} color="text-trade-up" />
             <InfoRow label={t.maxOpen} value={`${(maxOpenUSDC / effectivePrice).toFixed(2)} ${assetSymbol}`} color="text-trade-up" />
             <InfoRow label={t.estFee} value={`${estFee.toFixed(2)} USDC`} color="text-trade-up" />
          </div>
        </div>
        <div className="flex flex-col">
          <button onClick={() => handleOrderClick(OrderSide.SELL)} className="py-4 bg-trade-down hover:bg-red-600 text-white font-bold rounded-lg shadow-lg shadow-red-900/20 mb-3">{t.sellShort}</button>
          <div className="px-1 space-y-1">
             <InfoRow label={t.liqPrice} value={calcLiqPrice(OrderSide.SELL)} color="text-trade-down" />
             <InfoRow label={t.margin} value={marginReq.toFixed(2)} color="text-trade-down" />
             <InfoRow label={t.maxOpen} value={`${(maxOpenUSDC / effectivePrice).toFixed(2)} ${assetSymbol}`} color="text-trade-down" />
             <InfoRow label={t.estFee} value={`${estFee.toFixed(2)} USDC`} color="text-trade-down" />
          </div>
        </div>
      </div>

      {showLeveragePopup && (
        <>
          <div className="fixed inset-0 bg-black/50 z-[100] backdrop-blur-[1px]" onClick={() => setShowLeveragePopup(false)} />
          <div className="absolute top-16 left-4 right-4 bg-white dark:bg-dark-card border border-gray-200 dark:border-slate-700 rounded-lg shadow-2xl z-[101] p-4 animate-in zoom-in-95 duration-200">
             <div className="flex justify-between items-center mb-4"><span className="font-bold text-sm dark:text-white">{t.adjustLeverage}</span><button onClick={() => setShowLeveragePopup(false)} className="dark:text-white"><X size={16} /></button></div>
             <div className="bg-gray-100 dark:bg-slate-800 rounded p-2 mb-6 text-center"><span className="text-2xl font-bold text-brand-500">{leverage}x</span></div>
             <div className="relative px-1">
               <input type="range" min="1" max="50" step="1" value={leverage} onChange={(e) => setLeverage(parseInt(e.target.value))} className="w-full h-2 bg-gray-200 rounded-lg appearance-none cursor-pointer accent-brand-500 mb-6" />
               <div className="absolute -bottom-1 left-0 text-[10px] font-bold text-gray-400">1x</div>
               <div className="absolute -bottom-1 right-0 text-[10px] font-bold text-gray-400">50x</div>
             </div>
             <button onClick={() => setShowLeveragePopup(false)} className="w-full py-2 bg-brand-500 text-white font-bold rounded text-sm mt-4">{t.confirm}</button>
          </div>
        </>
      )}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { MOCK_ASKS, MOCK_BIDS, TRANSLATIONS, INITIAL_MARKET_DATA } from '../constants';
import { Language } from '../types';
import { ArrowUp, ArrowDown } from 'lucide-react';

interface OrderBookProps {
  lang: Language;
  lastPrice: number;
}

const Row = ({ price, amount, total, type }: { price: number, amount: string, total: string, type: 'ask' | 'bid' }) => {
  const bgClass = type === 'ask' ? 'bg-trade-down' : 'bg-trade-up';
  const textClass = type === 'ask' ? 'text-trade-down' : 'text-trade-up';
  const width = Math.min(parseFloat(total) * 1, 100); 

  return (
    <div className="grid grid-cols-3 text-xs py-1 hover:bg-slate-100 dark:hover:bg-slate-700 cursor-pointer transition-colors relative group items-center">
      <div 
        className={`absolute top-0 right-0 h-full opacity-10 transition-all duration-300 ${bgClass}`} 
        style={{ width: `${width}%` }} 
      />
      <div className={`text-left pl-2 ${textClass} z-10 font-mono`}>{price.toFixed(2)}</div>
      <div className="text-right text-slate-700 dark:text-slate-300 z-10 font-mono">{amount}</div>
      <div className="text-right pr-2 text-slate-500 dark:text-gray-400 z-10 font-mono">{total}</div>
    </div>
  );
};

export const OrderBook: React.FC<OrderBookProps> = ({ lang, lastPrice: initialLastPrice }) => {
  const t = TRANSLATIONS[lang];
  const [tab, setTab] = useState<'book' | 'trades'>('book');
  const [asks, setAsks] = useState(MOCK_ASKS);
  const [bids, setBids] = useState(MOCK_BIDS);
  const [lastPrice, setLastPrice] = useState(initialLastPrice);
  const [trades, setTrades] = useState<any[]>([]);

  // Simulation effect for Order Book and Trades
  useEffect(() => {
    // 调整为 21 行以匹配：10档卖盘 + 1行中间价 + 10档买盘
    const initialTrades = Array.from({ length: 21 }, (_, i) => ({
      id: `initial-${i}`,
      price: initialLastPrice + (Math.random() - 0.5) * 5,
      amount: (Math.random() * 2).toFixed(3),
      time: new Date(Date.now() - i * 5000).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit', hour12: false }),
      side: Math.random() > 0.5 ? 'BUY' : 'SELL'
    }));
    setTrades(initialTrades);

    const interval = setInterval(() => {
      // Update Price
      const priceChange = (Math.random() - 0.5) * 0.5;
      const newPrice = lastPrice + priceChange;
      setLastPrice(newPrice);

      // Update Order Book
      setAsks(prev => prev.map(a => ({
         ...a,
         amount: Math.max(0.1, parseFloat(a.amount) + (Math.random() - 0.5)).toFixed(3),
         total: Math.max(1, parseFloat(a.total) + (Math.random() - 0.5) * 2).toFixed(3)
      })));
      setBids(prev => prev.map(b => ({
         ...b,
         amount: Math.max(0.1, parseFloat(b.amount) + (Math.random() - 0.5)).toFixed(3),
         total: Math.max(1, parseFloat(b.total) + (Math.random() - 0.5) * 2).toFixed(3)
      })));

      // Occasional new trade
      if (Math.random() > 0.4) {
        const side = Math.random() > 0.5 ? 'BUY' : 'SELL';
        const newTrade = {
          id: Date.now().toString(),
          price: newPrice,
          amount: (Math.random() * 1.2).toFixed(3),
          time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit', hour12: false }),
          side
        };
        setTrades(prev => [newTrade, ...prev].slice(0, 21));
      }
    }, 1000);

    return () => clearInterval(interval);
  }, [lastPrice, initialLastPrice]);

  return (
    <div className="flex flex-col h-full bg-white dark:bg-dark-card border-l border-gray-200 dark:border-dark-border overflow-hidden select-none">
      <div className="flex border-b border-gray-200 dark:border-dark-border shrink-0">
        <button 
          onClick={() => setTab('book')}
          className={`flex-1 py-2 text-sm font-medium transition-colors ${tab === 'book' ? 'text-brand-500 border-b-2 border-brand-500' : 'text-gray-500'}`}
        >
          {t.orderBook}
        </button>
        <button 
          onClick={() => setTab('trades')}
          className={`flex-1 py-2 text-sm font-medium transition-colors ${tab === 'trades' ? 'text-brand-500 border-b-2 border-brand-500' : 'text-gray-500'}`}
        >
          {t.recentTrades}
        </button>
      </div>

      <div className="grid grid-cols-3 text-[10px] text-gray-500 dark:text-gray-400 px-2 py-2 font-semibold shrink-0 uppercase tracking-tighter">
        <div className="text-left">{t.price}</div>
        <div className="text-right">{t.amount}</div>
        <div className="text-right pr-2">{tab === 'book' ? t.total : t.time}</div>
      </div>

      <div className="flex-1 flex flex-col overflow-hidden">
        {tab === 'book' ? (
          <div className="flex-1 flex flex-col justify-between overflow-hidden">
            <div className="flex flex-col justify-end overflow-hidden">
              {/* 减少至 10 档 */}
              {asks.slice(0, 10).map((ask, i) => (
                <Row key={`ask-${i}`} {...ask} price={ask.price} type="ask" />
              ))}
            </div>

            <div className="py-2 my-1 border-y border-gray-100 dark:border-slate-800 bg-gray-50 dark:bg-slate-900/40 shrink-0 flex items-center justify-center space-x-4">
               <div className="flex items-center space-x-1">
                 <span className={`text-xl font-bold font-mono ${lastPrice >= initialLastPrice ? 'text-trade-up' : 'text-trade-down'}`}>{lastPrice.toFixed(2)}</span>
                 {lastPrice >= initialLastPrice ? <ArrowUp size={16} className="text-trade-up" /> : <ArrowDown size={16} className="text-trade-down" />}
               </div>
               <div className="text-[11px] text-slate-500 font-mono mt-0.5">{INITIAL_MARKET_DATA.markPrice.toFixed(2)}</div>
            </div>

            <div className="overflow-hidden">
               {/* 减少至 10 档 */}
               {bids.slice(0, 10).map((bid, i) => (
                <Row key={`bid-${i}`} {...bid} price={bid.price} type="bid" />
              ))}
            </div>
          </div>
        ) : (
          <div className="flex-1 overflow-y-auto hide-scrollbar">
             {trades.map((trade) => (
               <div key={trade.id} className="grid grid-cols-3 text-xs py-1.5 hover:bg-slate-100 dark:hover:bg-slate-700 cursor-pointer transition-colors px-2">
                 <div className={`text-left font-mono font-bold ${trade.side === 'BUY' ? 'text-trade-up' : 'text-trade-down'}`}>
                   {trade.price.toFixed(2)}
                 </div>
                 <div className="text-right text-slate-700 dark:text-slate-300 font-mono">
                   {trade.amount}
                 </div>
                 <div className="text-right text-slate-500 dark:text-gray-400 font-mono">
                   {trade.time}
                 </div>
               </div>
             ))}
          </div>
        )}
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { Header } from './components/Header';
import { MarketStats } from './components/MarketStats';
import { CandleChart } from './components/CandleChart';
import { OrderBook } from './components/OrderBook';
import { TradeForm } from './components/TradeForm';
import { PositionTable } from './components/PositionTable';
import { AccountInfo } from './components/AccountInfo';
import { NotificationContainer, RichNotification } from './components/Notification';
import { WalletModal, AssetModal, MarginManageModal, SignatureModal, SettingsModal, EmailModal } from './components/Modals';
import { INITIAL_MARKET_DATA, MOCK_POSITIONS, TRANSLATIONS, INITIAL_ACCOUNT_INFO, MOCK_ASSETS_HISTORY } from './constants';
import { Language, Theme, MarketData, Position, Order, OrderSide, OrderType, MarginMode, AccountInfo as AccountInfoType } from './types';

export default function App() {
  const [lang, setLang] = useState<Language>('zh-CN');
  const [theme, setTheme] = useState<Theme>('dark');
  const [isConnected, setIsConnected] = useState(false);
  const [isSigned, setIsSigned] = useState(false);
  const [isEmailBound, setIsEmailBound] = useState(false);
  const [marketData, setMarketData] = useState<MarketData>(INITIAL_MARKET_DATA);
  const [positions, setPositions] = useState<Position[]>(MOCK_POSITIONS);
  const [orders, setOrders] = useState<Order[]>([]);
  const [assetHistory, setAssetHistory] = useState(MOCK_ASSETS_HISTORY);
  const [notifications, setNotifications] = useState<RichNotification[]>([]);
  const [accountInfo, setAccountInfo] = useState<AccountInfoType>(INITIAL_ACCOUNT_INFO);

  const [showWalletModal, setShowWalletModal] = useState(false);
  const [showSignModal, setShowSignModal] = useState(false);
  const [showSettingsModal, setShowSettingsModal] = useState(false);
  const [showEmailModal, setShowEmailModal] = useState(false);

  const [assetModal, setAssetModal] = useState<{ isOpen: boolean, type: 'deposit' | 'withdraw' }>({ isOpen: false, type: 'deposit' });
  const [marginManage, setMarginManage] = useState<{ isOpen: boolean; type: 'add' | 'extract'; pos: Position | null }>({ isOpen: false, type: 'add', pos: null });

  const addRichNotification = (type: RichNotification['type'], title: string, message: string) => {
    const id = Date.now().toString();
    setNotifications(prev => [...prev, { id, type, title, message }]);
  };

  const handleConnectClick = () => {
    setShowWalletModal(true);
  };

  const handleWalletSelect = () => {
    setShowWalletModal(false);
    setShowSignModal(true);
  };

  const handleSign = () => {
    setShowSignModal(false);
    setIsConnected(true);
    setIsSigned(true);
    const title = lang === 'en' ? 'Welcome Back' : (lang === 'zh-CN' ? '欢迎回来' : '歡迎回來');
    const body = lang === 'en' ? 'Wallet connected and signed successfully.' : '钱包连接并签名成功。';
    addRichNotification('success', title, body);
  };

  const handleOrder = (side: OrderSide, type: OrderType, size: number, price: number, leverage: number, marginMode: MarginMode) => {
    if (!isSigned) { setShowWalletModal(true); return; }

    if (type === OrderType.MARKET) {
      const newPos: Position = { id: Date.now().toString(), symbol: marketData.symbol, side, size, entryPrice: price, markPrice: price, leverage, margin: (size * price) / leverage, marginMode, pnl: 0, pnlPercent: 0, liquidationPrice: side === OrderSide.BUY ? price * 0.8 : price * 1.2 };
      setPositions(prev => [newPos, ...prev]);

      const title = lang === 'en' ? 'Market Order Filled' : (lang === 'zh-CN' ? '市价单已完全成交' : '市價單已完全成交');
      const body = lang === 'en' 
        ? `Market ${side === OrderSide.BUY ? 'Buy' : 'Sell'} ${size.toFixed(2)} XAU fully filled.\nAvg Price $${price.toFixed(2)} | Fee $${(size * price * 0.0005).toFixed(2)}`
        : `市价${side === OrderSide.BUY ? '买入' : '卖出'} ${size.toFixed(2)} ${marketData.symbol.replace('USDC', '')} 已完全成交\n平均成交价 $${price.toFixed(2)} | 手续费 $${(size * price * 0.0005).toFixed(2)}`;
      addRichNotification('success', title, body);
    } else {
      const newOrder: Order = {
        id: Date.now().toString(),
        symbol: marketData.symbol,
        side,
        type: OrderType.LIMIT,
        price,
        amount: size,
        filled: 0,
        status: 'OPEN',
        time: new Date().toLocaleString()
      };
      setOrders(prev => [newOrder, ...prev]);

      const title = lang === 'en' ? 'Order Created' : (lang === 'zh-CN' ? '下单成功' : '下單成功');
      const sideStr = lang === 'en' ? (side === OrderSide.BUY ? 'Long' : 'Short') : (side === OrderSide.BUY ? '多头' : '空头');
      const body = lang === 'en'
        ? `You have successfully submitted ${marketData.symbol} ${sideStr} Limit Order.\nPrice $${price.toLocaleString()} | Amount ${size} XAU | Leverage ${leverage}x`
        : `您已成功提交${marketData.symbol} ${sideStr} 限价单\n价格 $${price.toLocaleString()} | 数量 ${size} ${marketData.symbol.replace('USDC', '')} | 杠杆 ${leverage}x`;
      addRichNotification('success', title, body);
    }
  };

  const handleClosePosition = (id: string, type: OrderType, closePrice?: number, closeAmount?: number) => {
    const pos = positions.find(p => p.id === id);
    if (!pos) return;

    setPositions(prev => prev.filter(x => x.id !== id));

    const title = lang === 'en' ? 'Position Closed' : (lang === 'zh-CN' ? '仓位已平仓' : '倉位已平倉');
    const sideStr = lang === 'en' ? (pos.side === OrderSide.BUY ? 'Long' : 'Short') : (pos.side === OrderSide.BUY ? '多头' : '空头');
    const body = lang === 'en'
      ? `Successfully closed ${pos.symbol} ${sideStr}.\nClosed Amount ${pos.size} XAU | Realized PnL +$${pos.pnl.toFixed(2)}`
      : `您已成功平仓 ${pos.symbol} ${sideStr}\n平仓数量 ${pos.size} ${pos.symbol.replace('USDC', '')} | 实现盈亏 +$${pos.pnl.toFixed(2)}`;
    addRichNotification('success', title, body);
  };

  const handleAssetConfirm = (type: 'deposit' | 'withdraw', v: number) => {
     const status = type === 'deposit' ? 'completed' : (v >= 100 ? 'reviewing' : 'completed');
     const newRecord = {
        id: Date.now().toString(),
        asset: 'USDC',
        type,
        amount: v,
        fee: type === 'withdraw' ? 0.5 : null,
        hash: '0x' + Math.random().toString(16).slice(2, 10) + '...',
        status,
        time: new Date().toISOString().replace('T', ' ').slice(0, 19)
     };
     setAssetHistory(prev => [newRecord, ...prev]);
     setAssetModal(m => ({ ...m, isOpen: false }));

     if (type === 'deposit') {
       const title = lang === 'en' ? 'Deposit Success' : (lang === 'zh-CN' ? '充值成功' : '充值成功');
       const body = lang === 'en' 
        ? `You have successfully deposited ${v.toLocaleString()} USDC, please check.`
        : `您已成功充值 ${v.toLocaleString()} USDC，请查看`;
       addRichNotification('success', title, body);
     } else {
       const title = lang === 'en' ? 'Withdrawal Success' : (lang === 'zh-CN' ? '提现成功' : '提現成功');
       const body = lang === 'en'
        ? `You have successfully withdrawn ${v.toLocaleString()} USDC to 0x4b...5591 (Arbitrum), estimated arrival in 1 minute.`
        : `您已成功提现 ${v.toLocaleString()} USDC 至 0x4b...5591 (Arbitrum)，预计 1 分钟到账。`;
       addRichNotification('success', title, body);
     }
  };

  const simulateLiquidation = () => {
    const title = lang === 'en' ? 'Position Liquidated' : (lang === 'zh-CN' ? '仓位已强平' : '倉位已強平');
    const body = lang === 'en'
      ? `Your ${marketData.symbol} Long position triggered liquidation at $2,800. $428 Liquidation fee deducted.`
      : `您的 ${marketData.symbol} 多头仓位已触发强平，强平价格 $2,800，已扣除 $428 强平罚金。`;
    addRichNotification('liquidation', title, body);
  };

  return (
    <div className={`flex flex-col h-screen ${theme} bg-gray-50 dark:bg-dark-bg text-slate-900 dark:text-slate-200 font-sans overflow-hidden transition-colors`}>
      <Header 
        lang={lang} setLang={setLang} theme={theme} setTheme={setTheme}
        isConnected={isSigned} 
        onConnectClick={handleConnectClick} 
        onDeposit={() => setAssetModal({ isOpen: true, type: 'deposit' })}
        onWithdraw={() => setAssetModal({ isOpen: true, type: 'withdraw' })}
        onDisconnect={() => { setIsConnected(false); setIsSigned(false); setPositions([]); setOrders([]); }}
      />
      <MarketStats data={marketData} lang={lang} onMarketSelect={setMarketData} />
      <main className="flex-1 flex overflow-hidden">
        <div className="flex-1 flex flex-col min-w-0">
          <div className="flex-[3] flex border-b border-gray-200 dark:border-dark-border">
            <div className="flex-1 relative border-r border-gray-200 dark:border-dark-border">
              <CandleChart lang={lang} currentMarket={marketData} />
              <button 
                onClick={simulateLiquidation}
                className="absolute bottom-4 left-4 bg-rose-600/20 hover:bg-rose-600/40 text-rose-500 text-[10px] px-2 py-1 rounded border border-rose-500/30 font-bold transition-all z-20"
              >
                Simulate Liq.
              </button>
            </div>
            <div className="w-[280px] hidden lg:block bg-white dark:bg-dark-card shrink-0"><OrderBook lang={lang} lastPrice={marketData.lastPrice} /></div>
          </div>
          <div className="flex-[2] min-h-[250px] overflow-hidden">
             <PositionTable 
               positions={positions} orders={orders} assetHistory={assetHistory} lang={lang} theme={theme}
               onClosePosition={handleClosePosition}
               onCancelOrder={(id) => setOrders(o => o.filter(x => x.id !== id))}
               onEditMargin={(pos, type) => setMarginManage({ isOpen: true, type, pos })}
               onCloseAll={() => setPositions([])}
               onCancelAll={() => setOrders([])}
             />
          </div>
        </div>
        {/* 设置 z-30 确保右侧面板内的浮窗能够高于持仓列表按钮 */}
        <div className="w-[340px] flex flex-col border-l border-gray-200 dark:border-dark-border bg-white dark:bg-dark-card z-30 shrink-0">
          <div className="flex-1 overflow-y-auto">
            <TradeForm lang={lang} theme={theme} isConnected={isSigned} onConnect={() => setShowWalletModal(true)} onOrder={handleOrder} lastPrice={marketData.lastPrice} availableBalance={accountInfo.marginBalance} currentSymbol={marketData.symbol} />
          </div>
          <div className="shrink-0 border-t border-gray-200 dark:border-dark-border"><AccountInfo lang={lang} info={accountInfo} /></div>
        </div>
      </main>

      <NotificationContainer notifications={notifications} removeNotification={(id) => setNotifications(n => n.filter(x => x.id !== id))} />

      <WalletModal isOpen={showWalletModal} onClose={() => setShowWalletModal(false)} lang={lang} onConnect={handleWalletSelect} />
      <SignatureModal isOpen={showSignModal} onClose={() => setShowSignModal(false)} lang={lang} onSign={handleSign} />
      <SettingsModal isOpen={showSettingsModal} onClose={() => setShowSettingsModal(false)} lang={lang} isEmailBound={isEmailBound} onBindClick={() => setShowEmailModal(true)} />
      <EmailModal isOpen={showEmailModal} onClose={() => setShowEmailModal(false)} lang={lang} onBind={() => { setIsEmailBound(true); setShowEmailModal(false); }} />

      <AssetModal 
        isOpen={assetModal.isOpen} 
        onClose={() => setAssetModal(prev => ({ ...prev, isOpen: false }))} 
        lang={lang} 
        type={assetModal.type} 
        maxAmount={1000.00} 
        onConfirm={(v) => handleAssetConfirm(assetModal.type, v)} 
        theme={theme}
      />

      {marginManage.isOpen && marginManage.pos && (
         <MarginManageModal 
            isOpen={true} onClose={() => setMarginManage(m => ({...m, isOpen: false}))}
            lang={lang} theme={theme} type={marginManage.type} pos={marginManage.pos}
            available={marginManage.type === 'add' ? accountInfo.marginBalance : marginManage.pos.margin - 100}
            onConfirm={(v) => {
              setPositions(prev => prev.map(p => p.id === marginManage.pos?.id ? { ...p, margin: marginManage.type === 'add' ? p.margin + v : p.margin - v } : p));
              setMarginManage(m => ({ ...m, isOpen: false }));
              addRichNotification('success', lang === 'en' ? 'Margin Adjusted' : '保证金调整成功', `${marginManage.type === 'add' ? 'Added' : 'Removed'} ${v} USDC margin.`);
            }}
         />
      )}
    </div>
  );
}

import React, { useState } from 'react';
import { AccountInfo as AccountInfoType, Language } from '../types';
import { TRANSLATIONS } from '../constants';
import { Info } from 'lucide-react';

interface AccountInfoProps {
  lang: Language;
  info: AccountInfoType;
}

const InfoRow = ({ 
  label, 
  value, 
  explanation, 
  isPnL = false 
}: { 
  label: string; 
  value: string; 
  explanation?: string; 
  isPnL?: boolean;
}) => {
  const [showTooltip, setShowTooltip] = useState(false);
  let colorClass = 'text-slate-900 dark:text-slate-200';
  if (isPnL) {
    if (value.startsWith('+')) colorClass = 'text-trade-up';
    else if (value.startsWith('-')) colorClass = 'text-trade-down';
  }

  return (
    <div className="flex justify-between items-center py-1.5 group relative">
      <div 
        className="flex items-center space-x-1 cursor-help border-b border-dashed border-gray-300 dark:border-slate-700 transition-colors hover:border-brand-500"
        onMouseEnter={() => setShowTooltip(true)}
        onMouseLeave={() => setShowTooltip(false)}
      >
        <span className="text-xs text-gray-500 dark:text-gray-400 font-medium">{label}</span>
      </div>
      <span className={`text-xs font-mono font-bold ${colorClass}`}>{value}</span>

      {showTooltip && explanation && (
        <div className="absolute right-full top-1/2 -translate-y-1/2 mr-3 z-[5000] w-64 p-3 bg-white dark:bg-slate-800 border border-gray-200 dark:border-slate-700 rounded-lg shadow-2xl text-xs text-gray-600 dark:text-gray-300 leading-relaxed animate-in fade-in slide-in-from-right-2 duration-150 ring-1 ring-black/5 pointer-events-none">
          <div className="font-bold text-slate-900 dark:text-white mb-1 flex items-center space-x-1">
            <Info size={12} className="text-brand-500" />
            <span>{label}</span>
          </div>
          {explanation}
        </div>
      )}
    </div>
  );
};

export const AccountInfo: React.FC<AccountInfoProps> = ({ lang, info }) => {
  const t = TRANSLATIONS[lang];

  return (
    <div className="flex flex-col bg-white dark:bg-dark-card border-l border-t border-gray-200 dark:border-dark-border p-4 flex-1">
      <div className="mb-4">
        <h4 className="text-sm font-black text-slate-900 dark:text-white mb-3 border-l-4 border-brand-500 pl-3 uppercase tracking-wider">
          {t.contractAccount}
        </h4>
        <div className="space-y-0.5">
          <InfoRow 
            label={t.totalValue} 
            value={`${info.totalValue.toLocaleString()} USDC`} 
            explanation={t.explanations.totalValue}
          />
          <InfoRow 
            label={t.unrealized} 
            value={`${info.unrealizedPnl >= 0 ? '+' : ''}${info.unrealizedPnl.toLocaleString()} USDC`} 
