import React, { useState, useMemo, useEffect, useRef } from 'react';
import { AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, BarChart, Bar } from 'recharts';
import { CHART_DATA, MOCK_ASKS, MOCK_BIDS, TRANSLATIONS, TIMEFRAMES } from '../constants';
import { Language, MarketData } from '../types';
import { ChevronDown, LineChart as LineIcon, BarChart2, Layers } from 'lucide-react';

type ChartType = 'line' | 'candle' | 'depth';
type PriceSourceKey = 'lastPrice' | 'markPrice' | 'indexPrice';

interface CandleChartProps {
  lang: Language;
  currentMarket: MarketData;
}

const CandleStickShape = (props: any) => {
  const { x, y, width, height, payload } = props;
  const { open, close, high, low } = payload;
  const isUp = close >= open;
  const color = isUp ? '#10B981' : '#F43F5E';

  const bodyLength = Math.abs(close - open);
  const pixelsPerUnit = bodyLength === 0 ? 0 : height / bodyLength;

  let wickTop = y;
  let wickBottom = y + height;

  if (pixelsPerUnit > 0) {
      const highDiff = high - Math.max(open, close);
      const lowDiff = Math.min(open, close) - low;
      wickTop = y - (highDiff * pixelsPerUnit);
      wickBottom = y + height + (lowDiff * pixelsPerUnit);
  }

  return (
    <g>
      <line x1={x + width / 2} y1={wickTop} x2={x + width / 2} y2={wickBottom} stroke={color} strokeWidth={1} />
      <rect x={x} y={y} width={width} height={Math.max(1, height)} fill={color} stroke="none"/>
    </g>
  );
};

export const CandleChart: React.FC<CandleChartProps> = ({ lang, currentMarket }) => {
  const t = TRANSLATIONS[lang];
  const [chartType, setChartType] = useState<ChartType>('candle');
  const [timeframe, setTimeframe] = useState('15m');
  const [priceSourceKey, setPriceSourceKey] = useState<PriceSourceKey>('lastPrice');
  const [isDropdownOpen, setIsDropdownOpen] = useState(false);
  const dropdownRef = useRef<HTMLDivElement>(null);

  // Initialize data with consistent historical prices
  const initialData = useMemo(() => {
    let basePrice = currentMarket.lastPrice;
    return Array.from({ length: 60 }, (_, i) => {
      const open = basePrice + (Math.random() - 0.5) * 10;
      const close = open + (Math.random() - 0.5) * 8;
      const high = Math.max(open, close) + Math.random() * 4;
      const low = Math.min(open, close) - Math.random() * 4;
      basePrice = close;
      return { time: i, open, close, high, low };
    });
  }, [currentMarket.symbol]);

  const [liveData, setLiveData] = useState(initialData);
  const [liveAsks, setLiveAsks] = useState(MOCK_ASKS);
  const [liveBids, setLiveBids] = useState(MOCK_BIDS);

  // Track ticks to simulate timeframe completion
  const tickCountRef = useRef(0);
  const TICKS_PER_CANDLE = 10; // New candle every ~5 seconds

  useEffect(() => {
    const interval = setInterval(() => {
      setLiveData(prev => {
        const newData = [...prev];
        const lastIdx = newData.length - 1;
        const lastCandle = { ...newData[lastIdx] };

        // Random walk for price movement
        const volatility = 1.5;
        const drift = (initialData[0].open - lastCandle.close) * 0.01; // Slight pull towards initial price to prevent infinite drift
        const change = (Math.random() - 0.5) * volatility + drift;
        const newPrice = lastCandle.close + change;

        tickCountRef.current += 1;

        if (tickCountRef.current >= TICKS_PER_CANDLE) {
          // Finalize current candle and start a new one
          tickCountRef.current = 0;
          const nextCandle = {
            time: lastCandle.time + 1,
            open: lastCandle.close,
            close: newPrice,
            high: Math.max(lastCandle.close, newPrice),
            low: Math.min(lastCandle.close, newPrice)
          };
          return [...newData.slice(1), nextCandle];
        } else {
          // Update the current candle (real-time tick)
          lastCandle.close = newPrice;
          lastCandle.high = Math.max(lastCandle.high, newPrice);
          lastCandle.low = Math.min(lastCandle.low, newPrice);
          newData[lastIdx] = lastCandle;
          return newData;
        }
      });

      // Update depth slightly for visual "noise"
      setLiveAsks(prev => prev.map(a => ({ ...a, amount: Math.max(0.1, (parseFloat(a.amount) + (Math.random() - 0.5))).toFixed(3) })));
      setLiveBids(prev => prev.map(b => ({ ...b, amount: Math.max(0.1, (parseFloat(b.amount) + (Math.random() - 0.5))).toFixed(3) })));

    }, 500); // 500ms ticks for smoothness

    return () => clearInterval(interval);
  }, [initialData]);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
        setIsDropdownOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const displayData = useMemo(() => {
    if (chartType === 'depth') {
        const bids = [...liveBids]
            .sort((a, b) => b.price - a.price)
            .reduce((acc: any[], item) => {
                const prevTotal = acc.length > 0 ? parseFloat(acc[acc.length - 1].total) : 0;
                const total = prevTotal + parseFloat(item.amount);
                acc.push({ price: item.price, bidTotal: total, total: total.toFixed(3) });
                return acc;
            }, [])
            .reverse();

        const asks = [...liveAsks]
            .sort((a, b) => a.price - b.price)
            .reduce((acc: any[], item) => {
                const prevTotal = acc.length > 0 ? parseFloat(acc[acc.length - 1].total) : 0;
                const total = prevTotal + parseFloat(item.amount);
                acc.push({ price: item.price, askTotal: total, total: total.toFixed(3) });
                return acc;
            }, []);

        return [
            ...bids.map(b => ({ ...b, askTotal: null })), 
            ...asks.map(a => ({ ...a, bidTotal: null }))
        ].sort((a, b) => a.price - b.price);
    } else {
        return liveData.map(d => {
            let val = d.close;
            // Simulated offset for Mark/Index price sources
            if (priceSourceKey === 'markPrice') val = d.close * 1.0002;
            if (priceSourceKey === 'indexPrice') val = d.close * 0.9998;
            return {
                ...d,
                displayPrice: val,
                body: [Math.min(d.open, d.close), Math.max(d.open, d.close)]
            };
        });
    }
  }, [chartType, priceSourceKey, liveData, liveAsks, liveBids]);

  return (
    <div className="w-full h-full flex flex-col bg-white dark:bg-dark-bg relative">
      <div className="flex items-center justify-between px-4 py-2 border-b border-gray-100 dark:border-slate-800 z-10 bg-white dark:bg-dark-bg">
         <div className="flex space-x-1 overflow-x-auto hide-scrollbar mr-2">
           {TIMEFRAMES.map(tf => (
             <button
               key={tf}
               onClick={() => setTimeframe(tf)}
               className={`px-2 py-1 text-xs font-medium rounded transition-colors whitespace-nowrap ${
                 timeframe === tf 
                   ? 'text-brand-500 bg-brand-500/10' 
                   : 'text-gray-500 hover:text-slate-900 dark:text-gray-400 dark:hover:text-slate-200'
               }`}
             >
               {tf}
             </button>
           ))}
         </div>

         <div className="flex items-center space-x-3 shrink-0">
             <div className="flex bg-gray-100 dark:bg-slate-800 rounded p-0.5">
               <button onClick={() => setChartType('line')} className={`p-1.5 rounded transition-colors ${chartType === 'line' ? 'bg-white dark:bg-slate-600 text-brand-500 shadow' : 'text-gray-400 hover:text-gray-600 dark:hover:text-gray-200'}`}>
                 <LineIcon size={14} />
               </button>
               <button onClick={() => setChartType('candle')} className={`p-1.5 rounded transition-colors ${chartType === 'candle' ? 'bg-white dark:bg-slate-600 text-brand-500 shadow' : 'text-gray-400 hover:text-gray-600 dark:hover:text-gray-200'}`}>
                 <BarChart2 size={14} />
               </button>
               <button onClick={() => setChartType('depth')} className={`p-1.5 rounded transition-colors ${chartType === 'depth' ? 'bg-white dark:bg-slate-600 text-brand-500 shadow' : 'text-gray-400 hover:text-gray-600 dark:hover:text-gray-200'}`}>
                 <Layers size={14} />
               </button>
             </div>

             <div className="relative" ref={dropdownRef}>
                 <button 
                    onClick={() => setIsDropdownOpen(!isDropdownOpen)}
                    className="flex items-center space-x-1 text-xs font-bold text-slate-700 dark:text-slate-300 hover:text-brand-500 transition-colors"
                 >
                     <span>{t[priceSourceKey]}</span>
                     <ChevronDown size={14} className={`transition-transform ${isDropdownOpen ? 'rotate-180' : ''}`} />
                 </button>
                 {isDropdownOpen && (
                   <div className="absolute right-0 mt-2 w-32 bg-white dark:bg-dark-card border border-gray-200 dark:border-slate-700 rounded-lg shadow-xl py-1 z-50">
                       {(['lastPrice', 'markPrice', 'indexPrice'] as PriceSourceKey[]).map(key => (
                           <button
                              key={key}
                              onClick={() => {
                                setPriceSourceKey(key);
                                setIsDropdownOpen(false);
                              }}
                              className={`block w-full text-left px-4 py-2 text-xs font-medium hover:bg-gray-100 dark:hover:bg-slate-800 ${
                                  priceSourceKey === key ? 'text-brand-500' : 'text-slate-700 dark:text-slate-300'
                              }`}
                           >
                               {t[key]}
                           </button>
                       ))}
                   </div>
                 )}
             </div>
         </div>
      </div>

      <div className="flex-1 w-full relative overflow-hidden">
        <ResponsiveContainer width="100%" height="100%">
          {chartType === 'line' ? (
              <AreaChart data={displayData} margin={{ top: 10, right: 0, left: 0, bottom: 0 }}>
                <defs>
                  <linearGradient id="colorPrice" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="5%" stopColor="#EAB308" stopOpacity={0.3}/>
                    <stop offset="95%" stopColor="#EAB308" stopOpacity={0}/>
                  </linearGradient>
                </defs>
                <CartesianGrid strokeDasharray="3 3" stroke="#334155" opacity={0.1} vertical={false} />
                <XAxis dataKey="time" hide />
                <YAxis orientation="right" domain={['auto', 'auto']} tick={{fill: '#94a3b8', fontSize: 10}} axisLine={false} tickLine={false} width={50} />
                <Tooltip 
                  contentStyle={{ backgroundColor: '#1E293B', borderColor: '#334155', color: '#f1f5f9' }}
                  itemStyle={{ color: '#EAB308' }}
                  formatter={(value: number) => [value.toFixed(2), t[priceSourceKey]]}
                  labelFormatter={() => ''}
                />
                <Area type="monotone" dataKey="displayPrice" stroke="#EAB308" strokeWidth={2} fillOpacity={1} fill="url(#colorPrice)" isAnimationActive={false} />
              </AreaChart>
          ) : chartType === 'candle' ? (
              <BarChart data={displayData} margin={{ top: 10, right: 0, left: 0, bottom: 0 }}>
                 <CartesianGrid strokeDasharray="3 3" stroke="#334155" opacity={0.1} vertical={false} />
                 <XAxis dataKey="time" hide />
                 <YAxis orientation="right" domain={['dataMin - 5', 'dataMax + 5']} tick={{fill: '#94a3b8', fontSize: 10}} axisLine={false} tickLine={false} width={50} />
                 <Tooltip cursor={{fill: 'rgba(255,255,255,0.05)'}} content={<CustomTooltip />} />
                 <Bar dataKey="body" shape={<CandleStickShape />} isAnimationActive={false} />
              </BarChart>
          ) : (
              <AreaChart data={displayData} margin={{ top: 10, right: 0, left: 0, bottom: 0 }}>
                 <CartesianGrid strokeDasharray="3 3" stroke="#334155" opacity={0.1} vertical={false} />
                 <XAxis dataKey="price" type="number" domain={['auto', 'auto']} tick={{fill: '#94a3b8', fontSize: 10}} axisLine={false} tickLine={false} tickCount={6} />
                 <YAxis orientation="right" tick={{fill: '#94a3b8', fontSize: 10}} axisLine={false} tickLine={false} width={50} />
                 <Tooltip contentStyle={{ backgroundColor: '#1E293B', borderColor: '#334155', color: '#f1f5f9' }} />
                 <Area type="step" dataKey="bidTotal" stroke="#10B981" fill="#10B981" fillOpacity={0.3} strokeWidth={2} name="Bid Depth" isAnimationActive={false} />
                 <Area type="step" dataKey="askTotal" stroke="#F43F5E" fill="#F43F5E" fillOpacity={0.3} strokeWidth={2} name="Ask Depth" isAnimationActive={false} />
              </AreaChart>
          )}
        </ResponsiveContainer>
      </div>

      <div className="absolute top-1/2 left-1/2 transform -translate-x-1/2 -translate-y-1/2 pointer-events-none opacity-[0.03] select-none">
         <div className="text-8xl font-black text-slate-900 dark:text-white uppercase">{currentMarket.symbol.replace('USDC', '')}</div>
      </div>
    </div>
  );
};

const CustomTooltip = ({ active, payload }: any) => {
   if (active && payload && payload.length) {
       const d = payload[0].payload;
       return (
           <div className="bg-dark-card border border-dark-border p-2 rounded shadow-lg text-[10px] font-mono">
               <div className="grid grid-cols-2 gap-x-4 gap-y-0.5">
                   <span className="text-gray-400">O:</span> <span className="text-slate-200">{d.open.toFixed(2)}</span>
                   <span className="text-gray-400">H:</span> <span className="text-slate-200">{d.high.toFixed(2)}</span>
                   <span className="text-gray-400">L:</span> <span className="text-slate-200">{d.low.toFixed(2)}</span>
                   <span className="text-gray-400">C:</span> <span className={d.open <= d.close ? 'text-trade-up' : 'text-trade-down'}>{d.close.toFixed(2)}</span>
               </div>
           </div>
       );
   }
   return null;
};

export type Language = 'en' | 'zh-CN' | 'zh-TW';

export type Theme = 'light' | 'dark';

export enum OrderSide {
  BUY = 'BUY',
  SELL = 'SELL',
}

export enum OrderType {
  MARKET = 'MARKET',
  LIMIT = 'LIMIT',
}

export enum MarginMode {
  CROSS = 'CROSS',
  ISOLATED = 'ISOLATED',
}

export interface Position {
  id: string;
  symbol: string;
  side: OrderSide;
  size: number;
  entryPrice: number;
  markPrice: number;
  leverage: number;
  margin: number;
  marginMode: MarginMode;
  pnl: number;
  pnlPercent: number;
  liquidationPrice: number;
}

export interface Order {
  id: string;
  symbol: string;
  side: OrderSide;
  type: OrderType;
  price: number;
  amount: number;
  filled: number;
  leverage: number;
  status: 'OPEN' | 'FILLED' | 'CANCELED';
  time: string;
}

export interface MarketData {
  symbol: string;
  lastPrice: number;
  markPrice: number;
  indexPrice: number;
  change24h: number;
  change24hPercent: number;
  high24h: number;
  low24h: number;
  volume24h: number; // In XAU
  turnover24h: number; // In USDC
  openInterest: number; // In USDC
  fundingRate: number;
  nextFundingTime: number; // timestamp
}

export interface Notification {
  id: string;
  type: 'success' | 'error' | 'info';
  message: string;
}

export type WalletProvider = 'WalletConnect' | 'Metamask' | 'OKX Wallet' | 'Binance Wallet';

export interface AccountInfo {
  totalValue: number;
  unrealizedPnl: number;
  marginRatio: number;
  maintenanceMargin: number;
  marginBalance: number;
  walletBalance: number;
}

import React, { useState, useEffect } from 'react';
import { Position, Order, Language, MarginMode, OrderType, Theme, OrderSide } from '../types';
import { TRANSLATIONS, INITIAL_MARKET_DATA, MOCK_FUNDING_RECORDS, MOCK_HISTORY_ORDERS, MOCK_TRADE_HISTORY } from '../constants';
import { Edit3, Trash2, X, ChevronDown, Repeat, Filter, PlusCircle, MinusCircle, Info } from 'lucide-react';
import { CustomSlider } from './TradeForm';

interface PositionTableProps {
  positions: Position[];
  orders: Order[];
  assetHistory: any[];
  lang: Language;
  theme: Theme;
  onClosePosition: (id: string, type: OrderType, price?: number, amount?: number) => void;
  onCancelOrder: (id: string) => void;
  onEditMargin: (position: Position, type: 'add' | 'extract') => void;
  onCloseAll: () => void;
  onCancelAll: () => void;
}

const ThWithTooltip: React.FC<{ label: string; explanation?: string; align?: 'left' | 'right' }> = ({ label, explanation, align = 'left' }) => {
  const [showTooltip, setShowTooltip] = useState(false);
  return (
    <th className={`py-2 px-4 font-semibold text-gray-500 uppercase relative ${align === 'right' ? 'text-right' : 'text-left'}`}>
      <div 
        className={`inline-flex items-center space-x-1 cursor-help border-b border-dashed border-gray-300 dark:border-slate-700 transition-colors hover:border-brand-500 ${align === 'right' ? 'justify-end' : ''}`}
        onMouseEnter={() => setShowTooltip(true)}
        onMouseLeave={() => setShowTooltip(false)}
      >
        <span>{label}</span>
      </div>
      {showTooltip && explanation && (
        <div className={`absolute top-full mb-2 ${align === 'right' ? 'right-0' : 'left-0'} z-[2000] w-64 p-3 bg-white dark:bg-slate-800 border border-gray-200 dark:border-slate-700 rounded-lg shadow-2xl text-xs text-gray-600 dark:text-gray-300 leading-relaxed normal-case animate-in fade-in zoom-in-95 duration-100 ring-1 ring-black/5`}>
          <div className="font-bold text-slate-900 dark:text-white mb-1 flex items-center space-x-1">
            <Info size={12} className="text-brand-500" />
            <span>{label}</span>
          </div>
          {explanation}
        </div>
      )}
    </th>
  );
};

export const PositionTable: React.FC<PositionTableProps> = ({ positions, orders, assetHistory, lang, theme, onClosePosition, onCancelOrder, onEditMargin, onCloseAll, onCancelAll }) => {
  const t = TRANSLATIONS[lang];
  const [activeTab, setActiveTab] = useState<'positions' | 'openOrders' | 'orderHistory' | 'tradeHistory' | 'assetsHistory' | 'fundingHistory'>('positions');
  const [closingPos, setClosingPos] = useState<Position | null>(null);
  const [fundingFilter, setFundingFilter] = useState('all');
  const [showCloseAllModal, setShowCloseAllModal] = useState(false);

  // Dynamic Recent Trades for History
  const [allTrades, setAllTrades] = useState<any[]>([]);

  useEffect(() => {
    setAllTrades(MOCK_TRADE_HISTORY);
  }, []);

  const getTabLabel = (tabId: string) => {
    const label = (t as any)[tabId] || tabId;
    if (tabId === 'positions') return `${label}(${positions.length})`;
    if (tabId === 'openOrders') return `${label}(${orders.length})`;
    return label;
  };

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'completed': return 'text-teal-500 bg-teal-500/10';
      case 'processing': case 'confirming': case 'reviewing': return 'text-amber-500 bg-amber-500/10';
      case 'rejected': case 'failed': return 'text-rose-500 bg-rose-500/10';
      case 'canceled': return 'text-gray-400 bg-gray-100 dark:bg-slate-800';
      case 'filledOrder': return 'text-brand-500 bg-brand-500/10';
      default: return 'text-gray-500 bg-gray-500/10';
    }
  };

  const CloseModal = ({ pos, onClose }: { pos: Position, onClose: () => void }) => {
    const [closeType, setCloseType] = useState<OrderType>(OrderType.MARKET);
    const [closePrice, setClosePrice] = useState<string>(INITIAL_MARKET_DATA.lastPrice.toFixed(2));
    const [closeAmount, setCloseAmount] = useState<string>(pos.size.toString());
    const [unit, setUnit] = useState<'XAU' | 'USDC'>('XAU');
    const [sliderVal, setSliderVal] = useState(100);

    const handleConfirm = () => { 
      const amountNum = parseFloat(closeAmount) || 0;
      const xauAmount = unit === 'XAU' ? amountNum : amountNum / (parseFloat(closePrice) || pos.markPrice);
      onClosePosition(pos.id, closeType, parseFloat(closePrice), xauAmount); 
      onClose(); 
    };

    const handleSlider = (val: number) => { 
      setSliderVal(val);
      const targetXAU = pos.size * (val / 100);
      if (unit === 'XAU') {
        setCloseAmount(targetXAU.toFixed(4));
      } else {
        setCloseAmount((targetXAU * (parseFloat(closePrice) || pos.markPrice)).toFixed(2));
      }
    };

    const amountNum = parseFloat(closeAmount) || 0;
    const estXAU = unit === 'XAU' ? amountNum : amountNum / (parseFloat(closePrice) || pos.markPrice);
    const estPnl = estXAU * ((closeType === OrderType.MARKET ? pos.markPrice : parseFloat(closePrice) || pos.markPrice) - pos.entryPrice);

    return (
      <div className="fixed inset-0 z-[200] flex items-center justify-center bg-black/70 backdrop-blur-sm p-4">
        <div className="w-full max-w-[420px] bg-white dark:bg-[#1a1c22] border border-gray-200 dark:border-slate-800 rounded-lg shadow-2xl overflow-hidden animate-in fade-in zoom-in duration-200">
          <div className="flex items-center justify-between px-6 py-4 border-b border-gray-100 dark:border-slate-800">
            <h3 className="text-lg font-bold dark:text-white">{t.closePos}</h3>
            <button onClick={onClose} className="text-gray-400 hover:text-white transition"><X size={20} /></button>
          </div>
          <div className="p-6 space-y-4">
            <div className="flex flex-col space-y-1">
              <div className="flex justify-between text-sm">
                <span className="text-gray-500">{t.tradingPair}</span>
                <span className="font-bold text-teal-600 font-mono">{pos.symbol} / {pos.side === 'BUY' ? t.long : t.short}</span>
              </div>
              <div className="flex justify-between text-[11px] text-gray-500">
                <span>{t.entryPrice}: <span className="font-mono">{pos.entryPrice.toFixed(2)}</span></span>
                <span>{t.markPrice}: <span className="font-mono">{pos.markPrice.toFixed(2)}</span></span>
              </div>
            </div>

            <div className="grid grid-cols-2 gap-4">
              <div className="space-y-1.5">
                <label className="text-xs text-gray-500">{t.closePrice}</label>
                <input type="number" disabled={closeType === OrderType.MARKET} value={closeType === OrderType.MARKET ? "" : closePrice} onChange={e => setClosePrice(e.target.value)} placeholder={closeType === OrderType.MARKET ? t.market : ""} className="w-full bg-gray-100 dark:bg-slate-800 border border-gray-200 dark:border-slate-700 rounded p-2 text-sm font-mono outline-none dark:text-white" />
              </div>
              <div className="space-y-1.5">
                <label className="text-xs text-gray-500">Mode</label>
                <div onClick={() => setCloseType(prev => prev === OrderType.MARKET ? OrderType.LIMIT : OrderType.MARKET)} className="flex items-center justify-between bg-gray-100 dark:bg-slate-800 border border-gray-200 dark:border-slate-700 rounded p-2 text-sm cursor-pointer dark:text-white">
                  <span className="font-mono">{closeType === OrderType.MARKET ? t.market : t.limit}</span>
                  <Repeat size={14} className="text-gray-500" />
                </div>
              </div>
            </div>

            <div className="space-y-1.5">
              <label className="text-xs text-gray-500">{t.closeAmount}</label>
              <div className="relative">
                <input type="number" value={closeAmount} onChange={e => setCloseAmount(e.target.value)} className="w-full bg-gray-100 dark:bg-slate-800 border border-gray-200 dark:border-slate-700 rounded p-2 pr-16 text-sm font-mono outline-none dark:text-white" />
                <button 
                  onClick={() => setUnit(u => u === 'XAU' ? 'USDC' : 'XAU')}
                  className="absolute right-2 top-1.5 bg-gray-200 dark:bg-slate-700 px-2 py-1 rounded text-[10px] font-bold text-gray-500 flex items-center space-x-1"
                >
                  <span>{unit}</span><Repeat size={8} />
                </button>
              </div>
            </div>

            <div className="pt-2"><CustomSlider value={sliderVal} onChange={handleSlider} theme={theme} /></div>

            <div className="space-y-1 pt-2 border-t border-gray-100 dark:border-slate-800">
              <div className="flex justify-between text-xs text-gray-500"><span>{t.heldAmount}</span><span className="font-mono dark:text-white">{pos.size} XAU</span></div>
              <div className="flex justify-between text-xs text-gray-500 font-bold"><span>{t.estPnl}</span><span className={`font-mono ${estPnl >= 0 ? 'text-teal-600' : 'text-trade-down'}`}>{estPnl.toFixed(2)} USDC</span></div>
            </div>

            <div className="grid grid-cols-2 gap-4 pt-4">
              <button onClick={onClose} className="py-2.5 border border-[#dca85e] text-[#dca85e] rounded font-bold hover:bg-[#dca85e]/5 transition">{t.cancel}</button>
              <button onClick={handleConfirm} className="py-2.5 bg-[#dca85e] text-slate-900 rounded font-bold shadow-lg shadow-[#dca85e]/20 hover:bg-[#c99750] transition">{t.confirm}</button>
            </div>
          </div>
        </div>
      </div>
    );
  };

  const filteredFunding = MOCK_FUNDING_RECORDS.filter(r => fundingFilter === 'all' || r.type === fundingFilter);

  return (
    <div className="flex flex-col h-full bg-white dark:bg-dark-card border-t border-gray-200 dark:border-dark-border overflow-hidden">
      {/* 选项卡头部 - 固定不滚动 */}
      <div className="flex items-center px-4 border-b border-gray-200 dark:border-dark-border shrink-0 bg-white dark:bg-dark-card z-30 overflow-x-auto hide-scrollbar">
        {['positions', 'openOrders', 'orderHistory', 'tradeHistory', 'assetsHistory', 'fundingHistory'].map(tabId => (
          <button 
            key={tabId} 
            onClick={() => setActiveTab(tabId as any)} 
            className={`py-3 px-3 text-sm font-medium border-b-2 transition-all whitespace-nowrap ${activeTab === tabId ? 'border-brand-500 text-brand-500' : 'border-transparent text-gray-500 hover:text-slate-900 dark:hover:text-white'}`}
          >
            {getTabLabel(tabId)}
          </button>
        ))}
        {activeTab === 'positions' && positions.length > 0 && (
          <button 
            onClick={() => setShowCloseAllModal(true)}
            className="ml-auto bg-trade-down/10 text-trade-down border border-trade-down/30 px-3 py-1 rounded text-xs font-bold hover:bg-trade-down hover:text-white transition"
          >
            {t.closeAll}
          </button>
        )}
        {activeTab === 'openOrders' && orders.length > 0 && (
          <button 
            onClick={() => onCancelAll()}
            className="ml-auto bg-slate-100 dark:bg-slate-800 text-gray-500 px-3 py-1 rounded text-xs font-bold hover:bg-slate-200 dark:hover:bg-slate-700 transition"
          >
            {t.cancelAll}
          </button>
        )}
      </div>

      {/* 数据内容滚动区 */}
      <div className="flex-1 overflow-auto relative scroll-smooth custom-scrollbar">
        {activeTab === 'positions' ? (
          <table className="w-full text-left text-xs border-collapse min-w-[1000px]">
            <thead className="sticky top-0 bg-white dark:bg-dark-card z-20 shadow-sm border-b border-gray-200 dark:border-slate-800">
              <tr className="text-gray-500 uppercase bg-gray-50/80 dark:bg-slate-900/80 backdrop-blur-sm">
                <th className="py-2 px-4 font-semibold">{t.symbol}</th>
                <ThWithTooltip label={t.nominalValue} explanation={t.explanations.nominalValue} />
                <ThWithTooltip label={t.entryPrice} explanation={t.explanations.entryPrice} />
                <ThWithTooltip label={t.markPrice} explanation={t.explanations.markPrice} />
                <ThWithTooltip label={t.liqPrice} explanation={t.explanations.liqPrice} />
                <ThWithTooltip label={t.margin} explanation={t.explanations.margin} />
                <ThWithTooltip label={t.unrealizedPnl} explanation={t.explanations.unrealizedPnl} align="right" />
                <th className="py-2 px-4 font-semibold text-right">{t.action}</th>
              </tr>
            </thead>
            <tbody>
              {positions.map(pos => (
                <tr key={pos.id} className="border-b border-gray-100 dark:border-slate-800/30 hover:bg-gray-50 dark:hover:bg-slate-800/20">
                  <td className="py-3 px-4">
                    <div className="flex flex-col">
                      <span className="font-bold text-slate-900 dark:text-white font-mono text-sm">{pos.symbol}</span>
                      <div className="flex items-center space-x-2">
                        <span className={`font-bold ${pos.side === 'BUY' ? 'text-trade-up' : 'text-trade-down'}`}>{pos.side === 'BUY' ? t.long : t.short}</span>
                        <span className="text-[10px] text-gray-500 font-bold bg-gray-100 dark:bg-slate-800 px-1 rounded">{pos.leverage}x</span>
                      </div>
                    </div>
                  </td>
                  <td className="py-3 px-4">
                    <div className="flex flex-col font-mono">
                      <span className="dark:text-white">{pos.size.toFixed(4)} XAU</span>
                      <span className="text-[10px] text-gray-500">{(pos.size * pos.markPrice).toFixed(2)} USDC</span>
                    </div>
                  </td>
                  <td className="py-3 px-4 font-mono dark:text-white">{pos.entryPrice.toFixed(2)}</td>
                  <td className="py-3 px-4 font-mono text-slate-400">{pos.markPrice.toFixed(2)}</td>
                  <td className="py-3 px-4 text-orange-500 font-mono font-bold">{pos.liquidationPrice.toFixed(2)}</td>
                  <td className="py-3 px-4 font-mono dark:text-white">
                    <div className="flex flex-col leading-none">
                      <div className="flex items-center space-x-2">
                        <span>{pos.margin.toFixed(2)}</span>
                        {pos.marginMode === MarginMode.ISOLATED && (
                          <div className="flex items-center space-x-1">
                            <button onClick={() => onEditMargin(pos, 'add')} className="text-teal-500 hover:text-teal-400"><PlusCircle size={14} /></button>
                            <button onClick={() => onEditMargin(pos, 'extract')} className="text-rose-500 hover:text-rose-400"><MinusCircle size={14} /></button>
                          </div>
                        )}
                      </div>
                      <span className="text-[9px] text-gray-500 uppercase mt-0.5">{pos.marginMode === MarginMode.CROSS ? t.cross : t.isolated}</span>
                    </div>
                  </td>
                  <td className={`py-3 px-4 text-right font-mono ${pos.pnl >= 0 ? 'text-trade-up' : 'text-trade-down'}`}>
                    <div>{pos.pnl >= 0 ? '+' : ''}{pos.pnl.toFixed(2)}</div>
                    <div className="text-[10px] opacity-70">{pos.pnlPercent.toFixed(2)}%</div>
                  </td>
                  <td className="py-3 px-4 text-right">
                    <button onClick={() => setClosingPos(pos)} className="px-3 py-1.5 bg-slate-100 dark:bg-slate-800 border border-gray-200 dark:border-slate-700 hover:bg-brand-500 dark:text-white rounded-md font-bold transition-all shadow-sm">{t.marketLimitClose}</button>
                  </td>
                </tr>
              ))}
              {positions.length === 0 && (
                <tr>
                  <td colSpan={8} className="py-10 text-center text-gray-400 italic">No open positions</td>
                </tr>
              )}
            </tbody>
          </table>
        ) : activeTab === 'openOrders' ? (
          <table className="w-full text-left text-xs border-collapse min-w-[900px]">
            <thead className="sticky top-0 bg-white dark:bg-dark-card z-20 shadow-sm border-b border-gray-200 dark:border-slate-800">
               <tr className="text-gray-500 uppercase bg-gray-50/80 dark:bg-slate-900/80 backdrop-blur-sm">
                 <th className="py-2 px-4">{t.symbol}</th>
                 <th className="py-2 px-4">{t.type}</th>
                 <th className="py-2 px-4">{t.price}</th>
                 <th className="py-2 px-4">{t.filled}</th>
                 <th className="py-2 px-4">{t.totalOrder}</th>
                 <th className="py-2 px-4">{t.fillRate}</th>
                 <th className="py-2 px-4">{t.leverage}</th>
                 <th className="py-2 px-4">{t.time}</th>
                 <th className="py-2 px-4 text-right">{t.action}</th>
               </tr>
            </thead>
            <tbody>
              {orders.map(o => (
                <tr key={o.id} className="border-b border-gray-100 dark:border-slate-800/30 hover:bg-gray-50 dark:hover:bg-slate-800/20">
                  <td className="py-3 px-4 font-bold text-slate-900 dark:text-white">{o.symbol} / <span className={o.side === 'BUY' ? 'text-trade-up' : 'text-trade-down'}>{o.side === 'BUY' ? t.buySide : t.sellSide}</span></td>
                  <td className="py-3 px-4 text-gray-500">{o.type === 'LIMIT' ? t.limit : t.market}</td>
                  <td className="py-3 px-4 font-mono dark:text-white">{o.price.toFixed(2)}</td>
                  <td className="py-3 px-4 font-mono dark:text-white">{o.filled.toFixed(4)}</td>
                  <td className="py-3 px-4 font-mono dark:text-white">{o.amount.toFixed(4)}</td>
                  <td className="py-3 px-4 font-mono dark:text-white">{((o.filled / o.amount) * 100).toFixed(2)}%</td>
                  <td className="py-3 px-4 font-mono text-gray-500 font-bold">{o.leverage}x</td>
                  <td className="py-3 px-4 text-gray-500">{o.time}</td>
                  <td className="py-3 px-4 text-right"><button onClick={() => onCancelOrder(o.id)} className="text-trade-down hover:underline font-bold">{t.cancelOrder}</button></td>
                </tr>
              ))}
              {orders.length === 0 && <tr><td colSpan={9} className="py-10 text-center text-gray-400 italic">No open orders</td></tr>}
            </tbody>
          </table>
        ) : activeTab === 'orderHistory' ? (
          <table className="w-full text-left text-xs border-collapse min-w-[900px]">
            <thead className="sticky top-0 bg-white dark:bg-dark-card z-20 shadow-sm border-b border-gray-200 dark:border-slate-800">
               <tr className="text-gray-500 uppercase bg-gray-50/80 dark:bg-slate-900/80 backdrop-blur-sm">
                 <th className="py-2 px-4">{t.symbol}</th>
                 <th className="py-2 px-4">{t.type}</th>
                 <th className="py-2 px-4">{t.price}</th>
                 <th className="py-2 px-4">{t.filled}</th>
                 <th className="py-2 px-4">{t.totalOrder}</th>
                 <th className="py-2 px-4">{t.leverage}</th>
                 <th className="py-2 px-4">{t.status}</th>
                 <th className="py-2 px-4">{t.time}</th>
               </tr>
            </thead>
            <tbody>
              {MOCK_HISTORY_ORDERS.map(o => (
                <tr key={o.id} className="border-b border-gray-100 dark:border-slate-800/30 hover:bg-gray-50 dark:hover:bg-slate-800/20">
                  <td className="py-3 px-4 font-bold text-slate-900 dark:text-white">{o.symbol} / <span className={o.side === 'BUY' ? 'text-trade-up' : 'text-trade-down'}>{o.side === 'BUY' ? t.buySide : t.sellSide}</span></td>
                  <td className="py-3 px-4 text-gray-500">{o.type === 'LIMIT' ? t.limit : t.market}</td>
                  <td className="py-3 px-4 font-mono dark:text-white">{o.price.toFixed(2)}</td>
                  <td className="py-3 px-4 font-mono dark:text-white">{o.filled.toFixed(4)}</td>
                  <td className="py-3 px-4 font-mono dark:text-white">{o.total.toFixed(4)}</td>
                  <td className="py-3 px-4 font-mono text-gray-500 font-bold">{o.leverage}x</td>
                  <td className="py-3 px-4"><span className={`px-2 py-0.5 rounded text-[10px] font-bold ${getStatusColor(o.status)}`}>{(t as any)[o.status] || o.status}</span></td>
                  <td className="py-3 px-4 text-gray-500">{o.time}</td>
                </tr>
              ))}
            </tbody>
          </table>
        ) : activeTab === 'tradeHistory' ? (
          <table className="w-full text-left text-xs border-collapse min-w-[900px]">
            <thead className="sticky top-0 bg-white dark:bg-dark-card z-20 shadow-sm border-b border-gray-200 dark:border-slate-800">
               <tr className="text-gray-500 uppercase bg-gray-50/80 dark:bg-slate-900/80 backdrop-blur-sm">
                 <th className="py-2 px-4">{t.symbol}</th>
                 <th className="py-2 px-4">{t.price}</th>
                 <th className="py-2 px-4">{t.amount}</th>
                 <th className="py-2 px-4">{t.total}</th>
                 <th className="py-2 px-4">{t.fee}</th>
                 <th className="py-2 px-4">{t.realizedPnl}</th>
                 <th className="py-2 px-4">{t.time}</th>
               </tr>
            </thead>
            <tbody>
              {allTrades.map(t2 => (
                <tr key={t2.id} className="border-b border-gray-100 dark:border-slate-800/30 hover:bg-gray-50 dark:hover:bg-slate-800/20">
                  <td className="py-3 px-4 font-bold text-slate-900 dark:text-white">{t2.symbol} / <span className={t2.side === 'BUY' ? 'text-trade-up' : 'text-trade-down'}>{t2.side === 'BUY' ? t.buySide : t.sellSide}</span></td>
                  <td className="py-3 px-4 font-mono dark:text-white">{t2.price.toFixed(2)}</td>
                  <td className="py-3 px-4 font-mono dark:text-white">{t2.amount.toFixed(4)}</td>
                  <td className="py-3 px-4 font-mono dark:text-white">{t2.total.toFixed(2)}</td>
                  <td className="py-3 px-4 font-mono text-rose-500">{t2.fee.toFixed(2)}</td>
                  <td className={`py-3 px-4 font-mono font-bold ${t2.pnl >= 0 ? 'text-teal-500' : 'text-rose-500'}`}>{t2.pnl >= 0 ? '+' : ''}{t2.pnl.toFixed(2)}</td>
                  <td className="py-3 px-4 text-gray-500">{t2.time}</td>
                </tr>
              ))}
            </tbody>
          </table>
        ) : activeTab === 'assetsHistory' ? (
          <table className="w-full text-left text-xs border-collapse min-w-[900px]">
            <thead className="sticky top-0 bg-white dark:bg-dark-card z-20 shadow-sm border-b border-gray-200 dark:border-slate-800">
               <tr className="text-gray-500 uppercase bg-gray-50/80 dark:bg-slate-900/80 backdrop-blur-sm">
                 <th className="py-2 px-4">{t.assetHeader}</th>
                 <th className="py-2 px-4">{t.type}</th>
                 <th className="py-2 px-4">{t.amount}</th>
                 <th className="py-2 px-4">{t.fee}</th>
                 <th className="py-2 px-4">{t.txHash}</th>
                 <th className="py-2 px-4">{t.status}</th>
                 <th className="py-2 px-4">{t.time}</th>
               </tr>
            </thead>
            <tbody>
              {assetHistory.map(a => (
                <tr key={a.id} className="border-b border-gray-100 dark:border-slate-800/30 hover:bg-gray-50 dark:hover:bg-slate-800/20">
                  <td className="py-3 px-4 dark:text-white">{a.asset}</td>
                  <td className="py-3 px-4 text-gray-500">{(t as any)[a.type] || a.type}</td>
                  <td className={`py-3 px-4 font-mono font-bold ${a.type === 'deposit' ? 'text-teal-500' : 'text-rose-500'}`}>{a.amount.toLocaleString()}</td>
                  <td className="py-3 px-4 text-rose-500 font-mono">{a.fee ? a.fee.toFixed(2) : '--'}</td>
                  <td className="py-3 px-4 font-mono text-brand-500 cursor-pointer hover:underline">{a.hash}</td>
                  <td className="py-3 px-4"><span className={`px-2 py-0.5 rounded text-[10px] font-bold ${getStatusColor(a.status)}`}>{(t as any)[a.status] || a.status}</span></td>
                  <td className="py-3 px-4 text-gray-500">{a.time}</td>
                </tr>
              ))}
            </tbody>
          </table>
        ) : activeTab === 'fundingHistory' ? (
          <div className="flex flex-col min-h-full min-w-[700px]">
            {/* 资金记录专用的 Sticky 头部 */}
            <div className="sticky top-0 bg-white dark:bg-dark-card z-20 shadow-sm border-b border-gray-200 dark:border-slate-800">
              <div className="p-3 flex items-center bg-gray-50/50 dark:bg-slate-900/50">
                <div className="relative group">
                  <button className="flex items-center space-x-2 bg-white dark:bg-slate-800 border border-gray-200 dark:border-slate-700 px-3 py-1 rounded text-xs transition hover:border-brand-500">
                    <Filter size={14} className="text-gray-400" />
                    <span>{(t as any)[fundingFilter] || t.all}</span>
                    <ChevronDown size={14} />
                  </button>
                  <div className="absolute left-0 mt-1 w-40 bg-white dark:bg-slate-800 border border-gray-200 dark:border-slate-700 rounded-lg shadow-xl z-40 hidden group-hover:block py-1">
                    {['all', 'tradingFee', 'fundingFee', 'realizedPnl', 'liquidationFee'].map(f => (
                      <button key={f} onClick={() => setFundingFilter(f)} className="w-full text-left px-4 py-2 text-xs hover:bg-gray-100 dark:hover:bg-slate-700 dark:text-white">{(t as any)[f] || t.all}</button>
                    ))}
                  </div>
                </div>
              </div>
              <table className="w-full text-left text-xs border-collapse">
                <thead className="bg-gray-100/80 dark:bg-slate-900/80 backdrop-blur-sm">
                  <tr className="text-gray-500 uppercase border-b border-gray-200 dark:border-slate-800">
                    <th className="py-2 px-4 w-1/4">{t.time}</th>
                    <th className="py-2 px-4 w-1/4">{t.type}</th>
                    <th className="py-2 px-4 w-1/4">{t.amount} (USDC)</th>
                    <th className="py-2 px-4 w-1/4">{t.contract}</th>
                  </tr>
                </thead>
              </table>
            </div>
            {/* 数据行 */}
            <table className="w-full text-left text-xs border-collapse">
              <tbody>
                {filteredFunding.map(r => (
                  <tr key={r.id} className="border-b border-gray-100 dark:border-slate-800/30 hover:bg-gray-50 dark:hover:bg-slate-800/20">
                    <td className="py-3 px-4 w-1/4 text-gray-500">{r.time}</td>
                    <td className="py-3 px-4 w-1/4 dark:text-white">{(t as any)[r.type] || r.type}</td>
                    <td className={`py-3 px-4 w-1/4 font-mono font-bold ${r.amount >= 0 ? 'text-teal-500' : 'text-rose-500'}`}>{r.amount >= 0 ? '+' : ''}{r.amount.toFixed(2)}</td>
                    <td className="py-3 px-4 w-1/4 text-gray-400">{r.symbol}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        ) : null}
      </div>

      {showCloseAllModal && (
        <div className="fixed inset-0 z-[300] flex items-center justify-center bg-black/60 backdrop-blur-sm">
           <div className="bg-white dark:bg-dark-card border border-gray-200 dark:border-slate-800 p-6 rounded-xl shadow-2xl max-w-sm w-full">
              <h3 className="text-lg font-bold mb-4 dark:text-white">{t.closeAll}?</h3>
              <p className="text-sm text-gray-500 mb-6">{t.closeAllConfirm}</p>
              <div className="flex space-x-4">
                 <button onClick={() => setShowCloseAllModal(false)} className="flex-1 py-2 border border-gray-300 dark:border-slate-700 rounded font-bold text-gray-500">{t.cancel}</button>
                 <button onClick={() => { onCloseAll(); setShowCloseAllModal(false); }} className="flex-1 py-2 bg-trade-down text-white rounded font-bold">{t.confirm}</button>
              </div>
           </div>
        </div>
      )}

      {closingPos && <CloseModal pos={closingPos} onClose={() => setClosingPos(null)} />}
    </div>
  );
};

import React, { useState } from 'react';
import { Header } from './components/Header';
import { MarketStats } from './components/MarketStats';
import { CandleChart } from './components/CandleChart';
import { OrderBook } from './components/OrderBook';
import { TradeForm } from './components/TradeForm';
import { PositionTable } from './components/PositionTable';
import { AccountInfo } from './components/AccountInfo';
import { NotificationContainer, RichNotification } from './components/Notification';
import { WalletModal, AssetModal, MarginManageModal, SignatureModal, SettingsModal, EmailModal } from './components/Modals';
import { INITIAL_MARKET_DATA, MOCK_POSITIONS, TRANSLATIONS, INITIAL_ACCOUNT_INFO, MOCK_ASSETS_HISTORY } from './constants';
import { Language, Theme, MarketData, Position, Order, OrderSide, OrderType, MarginMode, AccountInfo as AccountInfoType } from './types';

export default function App() {
  const [lang, setLang] = useState<Language>('zh-CN');
  const [theme, setTheme] = useState<Theme>('dark');
  const [isConnected, setIsConnected] = useState(false);
  const [isSigned, setIsSigned] = useState(false);
  const [isEmailBound, setIsEmailBound] = useState(false);
  const [marketData, setMarketData] = useState<MarketData>(INITIAL_MARKET_DATA);
  const [positions, setPositions] = useState<Position[]>(MOCK_POSITIONS);
  const [orders, setOrders] = useState<Order[]>([]);
  const [assetHistory, setAssetHistory] = useState(MOCK_ASSETS_HISTORY);
  const [notifications, setNotifications] = useState<RichNotification[]>([]);
  const [accountInfo, setAccountInfo] = useState<AccountInfoType>(INITIAL_ACCOUNT_INFO);

  const [showWalletModal, setShowWalletModal] = useState(false);
  const [showSignModal, setShowSignModal] = useState(false);
  const [showSettingsModal, setShowSettingsModal] = useState(false);
  const [showEmailModal, setShowEmailModal] = useState(false);

  const [assetModal, setAssetModal] = useState<{ isOpen: boolean, type: 'deposit' | 'withdraw' }>({ isOpen: false, type: 'deposit' });
  const [marginManage, setMarginManage] = useState<{ isOpen: boolean; type: 'add' | 'extract'; pos: Position | null }>({ isOpen: false, type: 'add', pos: null });

  const addRichNotification = (type: RichNotification['type'], title: string, message: string) => {
    const id = Date.now().toString();
    setNotifications(prev => [...prev, { id, type, title, message }]);
  };

  const handleConnectClick = () => {
    setShowWalletModal(true);
  };

  const handleWalletSelect = () => {
    setShowWalletModal(false);
    setShowSignModal(true);
  };

  const handleSign = () => {
    setShowSignModal(false);
    setIsConnected(true);
    setIsSigned(true);
    const title = lang === 'en' ? 'Welcome Back' : (lang === 'zh-CN' ? '欢迎回来' : '歡迎回來');
    const body = lang === 'en' ? 'Wallet connected and signed successfully.' : '钱包连接并签名成功。';
    addRichNotification('success', title, body);
  };

  const handleOrder = (side: OrderSide, type: OrderType, size: number, price: number, leverage: number, marginMode: MarginMode) => {
    if (!isSigned) { setShowWalletModal(true); return; }

    if (type === OrderType.MARKET) {
      const newPos: Position = { id: Date.now().toString(), symbol: marketData.symbol, side, size, entryPrice: price, markPrice: price, leverage, margin: (size * price) / leverage, marginMode, pnl: 0, pnlPercent: 0, liquidationPrice: side === OrderSide.BUY ? price * 0.8 : price * 1.2 };
      setPositions(prev => [newPos, ...prev]);

      const title = lang === 'en' ? 'Market Order Filled' : (lang === 'zh-CN' ? '市价单已完全成交' : '市價單已完全成交');
      const body = lang === 'en' 
        ? `Market ${side === OrderSide.BUY ? 'Buy' : 'Sell'} ${size.toFixed(2)} XAU fully filled.\nAvg Price $${price.toFixed(2)} | Fee $${(size * price * 0.0005).toFixed(2)}`
        : `市价${side === OrderSide.BUY ? '买入' : '卖出'} ${size.toFixed(2)} ${marketData.symbol.replace('USDC', '')} 已完全成交\n平均成交价 $${price.toFixed(2)} | 手续费 $${(size * price * 0.0005).toFixed(2)}`;
      addRichNotification('success', title, body);
    } else {
      const newOrder: Order = {
        id: Date.now().toString(),
        symbol: marketData.symbol,
        side,
        type: OrderType.LIMIT,
        price,
        amount: size,
        filled: 0,
        leverage,
        status: 'OPEN',
        time: new Date().toLocaleString()
      };
      setOrders(prev => [newOrder, ...prev]);

      const title = lang === 'en' ? 'Order Created' : (lang === 'zh-CN' ? '下单成功' : '下單成功');
      const sideStr = lang === 'en' ? (side === OrderSide.BUY ? 'Buy' : 'Sell') : (side === OrderSide.BUY ? '买入' : '卖出');
      const body = lang === 'en'
        ? `You have successfully submitted ${marketData.symbol} ${sideStr} Limit Order.\nPrice $${price.toLocaleString()} | Amount ${size} XAU | Leverage ${leverage}x`
        : `您已成功提交${marketData.symbol} ${sideStr} 限价单\n价格 $${price.toLocaleString()} | 数量 ${size} ${marketData.symbol.replace('USDC', '')} | 杠杆 ${leverage}x`;
      addRichNotification('success', title, body);
    }
  };

  const handleClosePosition = (id: string, type: OrderType, closePrice?: number, closeAmount?: number) => {
    const pos = positions.find(p => p.id === id);
    if (!pos) return;

    setPositions(prev => prev.filter(x => x.id !== id));

    const title = lang === 'en' ? 'Position Closed' : (lang === 'zh-CN' ? '仓位已平仓' : '倉位已平倉');
    const sideStr = lang === 'en' ? (pos.side === OrderSide.BUY ? 'Long' : 'Short') : (pos.side === OrderSide.BUY ? '多头' : '空头');
    const body = lang === 'en'
      ? `Successfully closed ${pos.symbol} ${sideStr}.\nClosed Amount ${pos.size} XAU | Realized PnL +$${pos.pnl.toFixed(2)}`
      : `您已成功平仓 ${pos.symbol} ${sideStr}\n平仓数量 ${pos.size} ${pos.symbol.replace('USDC', '')} | 实现盈亏 +$${pos.pnl.toFixed(2)}`;
    addRichNotification('success', title, body);
  };

  const handleAssetConfirm = (type: 'deposit' | 'withdraw', v: number) => {
     const status = type === 'deposit' ? 'completed' : (v >= 100 ? 'reviewing' : 'completed');
     const newRecord = {
        id: Date.now().toString(),
        asset: 'USDC',
        type,
        amount: v,
        fee: type === 'withdraw' ? 0.5 : null,
        hash: '0x' + Math.random().toString(16).slice(2, 10) + '...',
        status,
        time: new Date().toISOString().replace('T', ' ').slice(0, 19)
     };
     setAssetHistory(prev => [newRecord, ...prev]);
     setAssetModal(m => ({ ...m, isOpen: false }));

     if (type === 'deposit') {
       const title = lang === 'en' ? 'Deposit Success' : (lang === 'zh-CN' ? '充值成功' : '充值成功');
       const body = lang === 'en' 
        ? `You have successfully deposited ${v.toLocaleString()} USDC, please check.`
        : `您已成功充值 ${v.toLocaleString()} USDC，请查看`;
       addRichNotification('success', title, body);
     } else {
       const title = lang === 'en' ? 'Withdrawal Success' : (lang === 'zh-CN' ? '提现成功' : '提現成功');
       const body = lang === 'en'
        ? `You have successfully withdrawn ${v.toLocaleString()} USDC to 0x4b...5591 (Arbitrum), estimated arrival in 1 minute.`
        : `您已成功提现 ${v.toLocaleString()} USDC 至 0x4b...5591 (Arbitrum)，预计 1 分钟到账。`;
       addRichNotification('success', title, body);
     }
  };

  const simulateLiquidation = () => {
    const title = lang === 'en' ? 'Position Liquidated' : (lang === 'zh-CN' ? '仓位已强平' : '倉位已強平');
    const body = lang === 'en'
      ? `Your ${marketData.symbol} Long position triggered liquidation at $2,800. $428 Liquidation fee deducted.`
      : `您的 ${marketData.symbol} 多头仓位已触发强平，强平价格 $2,800，已扣除 $428 强平罚金。`;
    addRichNotification('liquidation', title, body);
  };

  return (
    <div className={`flex flex-col h-screen ${theme} bg-gray-50 dark:bg-dark-bg text-slate-900 dark:text-slate-200 font-sans overflow-hidden transition-colors`}>
      <Header 
        lang={lang} setLang={setLang} theme={theme} setTheme={setTheme}
        isConnected={isSigned} 
        onConnectClick={handleConnectClick} 
        onDeposit={() => setAssetModal({ isOpen: true, type: 'deposit' })}
        onWithdraw={() => setAssetModal({ isOpen: true, type: 'withdraw' })}
        onDisconnect={() => { setIsConnected(false); setIsSigned(false); setPositions([]); setOrders([]); }}
      />
      <MarketStats data={marketData} lang={lang} onMarketSelect={setMarketData} />
      <main className="flex-1 flex overflow-hidden">
        <div className="flex-1 flex flex-col min-w-0">
          <div className="flex-[1.8] flex border-b border-gray-200 dark:border-dark-border">
            <div className="flex-1 relative border-r border-gray-200 dark:border-dark-border">
              <CandleChart lang={lang} currentMarket={marketData} />
              <button 
                onClick={simulateLiquidation}
                className="absolute bottom-4 left-4 bg-rose-600/20 hover:bg-rose-600/40 text-rose-500 text-[10px] px-2 py-1 rounded border border-rose-500/30 font-bold transition-all z-20"
              >
                Simulate Liq.
              </button>
            </div>
            <div className="w-[280px] hidden lg:block bg-white dark:bg-dark-card shrink-0"><OrderBook lang={lang} lastPrice={marketData.lastPrice} /></div>
          </div>
          <div className="flex-[2] min-h-[250px] flex flex-col overflow-hidden">
             <PositionTable 
               positions={positions} orders={orders} assetHistory={assetHistory} lang={lang} theme={theme}
               onClosePosition={handleClosePosition}
               onCancelOrder={(id) => setOrders(o => o.filter(x => x.id !== id))}
               onEditMargin={(pos, type) => setMarginManage({ isOpen: true, type, pos })}
               onCloseAll={() => setPositions([])}
               onCancelAll={() => setOrders([])}
             />
          </div>
        </div>
        <div className="w-[340px] flex flex-col border-l border-gray-200 dark:border-dark-border bg-white dark:bg-dark-card z-30 shrink-0">
          <div className="flex-1 overflow-y-auto">
            <TradeForm lang={lang} theme={theme} isConnected={isSigned} onConnect={() => setShowWalletModal(true)} onOrder={handleOrder} lastPrice={marketData.lastPrice} availableBalance={accountInfo.marginBalance} currentSymbol={marketData.symbol} />
          </div>
          <div className="shrink-0 border-t border-gray-200 dark:border-dark-border"><AccountInfo lang={lang} info={accountInfo} /></div>
        </div>
      </main>

      <NotificationContainer notifications={notifications} removeNotification={(id) => setNotifications(n => n.filter(x => x.id !== id))} />

      <WalletModal isOpen={showWalletModal} onClose={() => setShowWalletModal(false)} lang={lang} onConnect={handleWalletSelect} />
      <SignatureModal isOpen={showSignModal} onClose={() => setShowSignModal(false)} lang={lang} onSign={handleSign} />
      <SettingsModal isOpen={showSettingsModal} onClose={() => setShowSettingsModal(false)} lang={lang} isEmailBound={isEmailBound} onBindClick={() => setShowEmailModal(true)} />
      <EmailModal isOpen={showEmailModal} onClose={() => setShowEmailModal(false)} lang={lang} onBind={() => { setIsEmailBound(true); setShowEmailModal(false); }} />

      <AssetModal 
        isOpen={assetModal.isOpen} 
        onClose={() => setAssetModal(prev => ({ ...prev, isOpen: false }))} 
        lang={lang} 
        type={assetModal.type} 
        maxAmount={1000.00} 
        onConfirm={(v) => handleAssetConfirm(assetModal.type, v)} 
        theme={theme}
      />

      {marginManage.isOpen && marginManage.pos && (
         <MarginManageModal 
            isOpen={true} onClose={() => setMarginManage(m => ({...m, isOpen: false}))}
            lang={lang} theme={theme} type={marginManage.type} pos={marginManage.pos}
            available={marginManage.type === 'add' ? accountInfo.marginBalance : marginManage.pos.margin - 100}
            onConfirm={(v) => {
              setPositions(prev => prev.map(p => p.id === marginManage.pos?.id ? { ...p, margin: marginManage.type === 'add' ? p.margin + v : p.margin - v } : p));
              setMarginManage(m => ({ ...m, isOpen: false }));
              addRichNotification('success', lang === 'en' ? 'Margin Adjusted' : '保证金调整成功', `${marginManage.type === 'add' ? 'Added' : 'Removed'} ${v} USDC margin.`);
            }}
         />
      )}
    </div>
  );
}

import React, { useState, useEffect } from 'react';
import { Position, Order, Language, MarginMode, OrderType, Theme, OrderSide } from '../types';
import { TRANSLATIONS, INITIAL_MARKET_DATA, MOCK_FUNDING_RECORDS, MOCK_HISTORY_ORDERS, MOCK_TRADE_HISTORY } from '../constants';
import { Edit3, Trash2, X, ChevronDown, Repeat, Filter, PlusCircle, MinusCircle, Info } from 'lucide-react';
import { CustomSlider } from './TradeForm';

interface PositionTableProps {
  positions: Position[];
  orders: Order[];
  assetHistory: any[];
  lang: Language;
  theme: Theme;
  onClosePosition: (id: string, type: OrderType, price?: number, amount?: number) => void;
  onCancelOrder: (id: string) => void;
  onEditMargin: (position: Position, type: 'add' | 'extract') => void;
  onCloseAll: () => void;
  onCancelAll: () => void;
}

const ThWithTooltip: React.FC<{ label: string; explanation?: string; align?: 'left' | 'right' }> = ({ label, explanation, align = 'left' }) => {
  const [showTooltip, setShowTooltip] = useState(false);
  return (
    <th className={`py-2 px-4 font-semibold text-gray-500 uppercase relative ${align === 'right' ? 'text-right' : 'text-left'}`}>
      <div 
        className={`inline-flex items-center space-x-1 cursor-help border-b border-dashed border-gray-300 dark:border-slate-700 transition-colors hover:border-brand-500 ${align === 'right' ? 'justify-end' : ''}`}
        onMouseEnter={() => setShowTooltip(true)}
        onMouseLeave={() => setShowTooltip(false)}
      >
        <span>{label}</span>
      </div>
      {showTooltip && explanation && (
        <div className={`absolute top-full mb-2 ${align === 'right' ? 'right-0' : 'left-0'} z-[2000] w-64 p-3 bg-white dark:bg-slate-800 border border-gray-200 dark:border-slate-700 rounded-lg shadow-2xl text-xs text-gray-600 dark:text-gray-300 leading-relaxed normal-case animate-in fade-in zoom-in-95 duration-100 ring-1 ring-black/5`}>
          <div className="font-bold text-slate-900 dark:text-white mb-1 flex items-center space-x-1">
            <Info size={12} className="text-brand-500" />
            <span>{label}</span>
          </div>
          {explanation}
        </div>
      )}
    </th>
  );
};

export const PositionTable: React.FC<PositionTableProps> = ({ positions, orders, assetHistory, lang, theme, onClosePosition, onCancelOrder, onEditMargin, onCloseAll, onCancelAll }) => {
  const t = TRANSLATIONS[lang];
  const [activeTab, setActiveTab] = useState<'positions' | 'openOrders' | 'orderHistory' | 'tradeHistory' | 'assetsHistory' | 'fundingHistory'>('positions');
  const [closingPos, setClosingPos] = useState<Position | null>(null);
  const [fundingFilter, setFundingFilter] = useState('all');
  const [showCloseAllModal, setShowCloseAllModal] = useState(false);

  // Dynamic Recent Trades for History
  const [allTrades, setAllTrades] = useState<any[]>([]);

  useEffect(() => {
    setAllTrades(MOCK_TRADE_HISTORY);
  }, []);

  const getTabLabel = (tabId: string) => {
    const label = (t as any)[tabId] || tabId;
    if (tabId === 'positions') return `${label}(${positions.length})`;
    if (tabId === 'openOrders') return `${label}(${orders.length})`;
    return label;
  };

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'completed': return 'text-teal-500 bg-teal-500/10';
      case 'processing': case 'confirming': case 'reviewing': return 'text-amber-500 bg-amber-500/10';
      case 'rejected': case 'failed': return 'text-rose-500 bg-rose-500/10';
      case 'canceled': return 'text-gray-400 bg-gray-100 dark:bg-slate-800';
      case 'filledOrder': return 'text-brand-500 bg-brand-500/10';
      default: return 'text-gray-500 bg-gray-500/10';
    }
  };

  const CloseModal = ({ pos, onClose }: { pos: Position, onClose: () => void }) => {
    const [closeType, setCloseType] = useState<OrderType>(OrderType.MARKET);
    const [closePrice, setClosePrice] = useState<string>(INITIAL_MARKET_DATA.lastPrice.toFixed(2));
    const [closeAmount, setCloseAmount] = useState<string>(pos.size.toString());
    const [unit, setUnit] = useState<'XAU' | 'USDC'>('XAU');
    const [sliderVal, setSliderVal] = useState(100);

    const handleConfirm = () => { 
      const amountNum = parseFloat(closeAmount) || 0;
      const xauAmount = unit === 'XAU' ? amountNum : amountNum / (parseFloat(closePrice) || pos.markPrice);
      onClosePosition(pos.id, closeType, parseFloat(closePrice), xauAmount); 
      onClose(); 
    };

    const handleSlider = (val: number) => { 
      setSliderVal(val);
      const targetXAU = pos.size * (val / 100);
      if (unit === 'XAU') {
        setCloseAmount(targetXAU.toFixed(4));
      } else {
        setCloseAmount((targetXAU * (parseFloat(closePrice) || pos.markPrice)).toFixed(2));
      }
    };

    const amountNum = parseFloat(closeAmount) || 0;
    const estXAU = unit === 'XAU' ? amountNum : amountNum / (parseFloat(closePrice) || pos.markPrice);
    const estPnl = estXAU * ((closeType === OrderType.MARKET ? pos.markPrice : parseFloat(closePrice) || pos.markPrice) - pos.entryPrice);

    return (
      <div className="fixed inset-0 z-[200] flex items-center justify-center bg-black/70 backdrop-blur-sm p-4">
        <div className="w-full max-w-[420px] bg-white dark:bg-[#1a1c22] border border-gray-200 dark:border-slate-800 rounded-lg shadow-2xl overflow-hidden animate-in fade-in zoom-in duration-200">
          <div className="flex items-center justify-between px-6 py-4 border-b border-gray-100 dark:border-slate-800">
            <h3 className="text-lg font-bold dark:text-white">{t.closePos}</h3>
