          </div>
          <div className="relative">
            <input 
              type="number" 
              value={amount} 
              onChange={e => {
                setAmount(e.target.value);
                setHasError(false);
              }}
              placeholder={t.amount} 
              className={`w-full bg-transparent border rounded p-2.5 pr-16 text-sm font-mono outline-none dark:text-white transition-all ${hasError ? 'border-red-500 ring-1 ring-red-500/20 shadow-[0_0_8px_rgba(239,68,68,0.2)]' : 'border-gray-200 dark:border-slate-700'}`} 
            />
            <span className="absolute right-3 top-2.5 text-xs text-gray-500 font-bold">{selectedToken}</span>
          </div>
          <div className="pt-2"><CustomSlider value={val} onChange={handleSlider} theme={theme} /></div>
