export const AssetModal: React.FC<{ isOpen: boolean; onClose: () => void; lang: Language; type: 'deposit' | 'withdraw'; maxAmount: number; onConfirm: (v: number) => void; theme: Theme }> = ({ isOpen, onClose, lang, type, maxAmount, onConfirm, theme }) => {
  const t = TRANSLATIONS[lang];
  const [amount, setAmount] = useState('');
  const [val, setVal] = useState(0);
  const [selectedToken, setSelectedToken] = useState('USDC');
  const [tokenSelectorOpen, setTokenSelectorOpen] = useState(false);
  const [hasError, setHasError] = useState(false);
  const [processingState, setProcessingState] = useState<null | 'approving' | 'swapping' | 'depositing'>(null);
  const selectorRef = useRef<HTMLDivElement>(null);

  const tokens = ['USDC', 'ETH', 'ARB', 'USDT'];
  const currentWalletBalance = MOCK_WALLET_BALANCES[selectedToken] || 0;

  const numAmount = parseFloat(amount) || 0;
  const isQuickSwap = type === 'deposit' && selectedToken !== 'USDC';

  // Calculate estimation for Swap
  const getConvertedValue = () => {
    if (!isQuickSwap) return numAmount;
    const rate = selectedToken === 'ETH' ? 3245 : selectedToken === 'ARB' ? 0.82 : 1.0;
    return numAmount * rate;
  };

  const actualReceivedUSDC = getConvertedValue();
  const actualAmount = type === 'withdraw' ? Math.max(0, numAmount - 0.5) : numAmount;

  const handleSlider = (v: number) => { 
    setVal(v); 
    setAmount((currentWalletBalance * v / 100).toFixed(selectedToken === 'ETH' ? 4 : 2)); 
    setHasError(false);
  };

  const handleAction = async () => {
    if (!amount || parseFloat(amount) <= 0) {
      setHasError(true);
      return;
    }

    if (type === 'deposit') {
      // Simulation steps for Deposit
      // 1. Approving (Skip for ETH)
      if (selectedToken !== 'ETH') {
        setProcessingState('approving');
        await new Promise(r => setTimeout(r, 1500));
      }

      // 2. Swapping (Only for non-USDC tokens)
      if (selectedToken !== 'USDC') {
        setProcessingState('swapping');
        await new Promise(r => setTimeout(r, 1500));
      }

      // 3. Depositing (Always)
      setProcessingState('depositing');
      await new Promise(r => setTimeout(r, 1500));
    }

    // Pass the actual USDC value for confirmations/notifications
    onConfirm(actualReceivedUSDC);
    setAmount('');
    setVal(0);
    setHasError(false);
    setProcessingState(null);
  };

  // Reset state on open
  useEffect(() => {
    if (isOpen) {
      setHasError(false);
      setAmount('');
      setVal(0);
      setProcessingState(null);
      if (type === 'withdraw') {
        setSelectedToken('USDC');
      }
    }
  }, [isOpen, type]);

  useEffect(() => {
    const handleClickOutside = (e: MouseEvent) => {
      if (selectorRef.current && !selectorRef.current.contains(e.target as Node)) {
        setTokenSelectorOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const getButtonText = () => {
    if (processingState === 'approving') {
      return t.approvingToken.replace('{token}', selectedToken);
    }
    if (processingState === 'swapping') {
      return t.swappingToken;
    }
    if (processingState === 'depositing') {
      return t.depositingToVault;
    }
    if (isQuickSwap) return t.swap;
    return t.confirm;
  };

  return (
    <BaseModal isOpen={isOpen} onClose={onClose} title={type === 'deposit' ? t.deposit : t.withdraw}>
      <div className="space-y-5">
        {/* Token Selector (Only for Deposit) */}
        {type === 'deposit' && (
          <div className="space-y-2 relative" ref={selectorRef}>
            <div className="text-xs font-bold text-gray-500 uppercase">{t.selectToken}</div>
            <button 
              onClick={() => !processingState && setTokenSelectorOpen(!tokenSelectorOpen)}
              disabled={!!processingState}
              className={`w-full flex items-center justify-between p-3 bg-gray-50 dark:bg-slate-800/50 border border-gray-200 dark:border-slate-700 rounded-lg hover:border-brand-500 transition-all dark:text-white ${processingState ? 'opacity-50 cursor-not-allowed' : ''}`}
            >
              <div className="flex items-center space-x-3">
                {TokenIcons[selectedToken]}
                <span className="font-bold">{selectedToken}</span>
              </div>
              <ChevronDown size={18} className={`transition-transform ${tokenSelectorOpen ? 'rotate-180' : ''}`} />
            </button>

            {tokenSelectorOpen && (
              <div className="absolute top-full left-0 right-0 mt-1 bg-white dark:bg-dark-card border border-gray-200 dark:border-slate-700 rounded-lg shadow-2xl z-50 overflow-hidden animate-in fade-in slide-in-from-top-1 duration-150">
                {tokens.map(tk => (
                  <button 
                    key={tk}
                    onClick={() => {
                      setSelectedToken(tk);
                      setTokenSelectorOpen(false);
                      setAmount('');
                      setVal(0);
                      setHasError(false);
                    }}
                    className={`w-full flex items-center justify-between p-3 hover:bg-gray-50 dark:hover:bg-slate-800 transition-colors ${selectedToken === tk ? 'bg-brand-500/10' : ''}`}
                  >
                    <div className="flex items-center space-x-3">
                      {TokenIcons[tk]}
                      <span className={`font-bold ${selectedToken === tk ? 'text-brand-500' : 'dark:text-white'}`}>{tk}</span>
                    </div>
                    <div className="text-right">
                      <div className="text-xs font-bold dark:text-white">{MOCK_WALLET_BALANCES[tk].toLocaleString()}</div>
                      <div className="text-[10px] text-gray-500 uppercase">{tk}</div>
                    </div>
                  </button>
                ))}
              </div>
            )}
          </div>
        )}

        {/* Withdrawal specific token label */}
        {type === 'withdraw' && (
           <div className="space-y-2">
             <div className="text-xs font-bold text-gray-500 uppercase">{t.selectToken}</div>
             <div className="flex items-center space-x-3 p-3 bg-gray-50 dark:bg-slate-800/50 border border-gray-200 dark:border-slate-700 rounded-lg dark:text-white opacity-80">
               {TokenIcons.USDC}
               <span className="font-bold">USDC</span>
             </div>
           </div>
        )}

        <div className="space-y-2">
          <div className="flex justify-between text-xs font-bold text-gray-500 uppercase">
            <span>{t.amount}</span>
            <span>{type === 'deposit' ? t.walletBalance : (lang === 'zh-CN' ? '可提现' : 'Avail to Withdraw')}: {currentWalletBalance.toLocaleString()} {selectedToken}</span>
          </div>
          <div className="relative">
            <input 
              type="number" 
              value={amount} 
              disabled={!!processingState}
              onChange={e => {
                setAmount(e.target.value);
                setHasError(false);
              }}
              placeholder={t.amount} 
              className={`w-full bg-transparent border rounded p-2.5 pr-16 text-sm font-mono outline-none dark:text-white transition-all ${hasError ? 'border-red-500 ring-1 ring-red-500/20 shadow-[0_0_8px_rgba(239,68,68,0.2)]' : 'border-gray-200 dark:border-slate-700'} ${processingState ? 'opacity-50' : ''}`} 
            />
            <span className="absolute right-3 top-2.5 text-xs text-gray-500 font-bold">{selectedToken}</span>
          </div>
          <div className={`pt-2 ${processingState ? 'pointer-events-none opacity-50' : ''}`}><CustomSlider value={val} onChange={handleSlider} theme={theme} /></div>
        </div>

        <div className="space-y-2">
          <div className="text-xs font-bold text-gray-500 uppercase">{t.network}</div>
          <div className="flex items-center justify-between border border-gray-200 dark:border-slate-700 p-2.5 rounded bg-gray-50 dark:bg-slate-800/50">
             <div className="flex items-center space-x-3">
               <ArbitrumLogo />
               <span className="font-bold text-sm dark:text-white">Arbitrum</span>
             </div>
             {isQuickSwap && (
               <div className="flex items-center space-x-1 text-[10px] bg-brand-500/10 text-brand-500 px-2 py-0.5 rounded font-black">
                 <Info size={10} />
                 <span>Auto-Swap to USDC</span>
               </div>
             )}
          </div>
        </div>

        {type === 'deposit' ? (
           <div className="space-y-1">
             <p className="text-[10px] text-gray-500 leading-tight">
               {isQuickSwap 
                 ? (lang === 'en' ? 'Quick Swap uses decentralized aggregators to convert your deposit to USDC.' : '闪兑功能将通过去中心化聚合器自动将您的充值转换为 USDC。') 
                 : t.depositTips}
             </p>
             {isQuickSwap && numAmount > 0 && (
                <div className="flex justify-between items-center bg-brand-500/5 p-2 rounded border border-brand-500/20 mt-2">
                  <span className="text-[11px] font-bold text-gray-500">{lang === 'en' ? 'Est. Received' : '预估到账'}</span>
                  <span className="font-mono text-xs font-bold text-brand-500">
                    ≈ {actualReceivedUSDC.toFixed(2)} USDC
                  </span>
                </div>
             )}
           </div>
        ) : (
           <div className="space-y-1 pt-1">
              <div className="flex justify-between text-xs text-gray-500"><span>{t.withdrawFee}</span><span className="text-red-400">0.5 USDC</span></div>
              <div className="flex justify-between text-xs text-gray-500 font-bold"><span>{t.actualAmount}</span><span className="text-green-500 font-mono">{actualAmount.toFixed(2)} USDC</span></div>
           </div>
        )}

        <div className="grid grid-cols-2 gap-4 pt-2">
           <button onClick={onClose} disabled={!!processingState} className={`py-2.5 bg-gray-400 hover:bg-gray-500 text-white font-bold rounded transition-all ${processingState ? 'opacity-50 cursor-not-allowed' : ''}`}>{t.cancel}</button>
           <button 
            onClick={handleAction} 
            disabled={!!processingState}
            className={`py-2.5 text-white font-bold rounded shadow-xl transition-all flex items-center justify-center space-x-2 ${isQuickSwap ? 'bg-brand-500 hover:bg-brand-600' : 'bg-[#8B5E14] hover:bg-[#7a5212]'} ${processingState ? 'opacity-80' : ''}`}
           >
             {processingState && <Loader2 size={16} className="animate-spin" />}
             <span>{getButtonText()}</span>
           </button>
        </div>
      </div>
    </BaseModal>
  );
};

export const MarginManageModal: React.FC<{ isOpen: boolean; onClose: () => void; lang: Language; type: 'add' | 'extract'; pos: Position; theme: Theme; available: number; onConfirm: (v: number) => void; }> = ({ isOpen, onClose, lang, type, pos, theme, available, onConfirm }) => {
  const t = TRANSLATIONS[lang];
  const [amount, setAmount] = useState('');
  const [sliderVal, setSliderVal] = useState(0);

  const numAmount = parseFloat(amount) || 0;
  const isAdd = type === 'add';
  const newMargin = isAdd ? pos.margin + numAmount : Math.max(0, pos.margin - numAmount);

  // Dynamic comparison calculations
  const notional = pos.size * pos.markPrice;
  const oldLeverage = notional / pos.margin;
  const newLeverage = newMargin > 0 ? notional / newMargin : oldLeverage;

  const oldLiq = pos.liquidationPrice;
  const liqDiff = (oldLiq * (numAmount / pos.margin)) * (isAdd ? -1 : 1);
  const newLiq = oldLiq + liqDiff;

  const oldMarginRate = (pos.margin / notional) * 100;
  const newMarginRate = (newMargin / notional) * 100;

  const handleSlider = (v: number) => { setSliderVal(v); setAmount((available * v / 100).toFixed(2)); };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-[300] flex items-center justify-center bg-black/60 backdrop-blur-sm p-4">
      <div className="w-full max-w-[420px] bg-white dark:bg-[#1a1c22] border border-gray-200 dark:border-slate-800 rounded-lg shadow-2xl overflow-hidden animate-in fade-in zoom-in duration-200">
        <div className="flex items-center justify-between px-6 py-4 border-b border-gray-100 dark:border-slate-800">
           <h3 className="text-lg font-bold dark:text-white">{isAdd ? t.addMargin : t.removeMargin}</h3>
           <button onClick={onClose} className="text-gray-400 hover:text-white transition"><X size={20} /></button>
        </div>
        <div className="p-6 space-y-5">
           <div className="flex flex-col border-b border-gray-100 dark:border-slate-800 pb-3">
              <div className="flex justify-between items-center text-sm mb-1">
                <span className="text-gray-500">{t.contract}</span>
                <span className="font-bold text-[#10B981] font-mono">{pos.symbol} / {pos.side === 'BUY' ? t.long : t.short}</span>
              </div>
              <div className="flex justify-between text-[11px] text-gray-500">
                <span>{t.entryPrice}: <span className="font-mono">{pos.entryPrice.toFixed(2)}</span></span>
                <span>{t.markPrice}: <span className="font-mono">{pos.markPrice.toFixed(2)}</span></span>
              </div>
           </div>

           <div className="space-y-2">
              <div className="flex justify-between text-xs font-bold text-gray-500">
                 <span>{t.amount}</span>
                 <span>{isAdd ? t.avail : t.availExtract}: {available.toLocaleString()} USDC</span>
              </div>
              <div className="relative">
                 <input type="number" value={amount} onChange={e => setAmount(e.target.value)} placeholder={t.amount} className="w-full bg-transparent border border-gray-200 dark:border-slate-700 rounded p-2.5 pr-14 text-sm font-mono focus:border-brand-500 outline-none dark:text-white" />
                 <span className="absolute right-3 top-2.5 text-xs text-gray-500 font-bold">USDC</span>
              </div>
              <div className="pt-2"><CustomSlider value={sliderVal} onChange={handleSlider} theme={theme} /></div>
           </div>

           <div className="space-y-4 pt-2 border-t border-gray-100 dark:border-slate-800">
              <div className="flex justify-between items-center text-xs">
                 <span className="text-gray-500">{t.margin}</span>
                 <div className="flex items-center space-x-3 font-mono font-bold dark:text-white">
                    <span>{pos.margin.toFixed(2)}</span><ArrowRightIcon size={12} className="text-[#10B981]" /><span>{newMargin.toFixed(2)}</span>
                 </div>
              </div>
              <div className="flex justify-between items-center text-xs">
                 <span className="text-gray-500">{t.liqPrice}</span>
                 <div className="flex items-center space-x-3 font-mono font-bold dark:text-white">
                    <span>{pos.liquidationPrice.toFixed(2)}</span><ArrowRightIcon size={12} className="text-[#10B981]" /><span>{newLiq.toFixed(2)}</span>
                 </div>
              </div>
              <div className="flex justify-between items-center text-xs">
                 <span className="text-gray-500">{t.leverage}</span>
                 <div className="flex items-center space-x-3 font-mono font-bold dark:text-white">
                    <span>{oldLeverage.toFixed(2)}x</span><ArrowRightIcon size={12} className="text-[#10B981]" /><span>{newLeverage.toFixed(2)}x</span>
                 </div>
              </div>
              <div className="flex justify-between items-center text-xs">
                 <span className="text-gray-500">{t.marginRate}</span>
                 <div className="flex items-center space-x-3 font-mono font-bold dark:text-white">
                    <span>{oldMarginRate.toFixed(2)}%</span><ArrowRightIcon size={12} className="text-[#10B981]" /><span>{newMarginRate.toFixed(2)}%</span>
                 </div>
              </div>
           </div>

           <div className="grid grid-cols-2 gap-4 pt-4">
              <button onClick={onClose} className="py-3 bg-gray-400 hover:bg-gray-500 text-white font-bold rounded-lg transition">{t.cancel}</button>
              <button 
                onClick={() => onConfirm(numAmount)} 
                disabled={numAmount <= 0 || numAmount > available}
                className="py-3 bg-[#8B5E14] hover:bg-[#7a5212] text-white font-bold rounded-lg shadow-xl shadow-[#8B5E14]/20 transition disabled:opacity-50 disabled:cursor-not-allowed"
              >
                {t.confirm}
              </button>
           </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { Header } from './components/Header';
import { MarketStats } from './components/MarketStats';
import { CandleChart } from './components/CandleChart';
import { OrderBook } from './components/OrderBook';
import { TradeForm } from './components/TradeForm';
import { PositionTable } from './components/PositionTable';
import { AccountInfo } from './components/AccountInfo';
import { NotificationContainer, RichNotification } from './components/Notification';
import { WalletModal, AssetModal, MarginManageModal, SignatureModal, SettingsModal, EmailModal } from './components/Modals';
import { INITIAL_MARKET_DATA, MOCK_POSITIONS, TRANSLATIONS, INITIAL_ACCOUNT_INFO, MOCK_ASSETS_HISTORY } from './constants';
import { Language, Theme, MarketData, Position, Order, OrderSide, OrderType, MarginMode, AccountInfo as AccountInfoType } from './types';

export default function App() {
  const [lang, setLang] = useState<Language>('zh-CN');
  const [theme, setTheme] = useState<Theme>('dark');
  const [isConnected, setIsConnected] = useState(false);
  const [isSigned, setIsSigned] = useState(false);
  const [isEmailBound, setIsEmailBound] = useState(false);
  const [marketData, setMarketData] = useState<MarketData>(INITIAL_MARKET_DATA);
  const [positions, setPositions] = useState<Position[]>(MOCK_POSITIONS);
  const [orders, setOrders] = useState<Order[]>([]);
  const [assetHistory, setAssetHistory] = useState(MOCK_ASSETS_HISTORY);
  const [notifications, setNotifications] = useState<RichNotification[]>([]);
  const [accountInfo, setAccountInfo] = useState<AccountInfoType>(INITIAL_ACCOUNT_INFO);

  const [showWalletModal, setShowWalletModal] = useState(false);
  const [showSignModal, setShowSignModal] = useState(false);
  const [showSettingsModal, setShowSettingsModal] = useState(false);
  const [showEmailModal, setShowEmailModal] = useState(false);

  const [assetModal, setAssetModal] = useState<{ isOpen: boolean, type: 'deposit' | 'withdraw' }>({ isOpen: false, type: 'deposit' });
  const [marginManage, setMarginManage] = useState<{ isOpen: boolean; type: 'add' | 'extract'; pos: Position | null }>({ isOpen: false, type: 'add', pos: null });

  // State for populating price from OrderBook to TradeForm
  const [selectedPrice, setSelectedPrice] = useState<string | null>(null);

  const addRichNotification = (type: RichNotification['type'], title: string, message: string) => {
    const id = Date.now().toString();
    setNotifications(prev => [...prev, { id, type, title, message }]);
  };

  const handleConnectClick = () => {
    setShowWalletModal(true);
  };

  const handleWalletSelect = () => {
    setShowWalletModal(false);
    setShowSignModal(true);
  };

  const handleSign = () => {
    setShowSignModal(false);
    setIsConnected(true);
    setIsSigned(true);
    const title = lang === 'en' ? 'Welcome Back' : (lang === 'zh-CN' ? '欢迎回来' : '歡迎回來');
    const body = lang === 'en' ? 'Wallet connected and signed successfully.' : '钱包连接并签名成功。';
    addRichNotification('success', title, body);
  };

  const handleOrder = (side: OrderSide, type: OrderType, size: number, price: number, leverage: number, marginMode: MarginMode) => {
    if (!isSigned) { setShowWalletModal(true); return; }

    if (type === OrderType.MARKET) {
      const newPos: Position = { id: Date.now().toString(), symbol: marketData.symbol, side, size, entryPrice: price, markPrice: price, leverage, margin: (size * price) / leverage, marginMode, pnl: 0, pnlPercent: 0, liquidationPrice: side === OrderSide.BUY ? price * 0.8 : price * 1.2 };
      setPositions(prev => [newPos, ...prev]);

      const title = lang === 'en' ? 'Market Order Filled' : (lang === 'zh-CN' ? '市价单已完全成交' : '市價單已完全成交');
      const body = lang === 'en' 
        ? `Market ${side === OrderSide.BUY ? 'Buy' : 'Sell'} ${size.toFixed(2)} XAU fully filled.\nAvg Price $${price.toFixed(2)} | Fee $${(size * price * 0.0005).toFixed(2)}`
        : `市价${side === OrderSide.BUY ? '买入' : '卖出'} ${size.toFixed(2)} ${marketData.symbol.replace('USDC', '')} 已完全成交\n平均成交价 $${price.toFixed(2)} | 手续费 $${(size * price * 0.0005).toFixed(2)}`;
      addRichNotification('success', title, body);
    } else {
      const newOrder: Order = {
        id: Date.now().toString(),
        symbol: marketData.symbol,
        side,
        type: OrderType.LIMIT,
        price,
        amount: size,
        filled: 0,
        leverage,
        status: 'OPEN',
        time: new Date().toLocaleString()
      };
      setOrders(prev => [newOrder, ...prev]);

      const title = lang === 'en' ? 'Order Created' : (lang === 'zh-CN' ? '下单成功' : '下單成功');
      const sideStr = lang === 'en' ? (side === OrderSide.BUY ? 'Buy' : 'Sell') : (side === OrderSide.BUY ? '买入' : '卖出');
      const body = lang === 'en'
        ? `You have successfully submitted ${marketData.symbol} ${sideStr} Limit Order.\nPrice $${price.toLocaleString()} | Amount ${size} XAU | Leverage ${leverage}x`
        : `您已成功提交${marketData.symbol} ${sideStr} 限价单\n价格 $${price.toLocaleString()} | 数量 ${size} ${marketData.symbol.replace('USDC', '')} | 杠杆 ${leverage}x`;
      addRichNotification('success', title, body);
    }
  };

  const handleClosePosition = (id: string, type: OrderType, closePrice?: number, closeAmount?: number) => {
    const pos = positions.find(p => p.id === id);
    if (!pos) return;

    setPositions(prev => prev.filter(x => x.id !== id));

    const title = lang === 'en' ? 'Position Closed' : (lang === 'zh-CN' ? '仓位已平仓' : '倉位已平倉');
    const sideStr = lang === 'en' ? (pos.side === OrderSide.BUY ? 'Long' : 'Short') : (pos.side === OrderSide.BUY ? '多头' : '空头');
    const body = lang === 'en'
      ? `Successfully closed ${pos.symbol} ${sideStr}.\nClosed Amount ${pos.size} XAU | Realized PnL +$${pos.pnl.toFixed(2)}`
      : `您已成功平仓 ${pos.symbol} ${sideStr}\n平仓数量 ${pos.size} ${pos.symbol.replace('USDC', '')} | 实现盈亏 +$${pos.pnl.toFixed(2)}`;
    addRichNotification('success', title, body);
  };

  const handleAssetConfirm = (type: 'deposit' | 'withdraw', v: number) => {
     // Note: v is the USDC equivalent for Swap/Deposit, or requested amount for Withdraw
     const status = type === 'deposit' ? 'completed' : (v >= 100 ? 'reviewing' : 'completed');
     const newRecord = {
        id: Date.now().toString(),
        asset: 'USDC',
        type,
        amount: v,
        fee: type === 'withdraw' ? 0.5 : null,
        hash: '0x' + Math.random().toString(16).slice(2, 10) + '...',
        status,
        time: new Date().toISOString().replace('T', ' ').slice(0, 19)
     };
     setAssetHistory(prev => [newRecord, ...prev]);
     setAssetModal(m => ({ ...m, isOpen: false }));

     if (type === 'deposit') {
       const title = lang === 'en' ? 'Deposit Success' : (lang === 'zh-CN' ? '充值成功' : '充值成功');
       const body = lang === 'en' 
        ? `You have successfully deposited ${v.toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })} USDC, please check.`
        : `您已成功充值 ${v.toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })} USDC，请查看`;
       addRichNotification('success', title, body);
     } else {
       const title = lang === 'en' ? 'Withdrawal Success' : (lang === 'zh-CN' ? '提现成功' : '提現成功');
       const body = lang === 'en'
        ? `You have successfully withdrawn ${v.toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })} USDC to 0x4b...5591 (Arbitrum), estimated arrival in 1 minute.`
        : `您已成功提现 ${v.toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })} USDC 至 0x4b...5591 (Arbitrum)，预计 1 分钟到账。`;
       addRichNotification('success', title, body);
     }
  };

  const simulateLiquidation = () => {
    const title = lang === 'en' ? 'Position Liquidated' : (lang === 'zh-CN' ? '仓位已强平' : '倉位已強平');
    const body = lang === 'en'
      ? `Your ${marketData.symbol} Long position triggered liquidation at $2,800. $428 Liquidation fee deducted.`
      : `您的 ${marketData.symbol} 多头仓位已触发强平，强平价格 $2,800，已扣除 $428 强平罚金。`;
    addRichNotification('liquidation', title, body);
  };

  return (
    <div className={`flex flex-col h-screen ${theme} bg-gray-50 dark:bg-dark-bg text-slate-900 dark:text-slate-200 font-sans overflow-hidden transition-colors`}>
      <Header 
        lang={lang} setLang={setLang} theme={theme} setTheme={setTheme}
        isConnected={isSigned} 
        onConnectClick={handleConnectClick} 
        onDeposit={() => setAssetModal({ isOpen: true, type: 'deposit' })}
        onWithdraw={() => setAssetModal({ isOpen: true, type: 'withdraw' })}
        onDisconnect={() => { setIsConnected(false); setIsSigned(false); setPositions([]); setOrders([]); }}
      />
      <MarketStats data={marketData} lang={lang} onMarketSelect={setMarketData} />
      <main className="flex-1 flex overflow-hidden">
        <div className="flex-1 flex flex-col min-w-0">
          <div className="flex-[1.8] flex border-b border-gray-200 dark:border-dark-border">
            <div className="flex-1 relative border-r border-gray-200 dark:border-dark-border">
              <CandleChart lang={lang} currentMarket={marketData} />
              <button 
                onClick={simulateLiquidation}
                className="absolute bottom-4 left-4 bg-rose-600/20 hover:bg-rose-600/40 text-rose-500 text-[10px] px-2 py-1 rounded border border-rose-500/30 font-bold transition-all z-20"
              >
                Simulate Liq.
              </button>
            </div>
            <div className="w-[280px] hidden lg:block bg-white dark:bg-dark-card shrink-0">
              <OrderBook lang={lang} lastPrice={marketData.lastPrice} onPriceClick={(p) => setSelectedPrice(p.toFixed(2))} />
            </div>
          </div>
          <div className="flex-[2] min-h-[250px] flex flex-col overflow-hidden">
             <PositionTable 
               positions={positions} orders={orders} assetHistory={assetHistory} lang={lang} theme={theme}
               onClosePosition={handleClosePosition}
               onCancelOrder={(id) => setOrders(o => o.filter(x => x.id !== id))}
               onEditMargin={(pos, type) => setMarginManage({ isOpen: true, type, pos })}
               onCloseAll={() => setPositions([])}
               onCancelAll={() => setOrders([])}
             />
          </div>
        </div>
        <div className="w-[340px] flex flex-col border-l border-gray-200 dark:border-dark-border bg-white dark:bg-dark-card z-30 shrink-0">
          <div className="flex-1 overflow-y-auto">
            <TradeForm 
              lang={lang} 
              theme={theme} 
              isConnected={isSigned} 
              onConnect={() => setShowWalletModal(true)} 
              onOrder={handleOrder} 
              lastPrice={marketData.lastPrice} 
              availableBalance={accountInfo.marginBalance} 
              currentSymbol={marketData.symbol} 
              selectedPrice={selectedPrice}
            />
          </div>
          <div className="shrink-0 border-t border-gray-200 dark:border-dark-border"><AccountInfo lang={lang} info={accountInfo} /></div>
        </div>
      </main>

      <NotificationContainer notifications={notifications} removeNotification={(id) => setNotifications(n => n.filter(x => x.id !== id))} />

      <WalletModal isOpen={showWalletModal} onClose={() => setShowWalletModal(false)} lang={lang} onConnect={handleWalletSelect} />
      <SignatureModal isOpen={showSignModal} onClose={() => setShowSignModal(false)} lang={lang} onSign={handleSign} />
      <SettingsModal isOpen={showSettingsModal} onClose={() => setShowSettingsModal(false)} lang={lang} isEmailBound={isEmailBound} onBindClick={() => setShowEmailModal(true)} />
      <EmailModal isOpen={showEmailModal} onClose={() => setShowEmailModal(false)} lang={lang} onBind={() => { setIsEmailBound(true); setShowEmailModal(false); }} />

      <AssetModal 
        isOpen={assetModal.isOpen} 
        onClose={() => setAssetModal(prev => ({ ...prev, isOpen: false }))} 
        lang={lang} 
        type={assetModal.type} 
        maxAmount={1000.00} 
        onConfirm={(v) => handleAssetConfirm(assetModal.type, v)} 
        theme={theme}
      />

      {marginManage.isOpen && marginManage.pos && (
         <MarginManageModal 
            isOpen={true} onClose={() => setMarginManage(m => ({...m, isOpen: false}))}
            lang={lang} theme={theme} type={marginManage.type} pos={marginManage.pos}
            available={marginManage.type === 'add' ? accountInfo.marginBalance : marginManage.pos.margin - 100}
            onConfirm={(v) => {
              setPositions(prev => prev.map(p => p.id === marginManage.pos?.id ? { ...p, margin: marginManage.type === 'add' ? p.margin + v : p.margin - v } : p));
              setMarginManage(m => ({ ...m, isOpen: false }));
              addRichNotification('success', lang === 'en' ? 'Margin Adjusted' : '保证金调整成功', `${marginManage.type === 'add' ? 'Added' : 'Removed'} ${v} USDC margin.`);
            }}
         />
      )}
    </div>
  );
}

import React, { useState, useEffect } from 'react';
import { MOCK_ASKS, MOCK_BIDS, TRANSLATIONS, INITIAL_MARKET_DATA } from '../constants';
import { Language } from '../types';
import { ArrowUp, ArrowDown } from 'lucide-react';

interface OrderBookProps {
  lang: Language;
  lastPrice: number;
  onPriceClick?: (price: number) => void;
}

const Row = ({ price, amount, total, type, onPriceClick }: { price: number, amount: string, total: string, type: 'ask' | 'bid', onPriceClick?: (p: number) => void }) => {
  const bgClass = type === 'ask' ? 'bg-trade-down' : 'bg-trade-up';
  const textClass = type === 'ask' ? 'text-trade-down' : 'text-trade-up';
  const width = Math.min(parseFloat(total) * 1, 100); 

  return (
    <div 
      onClick={() => onPriceClick?.(price)}
      className="grid grid-cols-3 text-[11px] py-0.5 hover:bg-slate-100 dark:hover:bg-slate-700 cursor-pointer transition-colors relative group items-center"
    >
      <div 
        className={`absolute top-0 right-0 h-full opacity-10 transition-all duration-300 ${bgClass}`} 
        style={{ width: `${width}%` }} 
      />
      <div className={`text-left pl-2 ${textClass} z-10 font-mono`}>{price.toFixed(2)}</div>
      <div className="text-right text-slate-700 dark:text-slate-300 z-10 font-mono">{amount}</div>
      <div className="text-right pr-2 text-slate-500 dark:text-gray-400 z-10 font-mono">{total}</div>
    </div>
  );
};

export const OrderBook: React.FC<OrderBookProps> = ({ lang, lastPrice: initialLastPrice, onPriceClick }) => {
  const t = TRANSLATIONS[lang];
  const [tab, setTab] = useState<'book' | 'trades'>('book');
  const [asks, setAsks] = useState(MOCK_ASKS);
  const [bids, setBids] = useState(MOCK_BIDS);
  const [lastPrice, setLastPrice] = useState(initialLastPrice);
  const [trades, setTrades] = useState<any[]>([]);

  // Simulation effect for Order Book and Trades
  useEffect(() => {
    // 调整为 19 行以匹配：9档卖盘 + 1行中间价 + 9档买盘
    const initialTrades = Array.from({ length: 19 }, (_, i) => ({
      id: `initial-${i}`,
      price: initialLastPrice + (Math.random() - 0.5) * 5,
      amount: (Math.random() * 2).toFixed(3),
      time: new Date(Date.now() - i * 5000).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit', hour12: false }),
      side: Math.random() > 0.5 ? 'BUY' : 'SELL'
    }));
    setTrades(initialTrades);

    const interval = setInterval(() => {
      // Update Price
      const priceChange = (Math.random() - 0.5) * 0.5;
      const newPrice = lastPrice + priceChange;
      setLastPrice(newPrice);

      // Update Order Book
      setAsks(prev => prev.map(a => ({
         ...a,
         amount: Math.max(0.1, parseFloat(a.amount) + (Math.random() - 0.5)).toFixed(3),
         total: Math.max(1, parseFloat(a.total) + (Math.random() - 0.5) * 2).toFixed(3)
      })));
      setBids(prev => prev.map(b => ({
         ...b,
         amount: Math.max(0.1, parseFloat(b.amount) + (Math.random() - 0.5)).toFixed(3),
         total: Math.max(1, parseFloat(b.total) + (Math.random() - 0.5) * 2).toFixed(3)
      })));

      // Occasional new trade
      if (Math.random() > 0.4) {
        const side = Math.random() > 0.5 ? 'BUY' : 'SELL';
        const newTrade = {
          id: Date.now().toString(),
          price: newPrice,
          amount: (Math.random() * 1.2).toFixed(3),
          time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit', hour12: false }),
          side
        };
        setTrades(prev => [newTrade, ...prev].slice(0, 19));
      }
    }, 1000);

    return () => clearInterval(interval);
  }, [lastPrice, initialLastPrice]);

  return (
    <div className="flex flex-col h-full bg-white dark:bg-dark-card border-l border-gray-200 dark:border-dark-border overflow-hidden select-none">
      <div className="flex border-b border-gray-200 dark:border-dark-border shrink-0">
        <button 
          onClick={() => setTab('book')}
          className={`flex-1 py-1.5 text-xs font-bold transition-colors ${tab === 'book' ? 'text-brand-500 border-b-2 border-brand-500' : 'text-gray-500'}`}
        >
          {t.orderBook}
        </button>
        <button 
          onClick={() => setTab('trades')}
          className={`flex-1 py-1.5 text-xs font-bold transition-colors ${tab === 'trades' ? 'text-brand-500 border-b-2 border-brand-500' : 'text-gray-500'}`}
        >
          {t.recentTrades}
        </button>
      </div>

      <div className="grid grid-cols-3 text-[9px] text-gray-500 dark:text-gray-400 px-2 py-1 font-semibold shrink-0 uppercase tracking-tighter">
        <div className="text-left">{t.price}</div>
        <div className="text-right">{t.amount}</div>
        <div className="text-right pr-2">{tab === 'book' ? t.total : t.time}</div>
      </div>

      <div className="flex-1 flex flex-col overflow-hidden">
        {tab === 'book' ? (
          <div className="flex-1 flex flex-col justify-between overflow-hidden">
            <div className="flex flex-col justify-end overflow-hidden">
              {/* 增加至 9 档 */}
              {asks.slice(0, 9).map((ask, i) => (
                <Row key={`ask-${i}`} {...ask} price={ask.price} type="ask" onPriceClick={onPriceClick} />
              ))}
            </div>

            <div className="py-1 my-0.5 border-y border-gray-100 dark:border-slate-800 bg-gray-50 dark:bg-slate-900/40 shrink-0 flex items-center justify-center space-x-3">
               <div className="flex items-center space-x-1">
                 <span className={`text-base font-bold font-mono ${lastPrice >= initialLastPrice ? 'text-trade-up' : 'text-trade-down'}`}>{lastPrice.toFixed(2)}</span>
                 {lastPrice >= initialLastPrice ? <ArrowUp size={12} className="text-trade-up" /> : <ArrowDown size={12} className="text-trade-down" />}
               </div>
               <div className="text-[10px] text-slate-500 font-mono">{INITIAL_MARKET_DATA.markPrice.toFixed(2)}</div>
            </div>

            <div className="overflow-hidden">
               {/* 增加至 9 档 */}
               {bids.slice(0, 9).map((bid, i) => (
                <Row key={`bid-${i}`} {...bid} price={bid.price} type="bid" onPriceClick={onPriceClick} />
              ))}
            </div>
          </div>
        ) : (
          <div className="flex-1 overflow-y-auto hide-scrollbar">
             {trades.map((trade) => (
               <div 
                key={trade.id} 
                onClick={() => onPriceClick?.(trade.price)}
                className="grid grid-cols-3 text-[11px] py-1 hover:bg-slate-100 dark:hover:bg-slate-700 cursor-pointer transition-colors px-2"
              >
                 <div className={`text-left font-mono font-bold ${trade.side === 'BUY' ? 'text-trade-up' : 'text-trade-down'}`}>
                   {trade.price.toFixed(2)}
                 </div>
                 <div className="text-right text-slate-700 dark:text-slate-300 font-mono">
                   {trade.amount}
                 </div>
                 <div className="text-right text-slate-500 dark:text-gray-400 font-mono">
                   {trade.time}
                 </div>
               </div>
             ))}
          </div>
        )}
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Language, MarginMode, OrderType, OrderSide, Theme } from '../types';
import { TRANSLATIONS } from '../constants';
import { Edit3, X, Repeat } from 'lucide-react';

interface TradeFormProps {
  lang: Language;
  theme: Theme;
  isConnected: boolean;
  onConnect: () => void;
  onOrder: (side: OrderSide, type: OrderType, size: number, price: number, leverage: number, marginMode: MarginMode) => void;
  lastPrice: number;
  availableBalance: number;
  currentSymbol: string;
  selectedPrice?: string | null;
}

