export const AssetModal: React.FC<{ isOpen: boolean; onClose: () => void; lang: Language; type: 'deposit' | 'withdraw'; maxAmount: number; onConfirm: (v: number) => void; theme: Theme }> = ({ isOpen, onClose, lang, type, maxAmount, onConfirm, theme }) => {
  const t = TRANSLATIONS[lang];
  const [amount, setAmount] = useState('');
  const [val, setVal] = useState(0);
  const [selectedToken, setSelectedToken] = useState('USDC');
  const [tokenSelectorOpen, setTokenSelectorOpen] = useState(false);
  const [hasError, setHasError] = useState(false);
  const [processingState, setProcessingState] = useState<null | 'approving' | 'swapping' | 'depositing' | 'withdrawing'>(null);
  const [slippage, setSlippage] = useState(0.5);
  const [customSlippage, setCustomSlippage] = useState('');
  const selectorRef = useRef<HTMLDivElement>(null);

  const tokens = ['USDC', 'ETH', 'ARB', 'USDT'];
  const currentWalletBalance = MOCK_WALLET_BALANCES[selectedToken] || 0;

  const numAmount = parseFloat(amount) || 0;
  const isQuickSwap = type === 'deposit' && selectedToken !== 'USDC';

  // Calculate estimation for Swap
  const getConvertedValue = () => {
    if (!isQuickSwap) return numAmount;
    const rate = selectedToken === 'ETH' ? 3245 : selectedToken === 'ARB' ? 0.82 : 1.0;
    return numAmount * rate;
  };

  const actualReceivedUSDC = getConvertedValue();
  const actualAmount = type === 'withdraw' ? Math.max(0, numAmount - 0.5) : numAmount;

  const handleSlider = (v: number) => { 
    setVal(v); 
    setAmount((currentWalletBalance * v / 100).toFixed(selectedToken === 'ETH' ? 4 : 2)); 
    setHasError(false);
  };

  const handleAction = async () => {
    if (!amount || parseFloat(amount) <= 0) {
      setHasError(true);
      return;
    }

    if (type === 'deposit') {
      // Simulation steps for Deposit
      if (selectedToken !== 'ETH') {
        setProcessingState('approving');
        await new Promise(r => setTimeout(r, 1500));
      }

      if (selectedToken !== 'USDC') {
        setProcessingState('swapping');
        await new Promise(r => setTimeout(r, 1500));
      }

      setProcessingState('depositing');
      await new Promise(r => setTimeout(r, 1500));
    } else {
      setProcessingState('withdrawing');
      await new Promise(r => setTimeout(r, 2000));
    }

    onConfirm(actualReceivedUSDC);
    setAmount('');
    setVal(0);
    setHasError(false);
    setProcessingState(null);
  };

  // Reset state on open
  useEffect(() => {
    if (isOpen) {
      setHasError(false);
      setAmount('');
      setVal(0);
      setProcessingState(null);
      if (type === 'withdraw') {
        setSelectedToken('USDC');
      }
    }
  }, [isOpen, type]);

  useEffect(() => {
    const handleClickOutside = (e: MouseEvent) => {
      if (selectorRef.current && !selectorRef.current.contains(e.target as Node)) {
        setTokenSelectorOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const getButtonText = () => {
    if (processingState === 'approving') return t.approvingToken.replace('{token}', selectedToken);
    if (processingState === 'swapping') return t.swappingToken;
    if (processingState === 'withdrawing') return t.withdrawingToken;
    if (processingState === 'depositing') return t.depositingToVault;
    if (isQuickSwap) return t.swap;
    return t.confirm;
  };

  return (
    <BaseModal isOpen={isOpen} onClose={onClose} title={type === 'deposit' ? t.deposit : t.withdraw}>
      <div className="space-y-5">
        {/* Network */}
        <div className="space-y-2">
          <div className="text-xs font-bold text-gray-500 uppercase">{t.network}</div>
          <div className="flex items-center justify-between border border-gray-200 dark:border-slate-700 p-2.5 rounded bg-gray-50 dark:bg-slate-800/50">
             <div className="flex items-center space-x-3">
               <ArbitrumLogo />
               <span className="font-bold text-sm dark:text-white">Arbitrum</span>
             </div>
          </div>
        </div>

        {/* Token Selector */}
        {type === 'deposit' ? (
          <div className="space-y-2 relative" ref={selectorRef}>
            <div className="text-xs font-bold text-gray-500 uppercase">{t.selectToken}</div>
            <button 
              onClick={() => !processingState && setTokenSelectorOpen(!tokenSelectorOpen)}
              disabled={!!processingState}
              className={`w-full flex items-center justify-between p-3 bg-gray-50 dark:bg-slate-800/50 border border-gray-200 dark:border-slate-700 rounded-lg hover:border-brand-500 transition-all dark:text-white ${processingState ? 'opacity-50 cursor-not-allowed' : ''}`}
            >
              <div className="flex items-center space-x-3">
                {TokenIcons[selectedToken]}
                <span className="font-bold">{selectedToken}</span>
                {isQuickSwap && (
                  <div className="flex items-center space-x-1 text-[10px] bg-brand-500/10 text-brand-500 px-2 py-0.5 rounded font-black ml-1">
                    <Info size={10} />
                    <span>Auto-Swap to USDC</span>
                  </div>
                )}
              </div>
              <ChevronDown size={18} className={`transition-transform ${tokenSelectorOpen ? 'rotate-180' : ''}`} />
            </button>

            {tokenSelectorOpen && (
              <div className="absolute top-full left-0 right-0 mt-1 bg-white dark:bg-dark-card border border-gray-200 dark:border-slate-700 rounded-lg shadow-2xl z-50 overflow-hidden animate-in fade-in slide-in-from-top-1 duration-150">
                {tokens.map(tk => (
                  <button 
                    key={tk}
                    onClick={() => {
                      setSelectedToken(tk);
                      setTokenSelectorOpen(false);
                      setAmount('');
                      setVal(0);
                      setHasError(false);
                    }}
                    className={`w-full flex items-center justify-between p-3 hover:bg-gray-50 dark:hover:bg-slate-800 transition-colors ${selectedToken === tk ? 'bg-brand-500/10' : ''}`}
                  >
                    <div className="flex items-center space-x-3">
                      {TokenIcons[tk]}
                      <span className={`font-bold ${selectedToken === tk ? 'text-brand-500' : 'dark:text-white'}`}>{tk}</span>
                    </div>
                    <div className="text-right">
                      <div className="text-xs font-bold dark:text-white">{MOCK_WALLET_BALANCES[tk].toLocaleString()}</div>
                      <div className="text-[10px] text-gray-500 uppercase">{tk}</div>
                    </div>
                  </button>
                ))}
              </div>
            )}
          </div>
        ) : (
           <div className="space-y-2">
             <div className="text-xs font-bold text-gray-500 uppercase">{t.selectToken}</div>
             <div className="flex items-center space-x-3 p-3 bg-gray-50 dark:bg-slate-800/50 border border-gray-200 dark:border-slate-700 rounded-lg dark:text-white opacity-80">
               {TokenIcons.USDC}
               <span className="font-bold">USDC</span>
             </div>
           </div>
        )}

        {/* Amount */}
        <div className="space-y-2">
          <div className="flex justify-between text-xs font-bold text-gray-500 uppercase">
            <span>{t.amount}</span>
            <span>{type === 'deposit' ? t.walletBalance : (lang === 'zh-CN' ? '可提现' : 'Avail to Withdraw')}: {currentWalletBalance.toLocaleString()} {selectedToken}</span>
          </div>
          <div className="relative">
            <input 
              type="number" 
              value={amount} 
              disabled={!!processingState}
              onChange={e => {
                setAmount(e.target.value);
                setHasError(false);
              }}
              placeholder={t.amount} 
              className={`w-full bg-transparent border rounded p-2.5 pr-16 text-sm font-mono outline-none dark:text-white transition-all ${hasError ? 'border-red-500 ring-1 ring-red-500/20 shadow-[0_0_8px_rgba(239,68,68,0.2)]' : 'border-gray-200 dark:border-slate-700'} ${processingState ? 'opacity-50' : ''}`} 
            />
            <span className="absolute right-3 top-2.5 text-xs text-gray-500 font-bold">{selectedToken}</span>
          </div>
          <div className={`pt-2 ${processingState ? 'pointer-events-none opacity-50' : ''}`}><CustomSlider value={val} onChange={handleSlider} theme={theme} /></div>
        </div>

        {/* Slippage & Estimation */}
        {type === 'deposit' ? (
           <div className="space-y-3">
             {isQuickSwap && (
                <div className="p-3 bg-gray-50 dark:bg-slate-800/50 border border-gray-200 dark:border-slate-700 rounded-lg animate-in slide-in-from-top-2">
                  <div className="flex justify-between items-center mb-3">
                    <span className="text-[11px] font-bold text-gray-500 uppercase flex items-center space-x-1">
                      <Settings size={10} />
                      <span>{t.slippage}</span>
                    </span>
                    <span className="text-[11px] font-bold text-brand-500">{slippage}%</span>
                  </div>
                  <div className="flex space-x-2">
                    {[0.1, 0.5, 1.0].map(v => (
                      <button 
                        key={v}
                        onClick={() => { setSlippage(v); setCustomSlippage(''); }}
                        className={`flex-1 py-1 text-[11px] font-bold rounded border transition-all ${slippage === v && !customSlippage ? 'bg-brand-500/10 border-brand-500 text-brand-500' : 'border-gray-200 dark:border-slate-700 text-gray-500'}`}
                      >
                        {v}%
                      </button>
                    ))}
                    <div className="flex-[1.5] relative">
                      <input 
                        type="number"
                        value={customSlippage}
                        onChange={e => {
                           setCustomSlippage(e.target.value);
                           setSlippage(parseFloat(e.target.value) || 0.5);
                        }}
                        placeholder={t.custom}
                        className={`w-full py-1 px-2 text-[11px] font-bold rounded border bg-transparent outline-none transition-all ${customSlippage ? 'border-brand-500 text-brand-500' : 'border-gray-200 dark:border-slate-700 text-gray-500 placeholder:text-gray-600'}`}
                      />
                      <span className="absolute right-2 top-1 text-[10px] text-gray-500">%</span>
                    </div>
                  </div>
                </div>
             )}

             <p className="text-[10px] text-gray-500 leading-tight px-1">
               {isQuickSwap ? (lang === 'en' ? 'Quick Swap uses aggregators to convert your deposit to USDC. Slippage protects you from unexpected price movements.' : '闪兑功能将通过聚合器自动将您的充值转换为 USDC。滑点设置可防止因价格剧烈波动导致交易失败。') : t.depositTips}
             </p>

             {isQuickSwap && numAmount > 0 && (
                <div className="flex justify-between items-center bg-brand-500/5 p-2 rounded border border-brand-500/20">
                  <span className="text-[11px] font-bold text-gray-500">{lang === 'en' ? 'Est. Received' : '预估到账'}</span>
                  <span className="font-mono text-xs font-bold text-brand-500">
                    ≈ {actualReceivedUSDC.toFixed(2)} USDC
                  </span>
                </div>
             )}
           </div>
        ) : (
           <div className="space-y-1 pt-1 px-1">
              <div className="flex justify-between text-xs text-gray-500"><span>{t.withdrawFee}</span><span className="text-red-400">0.5 USDC</span></div>
              <div className="flex justify-between text-xs text-gray-500 font-bold"><span>{t.actualAmount}</span><span className="text-green-500 font-mono">{actualAmount.toFixed(2)} USDC</span></div>
           </div>
        )}

        <div className="grid grid-cols-2 gap-4 pt-2">
           <button onClick={onClose} disabled={!!processingState} className={`py-2.5 bg-gray-400 hover:bg-gray-500 text-white font-bold rounded transition-all ${processingState ? 'opacity-50 cursor-not-allowed' : ''}`}>{t.cancel}</button>
           <button 
            onClick={handleAction} 
            disabled={!!processingState}
            className={`py-2.5 text-white font-bold rounded shadow-xl transition-all flex items-center justify-center space-x-2 ${isQuickSwap ? 'bg-brand-500 hover:bg-brand-600' : 'bg-[#8B5E14] hover:bg-[#7a5212]'} ${processingState ? 'opacity-80' : ''}`}
           >
             {processingState && <Loader2 size={16} className="animate-spin" />}
             <span>{getButtonText()}</span>
           </button>
        </div>
      </div>
    </BaseModal>
  );
};

export const MarginManageModal: React.FC<{ isOpen: boolean; onClose: () => void; lang: Language; type: 'add' | 'extract'; pos: Position; theme: Theme; available: number; onConfirm: (v: number) => void; }> = ({ isOpen, onClose, lang, type, pos, theme, available, onConfirm }) => {
  const t = TRANSLATIONS[lang];
  const [amount, setAmount] = useState('');
  const [sliderVal, setSliderVal] = useState(0);

  const numAmount = parseFloat(amount) || 0;
  const isAdd = type === 'add';
  const newMargin = isAdd ? pos.margin + numAmount : Math.max(0, pos.margin - numAmount);

  // Dynamic comparison calculations
  const notional = pos.size * pos.markPrice;

  const oldLiq = pos.liquidationPrice;
  const liqDiff = (oldLiq * (numAmount / pos.margin)) * (isAdd ? -1 : 1);
  const newLiq = oldLiq + liqDiff;

  const oldMarginRate = (pos.margin / notional) * 100;
  const newMarginRate = (newMargin / notional) * 100;

  const handleSlider = (v: number) => { setSliderVal(v); setAmount((available * v / 100).toFixed(2)); };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-[300] flex items-center justify-center bg-black/60 backdrop-blur-sm p-4">
      <div className="w-full max-w-[420px] bg-white dark:bg-[#1a1c22] border border-gray-200 dark:border-slate-800 rounded-lg shadow-2xl overflow-hidden animate-in fade-in zoom-in duration-200">
        <div className="flex items-center justify-between px-6 py-4 border-b border-gray-100 dark:border-slate-800">
           <h3 className="text-lg font-bold dark:text-white">{isAdd ? t.addMargin : t.removeMargin}</h3>
           <button onClick={onClose} className="text-gray-400 hover:text-white transition"><X size={20} /></button>
        </div>
        <div className="p-6 space-y-5">
           <div className="flex flex-col border-b border-gray-100 dark:border-slate-800 pb-3">
              <div className="flex justify-between items-center text-sm mb-1">
                <span className="text-gray-500">{t.contract}</span>
                <span className="font-bold text-[#10B981] font-mono">{pos.symbol} / {pos.side === 'BUY' ? t.long : t.short}</span>
              </div>
              <div className="flex justify-between text-[11px] text-gray-500">
                <span>{t.entryPrice}: <span className="font-mono">{pos.entryPrice.toFixed(2)}</span></span>
                <span>{t.markPrice}: <span className="font-mono">{pos.markPrice.toFixed(2)}</span></span>
              </div>
           </div>

           <div className="space-y-2">
              <div className="flex justify-between text-xs font-bold text-gray-500">
                 <span>{t.amount}</span>
                 <span>{isAdd ? t.avail : t.availExtract}: {available.toLocaleString()} USDC</span>
              </div>
              <div className="relative">
                 <input type="number" value={amount} onChange={e => setAmount(e.target.value)} placeholder={t.amount} className="w-full bg-transparent border border-gray-200 dark:border-slate-700 rounded p-2.5 pr-14 text-sm font-mono focus:border-brand-500 outline-none dark:text-white" />
                 <span className="absolute right-3 top-2.5 text-xs text-gray-500 font-bold">USDC</span>
              </div>
              <div className="pt-2"><CustomSlider value={sliderVal} onChange={handleSlider} theme={theme} /></div>
           </div>

           <div className="space-y-4 pt-2 border-t border-gray-100 dark:border-slate-800">
              <div className="flex justify-between items-center text-xs">
                 <span className="text-gray-500">{t.margin}</span>
                 <div className="flex items-center space-x-3 font-mono font-bold dark:text-white">
                    <span>{pos.margin.toFixed(2)}</span><ArrowRightIcon size={12} className="text-[#10B981]" /><span>{newMargin.toFixed(2)}</span>
                 </div>
              </div>
              <div className="flex justify-between items-center text-xs">
                 <span className="text-gray-500">{t.liqPrice}</span>
                 <div className="flex items-center space-x-3 font-mono font-bold dark:text-white">
                    <span>{pos.liquidationPrice.toFixed(2)}</span><ArrowRightIcon size={12} className="text-[#10B981]" /><span>{newLiq.toFixed(2)}</span>
                 </div>
              </div>
              <div className="flex justify-between items-center text-xs">
                 <span className="text-gray-500">{t.marginRate}</span>
                 <div className="flex items-center space-x-3 font-mono font-bold dark:text-white">
                    <span>{oldMarginRate.toFixed(2)}%</span><ArrowRightIcon size={12} className="text-[#10B981]" /><span>{newMarginRate.toFixed(2)}%</span>
                 </div>
              </div>
           </div>

           <div className="grid grid-cols-2 gap-4 pt-4">
              <button onClick={onClose} className="py-3 bg-gray-400 hover:bg-gray-500 text-white font-bold rounded-lg transition">{t.cancel}</button>
              <button 
                onClick={() => onConfirm(numAmount)} 
                disabled={numAmount <= 0 || numAmount > available}
                className="py-3 bg-[#8B5E14] hover:bg-[#7a5212] text-white font-bold rounded-lg shadow-xl shadow-[#8B5E14]/20 transition disabled:opacity-50 disabled:cursor-not-allowed"
              >
                {t.confirm}
              </button>
           </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Position, Order, Language, MarginMode, OrderType, Theme, OrderSide } from '../types';
import { TRANSLATIONS, INITIAL_MARKET_DATA, MOCK_FUNDING_RECORDS, MOCK_HISTORY_ORDERS, MOCK_TRADE_HISTORY } from '../constants';
import { Edit3, Trash2, X, ChevronDown, Repeat, Filter, PlusCircle, MinusCircle, Info } from 'lucide-react';
import { CustomSlider } from './TradeForm';

interface PositionTableProps {
  positions: Position[];
  orders: Order[];
  assetHistory: any[];
  lang: Language;
  theme: Theme;
  onClosePosition: (id: string, type: OrderType, price?: number, amount?: number) => void;
  onCancelOrder: (id: string) => void;
  onEditMargin: (position: Position, type: 'add' | 'extract') => void;
  onCloseAll: () => void;
  onCancelAll: () => void;
  lastPrice: number;
}

const ThWithTooltip: React.FC<{ label: string; explanation?: string; align?: 'left' | 'right' }> = ({ label, explanation, align = 'left' }) => {
  const [showTooltip, setShowTooltip] = useState(false);
  return (
    <th className={`py-2 px-4 font-semibold text-gray-500 uppercase relative ${align === 'right' ? 'text-right' : 'text-left'}`}>
      <div 
        className={`inline-flex items-center space-x-1 cursor-help border-b border-dashed border-gray-300 dark:border-slate-700 transition-colors hover:border-brand-500 ${align === 'right' ? 'justify-end' : ''}`}
        onMouseEnter={() => setShowTooltip(true)}
        onMouseLeave={() => setShowTooltip(false)}
      >
        <span>{label}</span>
      </div>
      {showTooltip && explanation && (
        <div className={`absolute top-full mb-2 ${align === 'right' ? 'right-0' : 'left-0'} z-[2000] w-64 p-3 bg-white dark:bg-slate-800 border border-gray-200 dark:border-slate-700 rounded-lg shadow-2xl text-xs text-gray-600 dark:text-gray-300 leading-relaxed normal-case animate-in fade-in zoom-in-95 duration-100 ring-1 ring-black/5`}>
          <div className="font-bold text-slate-900 dark:text-white mb-1 flex items-center space-x-1">
            <Info size={12} className="text-brand-500" />
            <span>{label}</span>
          </div>
          {explanation}
        </div>
      )}
    </th>
  );
};

export const PositionTable: React.FC<PositionTableProps> = ({ positions, orders, assetHistory, lang, theme, onClosePosition, onCancelOrder, onEditMargin, onCloseAll, onCancelAll, lastPrice }) => {
  const t = TRANSLATIONS[lang];
  const [activeTab, setActiveTab] = useState<'positions' | 'openOrders' | 'orderHistory' | 'tradeHistory' | 'assetsHistory' | 'fundingHistory'>('positions');
  const [closingPos, setClosingPos] = useState<Position | null>(null);
  const [fundingFilter, setFundingFilter] = useState('all');
  const [showCloseAllModal, setShowCloseAllModal] = useState(false);

  // Dynamic Recent Trades for History
  const [allTrades, setAllTrades] = useState<any[]>([]);

  useEffect(() => {
    setAllTrades(MOCK_TRADE_HISTORY);
  }, []);

  const getTabLabel = (tabId: string) => {
    const label = (t as any)[tabId] || tabId;
    if (tabId === 'positions') return `${label}(${positions.length})`;
    if (tabId === 'openOrders') return `${label}(${orders.length})`;
    return label;
  };

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'completed': return 'text-teal-500 bg-teal-500/10';
      case 'processing': case 'confirming': case 'reviewing': return 'text-amber-500 bg-amber-500/10';
      case 'rejected': case 'failed': return 'text-rose-500 bg-rose-500/10';
      case 'canceled': return 'text-gray-400 bg-gray-100 dark:bg-slate-800';
      case 'filledOrder': return 'text-brand-500 bg-brand-500/10';
      default: return 'text-gray-500 bg-gray-500/10';
    }
  };

  const CloseModal = ({ pos, onClose }: { pos: Position, onClose: () => void }) => {
    const [closeType, setCloseType] = useState<OrderType>(OrderType.MARKET);
    const [closePrice, setClosePrice] = useState<string>(INITIAL_MARKET_DATA.lastPrice.toFixed(2));
    const [closeAmount, setCloseAmount] = useState<string>(pos.size.toString());
    const [unit, setUnit] = useState<'XAU' | 'USDC'>('XAU');
    const [sliderVal, setSliderVal] = useState(100);

    const handleConfirm = () => { 
      const amountNum = parseFloat(closeAmount) || 0;
      const xauAmount = unit === 'XAU' ? amountNum : amountNum / (parseFloat(closePrice) || pos.markPrice);
      onClosePosition(pos.id, closeType, parseFloat(closePrice), xauAmount); 
      onClose(); 
    };

    const handleSlider = (val: number) => { 
      setSliderVal(val);
      const targetXAU = pos.size * (val / 100);
      if (unit === 'XAU') {
        setCloseAmount(targetXAU.toFixed(4));
      } else {
        setCloseAmount((targetXAU * (parseFloat(closePrice) || pos.markPrice)).toFixed(2));
      }
    };

    const amountNum = parseFloat(closeAmount) || 0;
    const estXAU = unit === 'XAU' ? amountNum : amountNum / (parseFloat(closePrice) || pos.markPrice);
    const estPnl = estXAU * ((closeType === OrderType.MARKET ? pos.markPrice : parseFloat(closePrice) || pos.markPrice) - pos.entryPrice);

    return (
      <div className="fixed inset-0 z-[200] flex items-center justify-center bg-black/70 backdrop-blur-sm p-4">
        <div className="w-full max-w-[420px] bg-white dark:bg-[#1a1c22] border border-gray-200 dark:border-slate-800 rounded-lg shadow-2xl overflow-hidden animate-in fade-in zoom-in duration-200">
          <div className="flex items-center justify-between px-6 py-4 border-b border-gray-100 dark:border-slate-800">
            <h3 className="text-lg font-bold dark:text-white">{t.closePos}</h3>
            <button onClick={onClose} className="text-gray-400 hover:text-white transition"><X size={20} /></button>
          </div>
          <div className="p-6 space-y-4">
            <div className="flex flex-col space-y-1">
              <div className="flex justify-between text-sm">
                <span className="text-gray-500">{t.tradingPair}</span>
                <span className="font-bold text-teal-600 font-mono">{pos.symbol} / {pos.side === 'BUY' ? t.long : t.short}</span>
              </div>
              <div className="flex justify-between text-[11px] text-gray-500">
                <span>{t.entryPrice}: <span className="font-mono">{pos.entryPrice.toFixed(2)}</span></span>
                <span>{t.markPrice}: <span className="font-mono">{pos.markPrice.toFixed(2)}</span></span>
              </div>
            </div>

            <div className="grid grid-cols-2 gap-4">
              <div className="space-y-1.5">
                <label className="text-xs text-gray-500">{t.closePrice}</label>
                <input type="number" disabled={closeType === OrderType.MARKET} value={closeType === OrderType.MARKET ? "" : closePrice} onChange={e => setClosePrice(e.target.value)} placeholder={closeType === OrderType.MARKET ? t.market : ""} className="w-full bg-gray-100 dark:bg-slate-800 border border-gray-200 dark:border-slate-700 rounded p-2 text-sm font-mono outline-none dark:text-white" />
              </div>
              <div className="space-y-1.5">
                <label className="text-xs text-gray-500">Mode</label>
                <div onClick={() => setCloseType(prev => prev === OrderType.MARKET ? OrderType.LIMIT : OrderType.MARKET)} className="flex items-center justify-between bg-gray-100 dark:bg-slate-800 border border-gray-200 dark:border-slate-700 rounded p-2 text-sm cursor-pointer dark:text-white">
                  <span className="font-mono">{closeType === OrderType.MARKET ? t.market : t.limit}</span>
                  <Repeat size={14} className="text-gray-500" />
                </div>
              </div>
            </div>

            <div className="space-y-1.5">
              <label className="text-xs text-gray-500">{t.closeAmount}</label>
              <div className="relative">
                <input type="number" value={closeAmount} onChange={e => setCloseAmount(e.target.value)} className="w-full bg-gray-100 dark:bg-slate-800 border border-gray-200 dark:border-slate-700 rounded p-2 pr-16 text-sm font-mono outline-none dark:text-white" />
                <button 
                  onClick={() => setUnit(u => u === 'XAU' ? 'USDC' : 'XAU')}
                  className="absolute right-2 top-1.5 bg-gray-200 dark:bg-slate-700 px-2 py-1 rounded text-[10px] font-bold text-gray-500 flex items-center space-x-1"
                >
                  <span>{unit}</span><Repeat size={8} />
                </button>
              </div>
            </div>

            <div className="pt-2"><CustomSlider value={sliderVal} onChange={handleSlider} theme={theme} /></div>

            <div className="space-y-1 pt-2 border-t border-gray-100 dark:border-slate-800">
              <div className="flex justify-between text-xs text-gray-500"><span>{t.heldAmount}</span><span className="font-mono dark:text-white">{pos.size} XAU</span></div>
              <div className="flex justify-between text-xs text-gray-500 font-bold"><span>{t.estPnl}</span><span className={`font-mono ${estPnl >= 0 ? 'text-teal-600' : 'text-trade-down'}`}>{estPnl.toFixed(2)} USDC</span></div>
            </div>

            <div className="grid grid-cols-2 gap-4 pt-4">
              <button onClick={onClose} className="py-2.5 border border-[#dca85e] text-[#dca85e] rounded font-bold hover:bg-[#dca85e]/5 transition">{t.cancel}</button>
              <button onClick={handleConfirm} className="py-2.5 bg-[#dca85e] text-slate-900 rounded font-bold shadow-lg shadow-[#dca85e]/20 hover:bg-[#c99750] transition">{t.confirm}</button>
            </div>
          </div>
        </div>
      </div>
    );
  };

  const filteredFunding = MOCK_FUNDING_RECORDS.filter(r => fundingFilter === 'all' || r.type === fundingFilter);

  return (
    <div className="flex flex-col h-full bg-white dark:bg-dark-card border-t border-gray-200 dark:border-dark-border overflow-hidden">
      {/* 选项卡头部 - 固定不滚动 */}
      <div className="flex items-center px-4 border-b border-gray-200 dark:border-dark-border shrink-0 bg-white dark:bg-dark-card z-30 overflow-x-auto hide-scrollbar">
        {['positions', 'openOrders', 'orderHistory', 'tradeHistory', 'assetsHistory', 'fundingHistory'].map(tabId => (
          <button 
            key={tabId} 
            onClick={() => setActiveTab(tabId as any)} 
            className={`py-3 px-3 text-sm font-medium border-b-2 transition-all whitespace-nowrap ${activeTab === tabId ? 'border-brand-500 text-brand-500' : 'border-transparent text-gray-500 hover:text-slate-900 dark:hover:text-white'}`}
          >
            {getTabLabel(tabId)}
          </button>
        ))}
        {activeTab === 'positions' && positions.length > 0 && (
          <button 
            onClick={() => setShowCloseAllModal(true)}
            className="ml-auto bg-trade-down/10 text-trade-down border border-trade-down/30 px-3 py-1 rounded text-xs font-bold hover:bg-trade-down hover:text-white transition"
          >
            {t.closeAll}
          </button>
        )}
        {activeTab === 'openOrders' && orders.length > 0 && (
          <button 
            onClick={() => onCancelAll()}
            className="ml-auto bg-slate-100 dark:bg-slate-800 text-gray-500 px-3 py-1 rounded text-xs font-bold hover:bg-slate-200 dark:hover:bg-slate-700 transition"
          >
            {t.cancelAll}
          </button>
        )}
      </div>

      {/* 数据内容滚动区 */}
      <div className="flex-1 overflow-auto relative scroll-smooth custom-scrollbar">
        {activeTab === 'positions' ? (
          <table className="w-full text-left text-xs border-collapse min-w-[1000px]">
            <thead className="sticky top-0 bg-white dark:bg-dark-card z-20 shadow-sm border-b border-gray-200 dark:border-slate-800">
              <tr className="text-gray-500 uppercase bg-gray-50/80 dark:bg-slate-900/80 backdrop-blur-sm">
                <th className="py-2 px-4 font-semibold">{t.symbol}</th>
                <ThWithTooltip label={t.positionValue} explanation={t.explanations.positionValue} />
                <ThWithTooltip label={t.entryPrice} explanation={t.explanations.entryPrice} />
                <ThWithTooltip label={t.markPrice} explanation={t.explanations.markPrice} />
                <ThWithTooltip label={t.liqPrice} explanation={t.explanations.liqPrice} />
                <ThWithTooltip label={t.margin} explanation={t.explanations.margin} />
                <ThWithTooltip label={t.unrealizedPnl} explanation={t.explanations.unrealizedPnl} align="right" />
                <th className="py-2 px-4 font-semibold text-right">{t.action}</th>
              </tr>
            </thead>
            <tbody>
              {positions.map(pos => (
                <tr key={pos.id} className="border-b border-gray-100 dark:border-slate-800/30 hover:bg-gray-50 dark:hover:bg-slate-800/20">
                  <td className="py-3 px-4">
                    <div className="flex flex-col">
                      <span className="font-bold text-slate-900 dark:text-white font-mono text-sm">{pos.symbol}</span>
                      <div className="flex items-center space-x-2">
                        <span className={`font-bold ${pos.side === 'BUY' ? 'text-trade-up' : 'text-trade-down'}`}>{pos.side === 'BUY' ? t.long : t.short}</span>
                        <span className="text-[10px] text-gray-500 font-bold bg-gray-100 dark:bg-slate-800 px-1 rounded">{pos.leverage}x</span>
                      </div>
                    </div>
